    if (!arg || !isdigit(static_cast<unsigned char>(arg[0])) || atoi(arg) > 10000) {
        Out(o, n, "usage: log.rate <lines per source and second, 0 = no limit>");
        return false;
    }
    g_logRate = atoi(arg);
    Out(o, n, "log.rate %d", g_logRate);
