struct W7Hist {
    DWORD tick, voice, channel, emitter, sid;
    int wave, group, kind;
    bool is3d;
    float vol;
    char time[12], name[44], src[56];
    int cat;                                 // 0.22.50: kW8Lara .. kW8Music (the box filters, quick hearing)
    bool loop, fmMute, fmPause, alive;       // 0.22.50: FMOD's own state (start; refreshed while the channel lives)
    float dist;                              // 0.22.50: metres to Lara at the start (-1 = 2D / unknown)
    DWORD first;                             // 0.22.50 (collapsed line): the first start
    int count;                               // 0.22.50 (collapsed line): starts of this wave + source
    float dry, send;                         // 0.22.51 W9: dry mix / the game's reverb send (refreshed while it lives)
    bool aud;                                // 0.22.51 W9: audible incl. the reverb path (W9Audible)
    int rev;                                 // 0.22.52 W10: reverb mark kW9RevNone / On / Muted
    int sub;                                 // 0.22.53 W11: the sub-group (kW8s*; cat = its kind)
};
const int kW7HistCap = 200;
W7Hist g_w7Hist[kW7HistCap];
int g_w7HistHead = 0, g_w7HistN = 0;         // next slot / entries kept (newest = head - 1)
LONG g_w7HistTotal = 0, g_w7HistLines = 0;
struct W7SeenV { DWORD voice, sample, channel; };
const int kW7SeenMax = 512;
W7SeenV g_w7Seen[kW7SeenMax], g_w7SeenNext[kW7SeenMax];
int g_w7SeenN = 0, g_w7SeenNextN = 0;
bool g_w7Baseline = true;                    // the first walk after a switch-on records nothing (voices already playing)
bool g_w7TickGroups = false;
int g_w7TickCats[5] = {0, 0, 0, 0, 0}, g_w7TickGroupN = 0;
bool W7HistWanted() { return g_w7Ok && g_w7History != 0; }
// ---- 0.22.50: the collapsed log lines (under g_snLock; game thread adds / refreshes, render thread copies) ----
const int kW8AggCap = 96;
W7Hist g_w8Agg[kW8AggCap];
int g_w8AggN = 0;
DWORD g_w8AggRefreshAt = 0;
// category, FMOD's own state and the distance of a new start (game thread, W7HistAdd)
void W8HistExtra(const W6Voice &v, int cat, W7Hist &h) {
    h.sub = W8SubOf(h.group, cat, v.wave, v.emitter, nullptr);   // 0.22.53 W11: by group, group 14 also by source
    h.cat = W8SubCat(h.sub);
    DWORD ci = 0, fl = 0, rf = 0, mode = 0;
    h.alive = W8FmOf(v.channel, &ci, &fl, &rf, &mode);
    h.fmMute = h.alive && (fl & 8) != 0;
    h.fmPause = h.alive && ((rf & 0x20) != 0 || (fl & 1) != 0);
    h.loop = h.alive && (mode & 6) != 0;
    W9Levels(v.voice, h.alive ? ci : 0, &h.dry, &h.send);   // 0.22.51 W9
    h.aud = W9Audible(h.alive, h.fmPause, h.fmMute, h.dry, h.send);
    h.rev = h.alive ? W10RevState(v.voice, h.fmMute, h.send) : 0;   // 0.22.52 W10
    h.dist = -1.0f;
    float pos[3], lara[3];
    DWORD player = 0;
    if (h.is3d && ReadFloats(v.voice + 0x30, pos, 3) && DvFinite(pos, 3) && g_playerOk && ReadDword(kPlayerPtr, &player) &&
        player && ReadFloats(player + kInstancePosition, lara, 3) && DvFinite(lara, 3)) {
        const float dx = pos[0] - lara[0], dy = pos[1] - lara[1], dz = pos[2] - lara[2];
        h.dist = sqrtf(dx * dx + dy * dy + dz * dz) / 290.0f;   // = kW7UnitsPerMetre (declared below, Markup-Massstab)
    }
    h.first = h.tick;
    h.count = 1;
}
// same wave (a stream: same name) + same source = one line: count up, newest time, it moves to the top (by tick)
void W8AggAdd(const W7Hist &h) {
    int at = -1, oldest = 0;
    for (int i = 0; i < g_w8AggN; ++i) {
        const W7Hist &a = g_w8Agg[i];
        if (a.wave == h.wave && !strcmp(a.src, h.src) && (h.wave >= 0 || !strcmp(a.name, h.name))) { at = i; break; }
        if (a.tick < g_w8Agg[oldest].tick) oldest = i;
    }
    if (at >= 0) {
        W7Hist &a = g_w8Agg[at];
        const DWORD first = a.first;
        const int count = a.count;
        a = h;
        a.first = first;
        a.count = count + 1;
        return;
    }
    if (g_w8AggN < kW8AggCap) g_w8Agg[g_w8AggN++] = h;
    else g_w8Agg[oldest] = h;                // full: the line not started for the longest time goes
}
// every 200 ms (game thread, W7HistEnd): FMOD's mute / pause / loop of the lines whose channel still lives
void W8AggRefresh() {
    const DWORD now = GetTickCount();
    if (g_w8AggRefreshAt && now - g_w8AggRefreshAt < 200) return;
    g_w8AggRefreshAt = now ? now : 1;
    EnterCriticalSection(&g_snLock);
    for (int i = 0; i < g_w8AggN; ++i) {
        W7Hist &a = g_w8Agg[i];
        if (!a.alive) continue;
        DWORD ci = 0, fl = 0, rf = 0, mode = 0;
        if (!W8FmOf(a.channel, &ci, &fl, &rf, &mode)) { a.alive = false; continue; }   // ended: the last state stays
        a.fmMute = (fl & 8) != 0;
        a.fmPause = (rf & 0x20) != 0 || (fl & 1) != 0;
        a.loop = (mode & 6) != 0;
        W9Levels(a.voice, ci, &a.dry, &a.send);   // 0.22.51 W9: the reverb send follows the voice
        a.aud = W9Audible(true, a.fmPause, a.fmMute, a.dry, a.send);
        a.rev = W10RevState(a.voice, a.fmMute, a.send);   // 0.22.52 W10
    }
    LeaveCriticalSection(&g_snLock);
}
void W7HistBegin(bool hist) {
    g_w7SeenNextN = 0;
    g_w7TickGroups = false;
    if (!hist) { g_w7Baseline = true; g_w7SeenN = 0; }
}
void W7HistAdd(const W6Voice &v) {
    if (!g_w7TickGroups) {                   // once per tick with a new voice (SnReadGroups: game thread, as SnBuild)
        if (!SnCats(g_w7TickCats))
            for (int i = 0; i < 5; ++i) g_w7TickCats[i] = 0;
        g_w7TickGroupN = SnReadGroups();
        g_w7TickGroups = true;
    }
    const bool de = g_qbLang == 0;
    W7Hist h = {};
    int cat = kSnOther;
    DWORD cg = 0, source = 0, srcFlags = 0;
    SnClassify(v.params, g_w7TickCats, g_w7TickGroupN, &h.group, &cat, &cg);
    h.tick = GetTickCount();
    h.voice = v.voice;
    h.channel = v.channel;
    h.emitter = v.emitter;
    h.sid = v.sid;
    h.wave = v.wave;
    h.kind = W7KindOf(h.group, cat);
    h.is3d = ReadDword(v.voice + 0x20, &source) && source && ReadDword(source + 0x18, &srcFlags) && (srcFlags & 0x100) != 0;
    if (!ReadFloats(v.voice + 0x18, &h.vol, 1)) h.vol = -1.0f;
    SYSTEMTIME st;
    GetLocalTime(&st);
    Out(h.time, sizeof(h.time), "%02u:%02u:%02u", st.wHour, st.wMinute, st.wSecond);
    W7VoiceName(v.wave, cat, de, h.name, sizeof(h.name));
    W7VoiceSource(v.emitter, h.kind, v.wave, de, h.src, sizeof(h.src));
    W8HistExtra(v, cat, h);                  // 0.22.50: category, FMOD's mute / pause / loop, distance
    EnterCriticalSection(&g_snLock);
    g_w7Hist[g_w7HistHead] = h;
    g_w7HistHead = (g_w7HistHead + 1) % kW7HistCap;
    if (g_w7HistN < kW7HistCap) ++g_w7HistN;
    W8AggAdd(h);                             // 0.22.50: the collapsed lines (same wave + same source = one line)
    LeaveCriticalSection(&g_snLock);
    const LONG total = InterlockedIncrement(&g_w7HistTotal);
    if (g_w7HistLog && g_w7HistLines < 5000) {
        if (++g_w7HistLines == 5000) Log(1, "snd.start: 5000 lines - further starts are only kept in the history");
        Log(1, "snd.start #%ld: %s w%d s%lu | g%d %s (%s) | %s | %s vol %.2f | voice 0x%08lx ch 0x%08lx emitter 0x%08lx",
            total, h.name, v.wave, v.sid, h.group, W7GroupName(h.group, false), kW7KindEn[h.kind], h.src,
            h.is3d ? "3D" : "2D", static_cast<double>(h.vol), v.voice, v.channel, v.emitter);
    }
}
void W7HistVoice(const W6Voice &v) {
    bool old = false;
    for (int i = 0; i < g_w7SeenN && !old; ++i)
        old = g_w7Seen[i].voice == v.voice && g_w7Seen[i].sample == v.sample && g_w7Seen[i].channel == v.channel;
    if (g_w7SeenNextN < kW7SeenMax) g_w7SeenNext[g_w7SeenNextN++] = {v.voice, v.sample, v.channel};
    if (!old && !g_w7Baseline) W7HistAdd(v);
}
void W7HistEnd(bool hist) {
    if (!hist) return;
    memcpy(g_w7Seen, g_w7SeenNext, sizeof(W7SeenV) * static_cast<size_t>(g_w7SeenNextN));
    g_w7SeenN = g_w7SeenNextN;
    g_w7Baseline = false;
    W8AggRefresh();                          // 0.22.50: FMOD's mute / pause of the collapsed lines (every 200 ms)
}
// ---- end of the 0.22.47 core (bar / overlay / items after "end of 0.22.45 W6") ----

// FMOD's own ChannelI::setMute through the game's handle validate (a stale handle: false, nothing called)
bool W6ChMute(DWORD handle, bool mute) {
    __try {
        DWORD chan = 0;
        if (reinterpret_cast<W6ValidateFn>(kW6ChValidate)(handle, &chan) != 0 || !chan) return false;
        reinterpret_cast<W6ChMuteFn>(kW6ChSetMute)(chan, nullptr, mute ? 1 : 0);
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        InterlockedIncrement(&g_ownExceptions);
        return false;
    }
}
bool W6ChMuted(DWORD handle, bool *muted) {
    *muted = false;
    __try {
        DWORD chan = 0;
        unsigned char b = 0;
        if (reinterpret_cast<W6ValidateFn>(kW6ChValidate)(handle, &chan) != 0 || !chan) return false;
        if (reinterpret_cast<W6ChGetMuteFn>(kW6ChGetMute)(chan, nullptr, &b) != 0) return false;
        *muted = b != 0;
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        InterlockedIncrement(&g_ownExceptions);
        return false;
    }
}
// the emitter of a voice's params (only when the wave sits directly under it: vtable 0x851240 at params - 0x14)
DWORD W6Emitter(DWORD params) {
    DWORD vt = 0;
    if (params < 0x10000 || !ReadDword(params - 0x14, &vt) || vt != kW6EmitterVtbl) return 0;
    return params - 0x14;
}
// group g's node R+0x50 (0 = no such group now)
DWORD W6GroupNode(int g) {
    DWORD table = 0, count = 0, r = 0;
    if (g <= 0 || !ReadDword(kSndGroups, &table) || !table || !ReadDword(kSndGroups + 4, &count) ||
        static_cast<DWORD>(g) >= count || !ReadDword(table + static_cast<DWORD>(g) * 0x84 + 0x64, &r) || !r)
        return 0;
    return r + 0x50;
}
int W6GroupCount() {
    DWORD count = 0;
    return ReadDword(kSndGroups + 4, &count) && count < 4096 ? static_cast<int>(count) : 0;
}
// the voice's node chain (params + 0x50, parent +0x18) passes the group node
bool W6InGroup(DWORD params, DWORD gnode) {
    DWORD node = params ? params + 0x50 : 0;
    for (int depth = 0; gnode && node && depth < 24; ++depth) {
        if (node == gnode) return true;
        DWORD parent = 0;
        if (!ReadDword(node + 0x18, &parent) || parent == node) break;
        node = parent;
    }
    return false;
}
bool W6Match(const W6Rule &r, const W6Voice &v, DWORD gnode) {
    switch (r.kind) {
    case kW6Wave: return v.wave >= 0 && static_cast<DWORD>(v.wave) == r.value;
    case kW6Sound: return v.emitter && v.sid == r.value;
    case kW6Emitter: return v.emitter && v.emitter == r.value;
    case kW6Group:
    case kW6Amb: return W6InGroup(v.params, gnode);
    case kW6Cat: return v.cat >= 0 && static_cast<DWORD>(v.cat) == r.value;   // 0.22.50 (W6VoiceTick classifies)
    case kW6Sub: return v.sub >= 0 && static_cast<DWORD>(v.sub) == r.value;   // 0.22.53 W11
    default: return false;                   // a track has no voice TruMenu can tell apart
    }
}
void W6RuleText(const W6Rule &r, char *o, size_t n) {
    switch (r.kind) {
    case kW6Wave: Out(o, n, "w%lu", r.value); break;
    case kW6Sound: Out(o, n, "s%lu", r.value); break;
    case kW6Emitter: Out(o, n, "e0x%08lx", r.value); break;
    case kW6Group: Out(o, n, "g%lu", r.value); break;
    case kW6Amb: Out(o, n, "ambience"); break;
    case kW6Cat: Out(o, n, "cat:%s", r.value < static_cast<DWORD>(kW8Cats) ? kW8CatKey[r.value] : "?"); break;   // 0.22.50
    case kW6Sub: Out(o, n, "sub:%s", r.value < static_cast<DWORD>(kW8Subs) ? kW8Sub[r.value].key : "?"); break;   // 0.22.53
    default: Out(o, n, "%s", r.name); break;
    }
}
bool W6Same(const W6Rule &a, const W6Rule &b) {
    if (a.kind != b.kind) return false;
    if (a.kind == kW6Track) return !_stricmp(a.name, b.name);
    return a.kind == kW6Amb || a.value == b.value;
}
int W6Find(const W6Rule &r) {
    for (int i = 0; i < g_w6RuleN; ++i)
        if (W6Same(g_w6Rules[i], r)) return i;
    return -1;
}
bool W6Watched(int wave) {
    for (int i = 0; i < g_w6WaveN; ++i)
        if (g_w6WaveIds[i] == wave) return true;
    return false;
}
// a track name a rule stops ('ambience' = the '_amb_' beds, as media.muteambient)
bool W6TrackRuled(const char *name) {
    for (int i = 0; i < g_w6RuleN; ++i) {
        if (g_w6Rules[i].kind == kW6Track && !_stricmp(g_w6Rules[i].name, name)) return true;
        if (g_w6Rules[i].kind == kW6Amb && SndAmbName(name)) return true;
    }
    return false;
}
// 0.22.50: W6EmitterOwner (one walk over every instance per watched-wave start) is gone - W6WaveLine names the source
// through W7VoiceSource (hook E1 first, then the owner list W7OwnBuild, at most once a second while shown)
// one log line per start of a watched wave (wave 10 = ui_drop_04 in the generalbank / the DLC 2 reuse, J-2)
void W6WaveLine(const W6Voice &v) {
    const LONG start = InterlockedIncrement(&g_w6WaveStarts);
    if (g_w6WaveMax > 0 && g_w6WaveLines >= g_w6WaveMax) {
        if (g_w6WaveLines == g_w6WaveMax) {
            ++g_w6WaveLines;
            Log(1, "snd.wave: [Sound] WaveLogMax %d lines reached - further starts are only counted (snd.mutes)",
                g_w6WaveMax);
        }
        return;
    }
    ++g_w6WaveLines;
    char unit[64] = "", emText[200] = "-", obj[200] = "-", where[48] = "";
    CurrentUnit(unit, sizeof(unit));
    int cats[5], group = -1, cat = kSnOther;
    DWORD cg = 0, source = 0, srcFlags = 0, mgr = 0;
    if (!SnCats(cats))
        for (int i = 0; i < 5; ++i) cats[i] = 0;
    SnClassify(v.params, cats, SnReadGroups(), &group, &cat, &cg);
    float vol = -1.0f;
    ReadFloats(v.voice + 0x18, &vol, 1);
    const bool is3d = ReadDword(v.voice + 0x20, &source) && source && ReadDword(source + 0x18, &srcFlags) &&
                      (srcFlags & 0x100) != 0;
    bool playing = false;
    SnFmBool(kFmChIsPlaying, v.channel, &playing);
    if (v.emitter) {
        Out(emText, sizeof(emText), "0x%08lx sound s%lu (SoundPlex section)", v.emitter, v.sid);
        // 0.22.50: no walk over every instance per start any more (W6EmitterOwner) - hook E1 / the throttled owner list
        char src[64];
        W7VoiceSource(v.emitter, W7KindOf(group, cat), v.wave, false, src, sizeof(src));
        W8EmRec er;
        if (W8EmitterInst(v.emitter, &er))
            Out(obj, sizeof(obj), "%s (object %d, intro %ld, inst 0x%08lx, hook E1 anim event)", src, er.objectId, er.intro,
                er.inst);
        else
            Out(obj, sizeof(obj), "%s (owner list of [inst+0x248]%s)", src, W8Visible() ? "" : ", walked only while the box "
                "or the monitor is shown");
        where[0] = 0;
    } else {
        Out(emText, sizeof(emText), "? (params 0x%08lx not under an emitter: inner SoundPlex node)", v.params);
    }
    DWORD e[6] = {0, 0, 0, 0, 0, 0};
    if (ReadDword(kSnWaveMgr, &mgr) && mgr)
        for (int i = 0; i < 6; ++i) ReadDword(mgr + 8 + static_cast<DWORD>(v.wave) * 0x18 + static_cast<DWORD>(i) * 4, &e[i]);
    Log(1, "snd.wave %d START #%ld: unit %s; voice 0x%08lx ch 0x%08lx, %s g%d, vol %.2f, %s, %s; emitter %s; object %s; "
        "wave entry %08lx %08lx %08lx %08lx %08lx %08lx", v.wave, start, unit[0] ? unit : "-", v.voice, v.channel,
        kSnCatEn[cat], group, static_cast<double>(vol), is3d ? "3D" : "2D", playing ? "playing" : "not playing yet",
        emText, obj, e[0], e[1], e[2], e[3], e[4], e[5]);
}
// 0.22.50: the groups a category rule mutes as a whole - the largest sub-trees (parent = entry +0x68, SgParent) whose
// groups all belong to the category; a group with a child of another category (57 PDA holds 70 Lara's hints, 4 the
// effects slider holds every effect) is not muted as a group - its own voices are muted per channel (W6VoiceTick)
// 0.22.53 W11: the same for a sub-group (sub = true: value = kW8s*); group 14 is never pure (Lara's sounds by source)
int W8CatPureGroups(int cat, int *out, int max, bool sub = false) {
    const int n = W6GroupCount() < 80 ? W6GroupCount() : 80;
    bool impure[80] = {};
    int parent[80];
    for (int g = 0; g < n; ++g) parent[g] = SgParent(g);
    for (int g = 0; g < n; ++g) {
        if (g != 14 && (sub ? kW8GroupSub[g] == cat : W8SubCat(kW8GroupSub[g]) == cat)) continue;
        impure[g] = true;
        for (int p = parent[g], guard = 0; p >= 0 && p < n && p != g && guard < 16; p = parent[p], ++guard) impure[p] = true;
    }
    int k = 0;
    for (int g = 1; g < n && k < max; ++g) {   // never the root
        if (impure[g]) continue;
        const int p = parent[g];
        if (p > 0 && p < n && p != g && !impure[p]) continue;   // its parent is muted as a whole already
        out[k++] = g;
    }
    return k;
}
// group / ambience rules: FMOD's ChannelGroupI::setMute on the group's channel group (as media.mutemusic)
void W6CgTick() {
    int want[kW6CgMax], wn = 0;
    for (int i = 0; i < g_w6RuleN && wn < kW6CgMax; ++i)
        if (g_w6Rules[i].kind == kW6Group) want[wn++] = static_cast<int>(g_w6Rules[i].value);
        else if (g_w6Rules[i].kind == kW6Amb) want[wn++] = kW6AmbGroup;
        else if (g_w6Rules[i].kind == kW6Cat)    // 0.22.50: the category's whole sub-trees (reach channels outside the pool)
            wn += W8CatPureGroups(static_cast<int>(g_w6Rules[i].value), want + wn, kW6CgMax - wn);
        else if (g_w6Rules[i].kind == kW6Sub)    // 0.22.53 W11: the sub-group's whole sub-trees
            wn += W8CatPureGroups(static_cast<int>(g_w6Rules[i].value), want + wn, kW6CgMax - wn, true);
    if (W7SonarMode() == 2 && wn < kW6CgMax) want[wn++] = kW7SonarGroup;   // 0.22.47 fallback: the whole group 57
    for (int k = 0; k < wn; ++k) {
        int r = -1;
        for (int i = 0; i < g_w6CgN; ++i)
            if (g_w6Cg[i].group == want[k]) r = i;
        if (r < 0) {
            if (g_w6CgN >= kW6CgMax) continue;
            r = g_w6CgN++;
            g_w6Cg[r] = {want[k], 0, false};
        }
        W6Cg &c = g_w6Cg[r];
        const DWORD cg = SmGroupCg(c.group);
        if (!cg) continue;                    // no FMOD / no group yet (loading): the record stays
        if (SmMuted(cg)) {
            if (c.cg != cg) { c.cg = cg; c.ours = false; }   // muted by someone else (media.mutemusic): never undone
            continue;
        }
        const bool again = c.ours && c.cg && c.cg != cg;
        if (!SmSetMute(cg, true)) continue;
        Log(1, "snd.mute: %sgroup %d muted (FMOD channel group 0x%08lx, ChannelGroupI::setMute 0x7c48cd) - volumes "
            "untouched", again ? "new (level load) " : "", c.group, cg);
        c.cg = cg;
        c.ours = true;
    }
    for (int i = 0; i < g_w6CgN;) {
        bool keep = false;
        for (int k = 0; k < wn; ++k)
            if (want[k] == g_w6Cg[i].group) keep = true;
        if (keep) { ++i; continue; }
        const W6Cg c = g_w6Cg[i];
        if (c.ours) {
            const DWORD cg = SmGroupCg(c.group);
            const bool done = cg && cg == c.cg && SmMuted(cg) && SmSetMute(cg, false);
            Log(1, "snd.mute: group %d %s", c.group, done ? "unmuted (setMute 0)" : "not unmuted - rebuilt by a level load "
                "(the new channel group was never muted)");
        }
        g_w6Cg[i] = g_w6Cg[--g_w6CgN];
    }
}
// track / ambience rules: the game's srmusic stop for every slot whose request or current track a rule names
void W6TrackTick() {
    if (!g_musicOk) return;
    for (int s = 0; s < kMusicSlotCount; ++s) {
        const DWORD slot = kMusicSlots + static_cast<DWORD>(s) * kMusicSlotSize;
        char want[64], cur[64];
        if (!ReadString(slot + 0x100, want, sizeof(want))) want[0] = 0;
        if (!ReadString(slot, cur, sizeof(cur))) cur[0] = 0;
        const bool wantHit = want[0] && W6TrackRuled(want), curHit = cur[0] && W6TrackRuled(cur);
        if (!wantHit && !curHit) {
            if (!want[0] && !cur[0]) g_w6TrDone[s][0] = 0;   // a new start of the same track counts again
            continue;
        }
        const char *name = wantHit ? want : cur;
        if (!_stricmp(g_w6TrDone[s], name)) continue;
        strncpy_s(g_w6TrDone[s], sizeof(g_w6TrDone[s]), name, _TRUNCATE);
        strncpy_s(g_w6Stopped[s], sizeof(g_w6Stopped[s]), name, _TRUNCATE);
        const bool ok = SndStopSlot(s);
        Log(1, "snd.mute: srmusic slot %d '%s' %s (SRMUSIC_LoadMusic(%d, NULL, %d, 0) as the stop native 0x4aa490)", s, name,
            ok ? "stopped" : "stop faulted", s, g_musicFade);
    }
}
// a removed track / ambience rule: the stopped tracks no rule names any more come back where media.music.play may run
void W6TrackBack() {
    if (!g_musicOk) return;
    for (int s = 0; s < kMusicSlotCount; ++s) {
        if (!g_w6Stopped[s][0] || W6TrackRuled(g_w6Stopped[s])) continue;
        const DWORD slot = kMusicSlots + static_cast<DWORD>(s) * kMusicSlotSize;
        char want[64], cur[64], why[160] = "";
        if (!ReadString(slot + 0x100, want, sizeof(want))) want[0] = 0;
        if (!ReadString(slot, cur, sizeof(cur))) cur[0] = 0;
        strncpy_s(g_w6Back[s], sizeof(g_w6Back[s]), g_w6Stopped[s], _TRUNCATE);
        g_w6Stopped[s][0] = 0;
        g_w6TrDone[s][0] = 0;
        if (want[0] || cur[0]) {
            Log(1, "snd.mute: srmusic slot %d '%s' not restarted - the slot holds '%s' now", s, g_w6Back[s], want[0] ? want : cur);
            continue;
        }
        if (!MusicPlace(why, sizeof(why))) {
            Log(1, "snd.mute: srmusic slot %d '%s' not restarted (%s) - the unit starts it again at its next start", s,
                g_w6Back[s], why);
            continue;
        }
        __try {
            reinterpret_cast<MusicLoadFn>(kMusicLoad)(s, g_w6Back[s], g_musicFade, g_musicFade);
            Log(1, "snd.mute: srmusic slot %d '%s' back (SRMUSIC_LoadMusic(%d, name, %d, %d) as the unit start 0x5b2211)", s,
                g_w6Back[s], s, g_musicFade, g_musicFade);
        } __except (EXCEPTION_EXECUTE_HANDLER) {
            InterlockedIncrement(&g_ownExceptions);
        }
    }
}
// 0.22.50: the used FMOD channels the pool never sees (oscillator / other DSP channels, SystemI +0x150): muted through
// their own handle (ChannelI +0x70, the validator + setMute as every W6 channel) by the category rules and the solo (a
// wave / emitter solo mutes every such channel - it has no wave); the common "gone" loop of W6VoiceTick unmutes them
LONG g_w8ExtraMuted = 0, g_w8ExtraLines = 0;
void W8ExtraMutes(const DWORD *pool, int poolN, int groups, bool catRule) {
    const DWORD soloCg = g_w6SoloOn && g_w6Solo.kind == kW6Group ? SmGroupCg(static_cast<int>(g_w6Solo.value))
                       : g_w6SoloOn && g_w6Solo.kind == kW6Amb ? SmGroupCg(kW6AmbGroup) : 0;
    W8ForUsed([&](DWORD ci, DWORD h, DWORD fl, DWORD) {
        for (int i = 0; i < poolN; ++i)
            if (pool[i] == h) return;            // a pool voice: W6VoiceTick's own path
        DWORD cg = 0;
        ReadDword(ci + 0x8c, &cg);
        const int g = W8GroupOfCg(cg, groups);
        const int sub = g >= 0 && g < 80 ? kW8GroupSub[g] : kW8sWoDefault;   // 0.22.53 W11: no source outside the pool
        const int cat = W8SubCat(sub);
        bool want = false;
        for (int i = 0; catRule && !want && i < g_w6RuleN; ++i)
            want = (g_w6Rules[i].kind == kW6Cat && g_w6Rules[i].value == static_cast<DWORD>(cat)) ||
                   (g_w6Rules[i].kind == kW6Sub && g_w6Rules[i].value == static_cast<DWORD>(sub));
        if (!want && g_w6SoloOn) {
            bool keep = (g_w6Solo.kind == kW6Cat && g_w6Solo.value == static_cast<DWORD>(cat)) ||
                        (g_w6Solo.kind == kW6Sub && g_w6Solo.value == static_cast<DWORD>(sub));
            for (DWORD c = cg, depth = 0; soloCg && c && depth < 16 && !keep; ++depth) {
                keep = c == soloCg;
                DWORD p = 0;
                if (!ReadDword(c + 0x1c, &p) || p == c) break;
                c = p;
            }
            want = !keep;
        }
        int r = -1;
        for (int i = 0; i < g_w6ChanN; ++i)
            if (!g_w6Chan[i].voice && g_w6Chan[i].channel == h) r = i;
        if (want && r < 0) {
            if (fl & 2) return;                  // its own mute bit is set by someone else: not ours
            if (g_w6ChanN < kW6ChanMax && W6ChMute(h, true)) {
                g_w6Chan[g_w6ChanN++] = {0, h, true};
                ++g_w6ChMutes;
                ++g_w8ExtraMuted;
                if (++g_w8ExtraLines <= 40)
                    Log(1, "snd.mute: a channel outside the voice pool (Fremdkanal / DSP) muted - handle 0x%08lx, ChannelI "
                        "0x%08lx, g%d (ChannelI::setMute 0x7c92b5 through its own handle +0x70)", h, ci, g);
            } else {
                ++g_w6ChFails;
            }
        } else if (want) {
            g_w6Chan[r].seen = true;
        } else if (r >= 0) {
            W6ChMute(h, false);
            g_w6Chan[r] = g_w6Chan[--g_w6ChanN];
        }
    });
}
// the voice pool once: wave log + the per-channel mutes of the wave / sound / emitter rules and the solo
void W6VoiceTick(bool watch) {
    for (int i = 0; i < g_w6ChanN; ++i) g_w6Chan[i].seen = false;
    const bool sonar = W7SonarMode() == 1;   // 0.22.47: "Sonar-Ton aus" = the sonar waves per channel, as a wave rule
    bool catRule = false;                    // 0.22.50: a category rule / solo needs each voice's category
    bool laraRule = false;                   // 0.22.53 W11: a Lara / Waffen rule needs the source of group-14 voices
    auto laraSide = [](const W6Rule &r) {
        return (r.kind == kW6Cat && (r.value == static_cast<DWORD>(kW8Lara) || r.value == static_cast<DWORD>(kW8Weapon) ||
                                     r.value == static_cast<DWORD>(kW8World))) ||
               (r.kind == kW6Sub && (r.value == static_cast<DWORD>(kW8sLaraGear) ||
                                     r.value == static_cast<DWORD>(kW8sWpLara14) || r.value == static_cast<DWORD>(kW8sWoDefault)));
    };
    for (int i = 0; i < g_w6RuleN; ++i) {
        catRule = catRule || g_w6Rules[i].kind == kW6Cat || g_w6Rules[i].kind == kW6Sub;
        laraRule = laraRule || laraSide(g_w6Rules[i]);
    }
    const bool catSolo = g_w6SoloOn && (g_w6Solo.kind == kW6Cat || g_w6Solo.kind == kW6Sub);
    g_w8NeedOwners = laraRule || (catSolo && laraSide(g_w6Solo));
    const bool perVoice = g_w6SoloOn != 0 || sonar || catRule || [] {
        for (int i = 0; i < g_w6RuleN; ++i)
            if (g_w6Rules[i].kind == kW6Wave || g_w6Rules[i].kind == kW6Sound || g_w6Rules[i].kind == kW6Emitter) return true;
        return false;
    }();
    const bool hist = W7HistWanted();        // 0.22.47: the start history ([Sound] History)
    DWORD soloNode = 0;
    if (g_w6SoloOn && g_w6Solo.kind == kW6Group) soloNode = W6GroupNode(static_cast<int>(g_w6Solo.value));
    if (g_w6SoloOn && g_w6Solo.kind == kW6Amb) soloNode = W6GroupNode(kW6AmbGroup);
    int tcats[5] = {0, 0, 0, 0, 0}, tgroups = 0;
    if (catRule || catSolo || g_w6SoloOn) {  // the groups of this tick (SnClassify / W8GroupOfCg), game thread
        if (!SnCats(tcats))
            for (int i = 0; i < 5; ++i) tcats[i] = 0;
        tgroups = SnReadGroups();
    }
    static DWORD poolCh[1024];               // 0.22.50: the pool's channel handles (the rest of the used list = extras)
    int poolN = 0;
    DWORD node = 0, end = 0;
    int seenNew = 0;
    W7HistBegin(hist);
    if ((perVoice || watch || hist || g_w6ChanN) && ReadDword(kSnPool + 8, &node) && ReadDword(kSnPoolEnd, &end)) {
        for (int steps = 0; node && node != end && steps < 1024; ++steps) {
            DWORD next = 0;
            W6Voice v = {};
            v.cat = v.sub = -1;
            if (!ReadDword(node + 4, &v.voice) || !ReadDword(node, &next)) break;
            node = next;
            if (!v.voice || !ReadDword(v.voice + 4, &v.channel) || !ReadDword(v.voice + 0x10, &v.sample) ||
                !ReadDword(v.voice + 0x1c, &v.params))
                continue;
            if (poolN < 1024) poolCh[poolN++] = v.channel;
            v.wave = W7Wave(v.sample);       // 0.22.47: sample = wave entry +4 (0x591348), mapped back to the id
            v.emitter = W7Emitter(v.params);   // 0.22.47: voice +0x1c is the node's own 0x90 object, +0x74 = its params
            const DWORD hooked = W8VoiceEmitter(v.voice, v.channel);   // 0.22.50: the wave node's own emitter (V1)
            if (hooked) v.emitter = hooked;
            if (v.emitter) ReadDword(v.emitter + 0xc, &v.sid);
            if (catRule || catSolo) {        // 0.22.50: the voice's category, kept per voice when the hook record exists
                W8VoiceRec *rec = W8VoiceRecOf(v.voice, v.channel);
                if (rec && rec->sub >= 0) {  // 0.22.53 W11: the sub-group (its kind follows); kept only when final
                    v.sub = rec->sub;
                } else {
                    int g = -1, c = kSnOther;
                    DWORD cg = 0;
                    bool final = true;
                    SnClassify(v.params, tcats, tgroups, &g, &c, &cg);
                    v.sub = W8SubOf(g, c, v.wave, v.emitter, &final);
                    if (rec && final) rec->sub = v.sub;
                }
                v.cat = W8SubCat(v.sub);
            }
            if (hist) W7HistVoice(v);         // 0.22.47: a new (voice, sample, channel) = one history entry
            if (watch && v.wave >= 0 && W6Watched(v.wave)) {
                bool old = false;
                for (int i = 0; i < g_w6SeenN; ++i)
                    if (g_w6Seen[i].voice == v.voice && g_w6Seen[i].sample == v.sample &&
                        g_w6Seen[i].channel == v.channel)
                        old = true;
                if (seenNew < 64) g_w6SeenNew[seenNew++] = {v.voice, v.sample, v.channel};
                if (!old) W6WaveLine(v);
            }
            bool want = false;
            for (int i = 0; perVoice && !want && i < g_w6RuleN; ++i) {
                const int k = g_w6Rules[i].kind;
                if ((k == kW6Wave || k == kW6Sound || k == kW6Emitter || k == kW6Cat || k == kW6Sub) &&
                    W6Match(g_w6Rules[i], v, 0))
                    want = true;                 // 0.22.50: kW6Cat per channel too (groups shared with another category)
            }
            if (!want && g_w6SoloOn && !W6Match(g_w6Solo, v, soloNode)) want = true;
            if (!want && sonar && W7SonarWave(v.wave)) want = true;   // 0.22.47 [Sound] SonarMute 1 / SonarWaves
            int r = -1;
            for (int i = 0; i < g_w6ChanN; ++i)
                if (g_w6Chan[i].voice == v.voice && g_w6Chan[i].channel == v.channel) r = i;
            if (want && r < 0) {
                bool already = false;
                if (W6ChMuted(v.channel, &already) && already) continue;   // muted by someone else: not ours
                if (g_w6ChanN < kW6ChanMax && W6ChMute(v.channel, true)) {
                    g_w6Chan[g_w6ChanN++] = {v.voice, v.channel, true};
                    ++g_w6ChMutes;
                    Log(2, "snd.mute: voice 0x%08lx ch 0x%08lx wave %d sound s%lu muted (ChannelI::setMute 0x7c92b5)",
                        v.voice, v.channel, v.wave, v.sid);
                } else {
                    ++g_w6ChFails;
                }
            } else if (want) {
                g_w6Chan[r].seen = true;
            } else if (r >= 0) {
                W6ChMute(v.channel, false);
                g_w6Chan[r] = g_w6Chan[--g_w6ChanN];
            }
        }
    }
    if (catRule || g_w6SoloOn) W8ExtraMutes(poolCh, poolN, tgroups, catRule);   // 0.22.50: channels outside the pool
    for (int i = 0; i < g_w6ChanN;) {             // gone from the pool: unmute the handle (a stale one is refused)
        if (g_w6Chan[i].seen) { ++i; continue; }
        W6ChMute(g_w6Chan[i].channel, false);
        g_w6Chan[i] = g_w6Chan[--g_w6ChanN];
    }
    memcpy(g_w6Seen, g_w6SeenNew, sizeof(W6Seen) * static_cast<size_t>(seenNew));
    g_w6SeenN = seenNew;
    W7HistEnd(hist);
}
// 0.22.53 W11: what Stumm / Solo silences, for "Filter folgt Stumm" in the box (render thread reads under g_snLock)
void W8PublishMute() {
    W8MuteState m = {0, 0, -1, 0, g_w6SoloOn != 0};
    for (int i = 0; i < g_w6RuleN; ++i) {
        const W6Rule &r = g_w6Rules[i];
        if (r.kind == kW6Cat && r.value < static_cast<DWORD>(kW8Cats)) m.catMuted |= 1u << r.value;
        if (r.kind == kW6Sub && r.value < static_cast<DWORD>(kW8Subs)) m.subMuted |= 1ull << r.value;
    }
    if (g_sndMuteMusic) m.catMuted |= 1u << kW8Music;   // "Musik aus" = Stumm: Musik
    if (m.soloOn) { m.soloKind = g_w6Solo.kind; m.soloValue = g_w6Solo.value; }
    EnterCriticalSection(&g_snLock);
    g_w8Mute = m;
    LeaveCriticalSection(&g_snLock);
}
// true = Stumm / Solo silences a line of this kind / sub-group / wave / section / emitter / group (the solo: every line
// that does not match it) - the box's "Filter folgt Stumm"
bool W8MutedByTree(const W8MuteState &m, int cat, int sub, int wave, DWORD sid, DWORD emitter, int group) {
    if (cat >= 0 && cat < kW8Cats && (m.catMuted & (1u << cat))) return true;
    if (sub >= 0 && sub < kW8Subs && (m.subMuted & (1ull << sub))) return true;
    if (!m.soloOn) return false;
    switch (m.soloKind) {
    case kW6Cat: return static_cast<DWORD>(cat) != m.soloValue;
    case kW6Sub: return static_cast<DWORD>(sub) != m.soloValue;
    case kW6Wave: return wave < 0 || static_cast<DWORD>(wave) != m.soloValue;
    case kW6Sound: return sid != m.soloValue;
    case kW6Emitter: return emitter != m.soloValue;
    case kW6Group: return group != static_cast<int>(m.soloValue);   // display: the group itself (no sub-tree walk)
    default: return false;
    }
}
// PadHook (SnTick, game thread, every poll): cheap while no rule is set and the wave log is off
void W6Tick() {
    if (!g_w6Ok) return;
    W8PublishMute();                         // 0.22.53 W11
    if (InterlockedExchange(&g_w6BackPending, 0)) W6TrackBack();            // a removed track / ambience rule
    const bool watch = g_w6WaveLog && g_w6WaveN > 0;
    if (!watch && !g_w6RuleN && !g_w6SoloOn && !g_w6ChanN && !g_w6CgN && !W7SonarMode() && !W7HistWanted()) return;
    const DWORD now = GetTickCount();
    if (now == g_w6LastTick) return;
    g_w6LastTick = now;
    W6CgTick();
    W6TrackTick();
    W6VoiceTick(watch);
}
// "<target>": w<id> / <id> wave, s<id> SoundPlex section of the emitter, e<hex> emitter, g<n> group, ambience,
// or a srmusic track name (TruMenu.media.txt or a slot now)
bool W6Parse(const char *t, W6Rule *r, char *o, size_t n) {
    memset(r, 0, sizeof(*r));
    if (!_stricmp(t, "ambience") || !_stricmp(t, "amb") || !_stricmp(t, "umgebung")) { r->kind = kW6Amb; return true; }
    if (!_strnicmp(t, "cat:", 4)) {          // 0.22.50: a category of the log box (snd.catmute / snd.catsolo)
        const int c = W8CatFind(t + 4);
        if (c < 0) {
            Out(o, n, "'%s': cat:<lara|weapons|enemies|world|objects|ui|speech|music>", t);
            return false;
        }
        r->kind = kW6Cat;
        r->value = static_cast<DWORD>(c);
        return true;
    }
    if (!_strnicmp(t, "sub:", 4)) {          // 0.22.53 W11: a sub-group of the log box (snd.hear <sub-group>)
        const int s = W8SubFind(t + 4);
        if (s < 0) {
            Out(o, n, "'%s': sub:<sub-group key> (snd.hear lists them: lara_voice, wp_shot, ...)", t);
            return false;
        }
        r->kind = kW6Sub;
        r->value = static_cast<DWORD>(s);
        return true;
    }
    const char c = static_cast<char>(tolower(static_cast<unsigned char>(t[0])));
    const bool digits = t[0] >= '0' && t[0] <= '9';
    if (digits || ((c == 'w' || c == 's' || c == 'g') && t[1] >= '0' && t[1] <= '9')) {
        char *end = nullptr;
        const unsigned long v = strtoul(digits ? t : t + 1, &end, 10);
        if (!end || *end) { Out(o, n, "'%s': a number after w / s / g (decimal)", t); return false; }
        r->value = v;
        r->kind = digits || c == 'w' ? kW6Wave : c == 's' ? kW6Sound : kW6Group;
        if (r->kind == kW6Wave && v >= 0x1400) { Out(o, n, "wave %lu: the wave table has 0x1400 = 5120 entries", v); return false; }
        if (r->kind == kW6Sound && (v == 0 || v >= 0x8000)) { Out(o, n, "s%lu: a SoundPlex section id is 1 .. 32767", v); return false; }
        if (r->kind == kW6Group) {
            const int count = W6GroupCount();
            if (v == 0) { Out(o, n, "g0 is the root group (everything) - use snd.solo for 'all but one'"); return false; }
            if (!count || v >= static_cast<unsigned long>(count)) {
                Out(o, n, "g%lu: no such sound group now (%d groups)", v, count);
                return false;
            }
        }
        return true;
    }
    if (c == 'e' && t[1]) {
        char *end = nullptr;
        const unsigned long v = strtoul(t + 1, &end, 16);
        if (!end || *end || !v) { Out(o, n, "'%s': e<hex address> of an emitter (snd.now)", t); return false; }
        if (W6Emitter(v + 0x14) != v) { Out(o, n, "e0x%08lx is no emitter now (vtable 0x851240) - snd.now lists them", v); return false; }
        r->kind = kW6Emitter;
        r->value = v;
        return true;
    }
    for (const char *p = t; *p; ++p)
        if (!isalnum(static_cast<unsigned char>(*p)) && *p != '_') {
            Out(o, n, "'%s': not a target - w<id>, s<id>, e<hex>, g<n>, ambience, music or a music track name", t);
            return false;
        }
    bool known = g_mediaCount >= 0 && MediaFind("music", t) != nullptr;
    for (int s = 0; !known && g_musicOk && s < kMusicSlotCount; ++s) {
        char cur[64] = "", req[64] = "";
        const DWORD slot = kMusicSlots + static_cast<DWORD>(s) * kMusicSlotSize;
        ReadString(slot, cur, sizeof(cur));
        ReadString(slot + 0x100, req, sizeof(req));
        known = !_stricmp(cur, t) || !_stricmp(req, t);
    }
    if (!known) {
        Out(o, n, "'%s': no such music track (TruMenu.media.txt%s, srmusic slots) - w<id>, s<id>, e<hex>, g<n>, ambience",
            t, g_mediaCount < 0 ? " missing" : "");
        return false;
    }
    r->kind = kW6Track;
    strncpy_s(r->name, sizeof(r->name), t, _TRUNCATE);
    return true;
}
bool W6Gate(char *o, size_t n) {
    if (!g_w6Ok) { Out(o, n, "disabled: pre-check failed (%s)", g_w6Why); return false; }
    return true;
}
// a rule changed: on the game thread at once, else (the request ran from the Present hook) with the next poll
void W6Apply() {
    g_w6LastTick = 0;
    if (GetCurrentThreadId() == g_snGameThread) W6Tick();
}
void W6Clear() {
    bool amb = false;                        // 0.22.50 C: "alles zurueck" also ends the kept "Ambient aus"
    for (int i = 0; i < g_w6RuleN; ++i) amb = amb || g_w6Rules[i].kind == kW6Amb;
    if (amb) IniKeep("Media", "MuteAmbient", "0");
    g_w6RuleN = 0;
    g_w6SoloOn = 0;
    InterlockedExchange(&g_w6BackPending, 1);
    W6Apply();                               // unmutes every channel / group TruMenu muted
}
void ValW6Mutes(char *o, size_t n) {
    if (!g_w6Ok) { Out(o, n, "n/a (%s)", g_w6Why); return; }
    size_t used = 0;
    o[0] = 0;
    LabelAdd(o, n, &used, "rules %d:", g_w6RuleN);
    for (int i = 0; i < g_w6RuleN; ++i) {
        char t[72];
        W6RuleText(g_w6Rules[i], t, sizeof(t));
        LabelAdd(o, n, &used, " %s", t);
    }
    char solo[72] = "off";
    if (g_w6SoloOn) W6RuleText(g_w6Solo, solo, sizeof(solo));
    LabelAdd(o, n, &used, "; solo %s; channels muted now %d (%ld mutes, %ld refused); groups", solo, g_w6ChanN,
             g_w6ChMutes, g_w6ChFails);
    for (int i = 0; i < g_w6CgN; ++i)
        LabelAdd(o, n, &used, " g%d%s", g_w6Cg[i].group, g_w6Cg[i].ours ? "" : " (not ours)");
    if (!g_w6CgN) LabelAdd(o, n, &used, " -");
    LabelAdd(o, n, &used, "; tracks stopped");
    int stopped = 0;
    for (int s = 0; s < kMusicSlotCount; ++s)
        if (g_w6Stopped[s][0]) { LabelAdd(o, n, &used, " %d:%s", s, g_w6Stopped[s]); ++stopped; }
    if (!stopped) LabelAdd(o, n, &used, " -");
    LabelAdd(o, n, &used, "; wave log %s", g_w6WaveLog ? "on" : "off");
    for (int i = 0; g_w6WaveLog && i < g_w6WaveN; ++i) LabelAdd(o, n, &used, " w%d", g_w6WaveIds[i]);
    LabelAdd(o, n, &used, " (%ld starts, %ld lines)", g_w6WaveStarts, g_w6WaveLines);
    const int sm = W7SonarMode();            // 0.22.47: the persistent sonar switch ([Sound] SonarMute)
    LabelAdd(o, n, &used, "; sonar %s", sm == 1 ? "waves" : sm == 2 ? "group 57" : "off");
    for (int i = 0; sm == 1 && i < g_w7SonarN; ++i) LabelAdd(o, n, &used, " w%d", g_w7SonarWaves[i]);
}
// snd.mute <target> [1|0] (no value = toggle); snd.mute all 0 = every rule and the solo off; snd.mute music = music.mute
bool RunW6Mute(const char *arg, char *o, size_t n) {
    char t[72] = "";
    const char *v = TestWord(arg ? arg : "", t, sizeof(t));
    if (!t[0]) {
        Out(o, n, "usage: snd.mute <w<id>|<id>|s<id>|e<hex>|g<n>|ambience|music|track|all> [1|0] (snd.now, snd.mutes)");
        return false;
    }
    if (v[0] && strcmp(v, "0") && strcmp(v, "1") && _stricmp(v, "on") && _stricmp(v, "off")) {
        Out(o, n, "snd.mute %s: value '%s' is not 1 / 0 / on / off", t, v);
        return false;
    }
    if (!_stricmp(t, "music") || !_stricmp(t, "musik")) return RunMuteMusic(v, o, n);   // the 0.20.1 music mute
    if (!W6Gate(o, n)) return false;
    if (!_stricmp(t, "all")) {
        if (v[0] && BoolArg(v, false)) { Out(o, n, "snd.mute all 1: not a rule - use snd.solo <target>"); return false; }
        const int rules = g_w6RuleN, solo = g_w6SoloOn;
        W6Clear();
        Log(1, "snd.mute all 0 (src=%s): %d rule(s)%s removed - TruMenu's channel / group mutes undone", ShotSource("snd.mute"),
            rules, solo ? " and the solo" : "");
        Out(o, n, "snd.mute: all off (%d rule(s)%s)", rules, solo ? " + solo" : "");
        return true;
    }
    W6Rule r;
    if (!W6Parse(t, &r, o, n)) return false;
    const int idx = W6Find(r);
    const bool on = v[0] ? BoolArg(v, false) : idx < 0;
    char text[72];
    W6RuleText(r, text, sizeof(text));
    if (on) {
        if (idx >= 0) { Out(o, n, "snd.mute %s: already muted", text); return true; }
        if (g_w6RuleN >= kW6RuleMax) { Out(o, n, "snd.mute: %d rules is the limit - snd.mute all 0 first", kW6RuleMax); return false; }
        g_w6Rules[g_w6RuleN++] = r;
    } else {
        if (idx < 0) { Out(o, n, "snd.mute %s: was not muted", text); return true; }
        g_w6Rules[idx] = g_w6Rules[--g_w6RuleN];
        if (r.kind == kW6Track || r.kind == kW6Amb) InterlockedExchange(&g_w6BackPending, 1);   // the way back
    }
    if (r.kind == kW6Amb) IniKeep("Media", "MuteAmbient", on ? "1" : "0");   // 0.22.50 C: one "Ambient aus", kept
    W6Apply();                               // at once on the game thread
    Out(o, n, "snd.mute %s %d%s", text, on ? 1 : 0, !on && (r.kind == kW6Track || r.kind == kW6Amb) ?
        " (a stopped track comes back where media.music.play may run, else with the next unit start - TruMenu.log)" : "");
    // 0.22.54 (crash 15.11. 19:48, TruMenu+0x13aec6 in strnlen under this Log): the sub-group kind (0.22.53) had no text
    // here - kHow[7] read past the end (the bytes "ever" of the first text) and the %s took them as a pointer. One text
    // per kind now (static_assert) and the index checked
    static const char *const kHow[] = {"every voice of the wave: FMOD ChannelI::setMute per channel",
                                       "every voice of that SoundPlex section's emitters: ChannelI::setMute",
                                       "every voice of the emitter: ChannelI::setMute",
                                       "the group's FMOD channel group: ChannelGroupI::setMute",
                                       "the srmusic track: SRMUSIC_LoadMusic(slot, NULL) whenever it starts",
                                       "group 15 (16 .. 24) channel group + the '_amb_' srmusic beds",
                                       "the category: its whole sub-trees by ChannelGroupI::setMute, the rest of its voices "
                                       "and the channels outside the pool by ChannelI::setMute",   // 0.22.50
                                       "the sub-group: its whole sub-trees by ChannelGroupI::setMute, the rest of its "
                                       "voices (stream voices too, wave -1) and the channels outside the pool by "
                                       "ChannelI::setMute"};   // 0.22.54
    static_assert(sizeof(kHow) / sizeof(kHow[0]) == kW6Kinds, "snd.mute: one kHow text per rule kind");
    const int how = static_cast<int>(r.kind);
    Log(1, "snd.mute %s %d (src=%s): %s; %d rule(s), %d channel(s) muted now", text, on ? 1 : 0, ShotSource("snd.mute"),
        how >= 0 && how < kW6Kinds ? kHow[how] : "?", g_w6RuleN, g_w6ChanN);
    return true;
}
// snd.solo <target> | off: every voice but the target's muted (channels); the same target again = off
bool RunW6Solo(const char *arg, char *o, size_t n) {
    char t[72] = "";
    TestWord(arg ? arg : "", t, sizeof(t));
    if (!W6Gate(o, n)) return false;
    if (!t[0] || !_stricmp(t, "off")) {
        const bool was = g_w6SoloOn != 0;
        g_w6SoloOn = 0;
        W6Apply();
        Log(1, "snd.solo off (src=%s)%s", ShotSource("snd.solo"), was ? ": the other voices unmuted" : " (was off)");
        Out(o, n, "snd.solo off");
        return true;
    }
    W6Rule r;
    if (!W6Parse(t, &r, o, n)) return false;
    if (r.kind == kW6Track) {
        Out(o, n, "snd.solo %s: a music track has no voice TruMenu can tell apart - snd.mute <track> / music.stop", t);
        return false;
    }
    char text[72];
    W6RuleText(r, text, sizeof(text));
    if (g_w6SoloOn && W6Same(g_w6Solo, r)) return RunW6Solo("off", o, n);   // the bar row toggles
    g_w6Solo = r;
    g_w6SoloOn = 1;
    W6Apply();
    Log(1, "snd.solo %s (src=%s): every other voice muted per channel (ChannelI::setMute 0x7c92b5) - %d now",
        text, ShotSource("snd.solo"), g_w6ChanN);
    Out(o, n, "snd.solo %s (%d other channel(s) muted)", text, g_w6ChanN);
    return true;
}
// snd.ambmute 1|0: the bar's switch for 'snd.mute ambience'
// 0.22.50 C (owner: two "Ambience off" rows): ONE "Ambient aus" - media.muteambient and snd.ambmute are this switch now:
// 'snd.mute ambience' = group 15 with 16 .. 24 (FMOD channel group mute) AND the '_amb_' srmusic beds (W6TrackRuled),
// kept in [Media] MuteAmbient (read at the start, W6Check turns it into the rule); without the W6 checks the 0.20 path
// (only the '_amb_' beds) is the fallback
void ValW6Amb(char *o, size_t n) {
    W6Rule r = {};
    r.kind = kW6Amb;
    if (!g_w6Ok) { ValMuteAmbient(o, n); return; }   // the 0.20 fallback
    Out(o, n, "%d", W6Find(r) >= 0 ? 1 : 0);
}
bool RunW6Amb(const char *arg, char *o, size_t n) {
    if (!g_w6Ok) return RunMuteAmbient(arg, o, n);   // 0.22.50: the 0.20 '_amb_' path when W6 is off
    W6Rule r = {};
    r.kind = kW6Amb;
    const bool on = BoolArg(arg, W6Find(r) >= 0);
    InterlockedExchange(&g_sndMuteAmb, 0);   // the rule stops the beds itself (no second stop)
    Log(1, "media.muteambient / snd.ambmute %d (src=%s): Ambient aus = sound groups 15 .. 24 (FMOD channel group mute) + "
        "the '_amb_' srmusic beds; [Media] MuteAmbient=%d kept", on ? 1 : 0, ShotSource("media.muteambient"), on ? 1 : 0);
    return RunW6Mute(on ? "ambience 1" : "ambience 0", o, n);
}
// snd.now: what plays now - one log line per voice (wave, SoundPlex section, emitter, group, state), short answer
bool RunW6Now(const char *, char *o, size_t n) {
    if (!g_snOk) { Out(o, n, "disabled: pre-check failed (%s)", g_snWhy); return false; }
    if (!W6Gate(o, n)) return false;
    if (GetCurrentThreadId() != g_snGameThread) {   // as snd.dump: the FMOD queries only on the game thread
        Out(o, n, "snd.now: only on the game thread - the game is not polling the pad now (loading / front end?), "
            "try again in a level");
        return false;
    }
    int audible = 0;
    const int all = SnBuild(&audible);
    g_snLastBuild = GetTickCount();
    EnterCriticalSection(&g_snLock);
    const int count = g_snSnapN;
    char music[160];
    strncpy_s(music, sizeof(music), g_snSnapMusic, _TRUNCATE);
    LeaveCriticalSection(&g_snLock);
    char unit[64] = "";
    CurrentUnit(unit, sizeof(unit));
    Log(1, "snd.now (src=%s): unit %s, %d voice(s), %d audible; srmusic '%s'", ShotSource("snd.now"), unit[0] ? unit : "-",
        all, audible, music);
    size_t used = 0;
    o[0] = 0;
    LabelAdd(o, n, &used, "%d voices, %d audible:", all, audible);
    int listed = 0;
    for (int i = 0; i < count; ++i) {
        const SnVoice &sv = g_snWork[i];
        const DWORD em = sv.emitter;         // 0.22.47: W7Emitter (params -> +0x74 chain) in SnBuild
        const DWORD sid = sv.sid;
        bool ours = false;
        for (int k = 0; k < g_w6ChanN; ++k)
            if (g_w6Chan[k].voice == sv.voice && g_w6Chan[k].channel == sv.channel) ours = true;
        char line[400], emText[48] = "?";
        SnVoiceText(sv, false, false, music, line, sizeof(line));
        if (em) Out(emText, sizeof(emText), "0x%08lx sound s%lu", em, sid);
        Log(1, "snd.now %3d %s | voice 0x%08lx ch 0x%08lx | emitter %s%s", i, line, sv.voice, sv.channel, emText,
            ours ? " | muted by TruMenu" : "");
        if (SnState(sv) != kSnStPlaying && !ours) continue;
        char w[16];
        if (sv.wave >= 0) Out(w, sizeof(w), "w%d", sv.wave);
        else Out(w, sizeof(w), "stream");
        char s[16] = "";
        if (em) Out(s, sizeof(s), "/s%lu", sid);
        LabelAdd(o, n, &used, " %s%s/g%d %.2f%s;", w, s, sv.group, static_cast<double>(sv.vol), ours ? " (stumm)" : "");
        ++listed;
    }
    if (music[0]) LabelAdd(o, n, &used, " music [%s]", music);
    if (!listed && !music[0]) LabelAdd(o, n, &used, " nothing audible");
    return true;
}
// snd.wavelog [on|off|<ids>]: the watched waves (session; [Sound] WaveLog / WaveIds at the start)
void ValW6WaveLog(char *o, size_t n) {
    size_t used = 0;
    o[0] = 0;
    LabelAdd(o, n, &used, "%s", g_w6WaveLog ? "on" : "off");
    for (int i = 0; i < g_w6WaveN; ++i) LabelAdd(o, n, &used, " %d", g_w6WaveIds[i]);
    LabelAdd(o, n, &used, " (%ld starts, %ld lines, max %d)", g_w6WaveStarts, g_w6WaveLines, g_w6WaveMax);
}
int W6ParseIds(const char *s, int out[8], char *o, size_t n) {
    int count = 0;
    const char *p = s;
    while (*p) {
        while (*p == ' ' || *p == ',') ++p;
        if (!*p) break;
        char *end = nullptr;
        const long v = strtol(p, &end, 10);
        if (end == p || (*end && *end != ' ' && *end != ',') || v < 0 || v >= 0x1400) {
            if (o) Out(o, n, "wave ids: '%s' - decimal 0 .. 5119, at most 8, space or comma between", s);
            return -1;
        }
        if (count >= 8) { if (o) Out(o, n, "wave ids: at most 8"); return -1; }
        out[count++] = static_cast<int>(v);
        p = end;
    }
    return count;
}
bool RunW6WaveLog(const char *arg, char *o, size_t n) {
    if (!g_w6Ok) { Out(o, n, "disabled: pre-check failed (%s)", g_w6Why); return false; }
    if (!arg || !arg[0]) { ValW6WaveLog(o, n); return true; }
    if (!_stricmp(arg, "on") || !_stricmp(arg, "off")) {
        g_w6WaveLog = _stricmp(arg, "on") == 0 ? 1 : 0;
    } else {
        int ids[8];
        const int k = W6ParseIds(arg, ids, o, n);
        if (k <= 0) { if (!k) Out(o, n, "wave ids: give at least one id (or on / off)"); return false; }
        memcpy(g_w6WaveIds, ids, sizeof(ids));
        g_w6WaveN = k;
        g_w6WaveLog = 1;
        g_w6SeenN = 0;
    }
    Log(1, "snd.wavelog (src=%s): %s", ShotSource("snd.wavelog"), arg);
    ValW6WaveLog(o, n);
    return true;
}
// music.stop [slot|all]: the game's stop native path for every slot that holds a track (default all); also in a level
bool RunW6MusicStop(const char *arg, char *o, size_t n) {
    if (!g_musicOk) { Out(o, n, "music code not verified (%s)", g_musicCheck); return false; }
    const bool all = !arg || !arg[0] || !_stricmp(arg, "all");
    const int slot = all ? 0 : MusicSlotArg(arg, -1);
    if (slot < 0) { Out(o, n, "usage: music.stop [slot 0-7 | all]"); return false; }
    size_t used = 0;
    o[0] = 0;
    LabelAdd(o, n, &used, "music.stop:");
    int stopped = 0;
    for (int s = all ? 0 : slot; s <= (all ? kMusicSlotCount - 1 : slot); ++s) {
        const DWORD base = kMusicSlots + static_cast<DWORD>(s) * kMusicSlotSize;
        char cur[64] = "", req[64] = "";
        ReadString(base, cur, sizeof(cur));
        ReadString(base + 0x100, req, sizeof(req));
        if (!cur[0] && !req[0]) continue;
        if (!SndStopSlot(s)) continue;
        LabelAdd(o, n, &used, " slot %d '%s'", s, req[0] ? req : cur);
        ++stopped;
    }
    if (!stopped) LabelAdd(o, n, &used, " nothing playing");
    else LabelAdd(o, n, &used, " stopped (SRMUSIC_LoadMusic(slot, NULL, %d, 0) as the stop native 0x4aa490)", g_musicFade);
    Log(1, "%s (src=%s)", o, ShotSource("music.stop"));
    return true;
}
// music.next: the music row of TruMenu.media.txt after the track of slot 0, through media.music.play (its gates)
bool RunW6MusicNext(const char *, char *o, size_t n) {
    if (!g_musicOk) { Out(o, n, "music code not verified (%s)", g_musicCheck); return false; }
    if (g_mediaCount < 0) { Out(o, n, "no TruMenu.media.txt - the track names are not known, nothing played"); return false; }
    char cur[64] = "", req[64] = "";
    ReadString(kMusicSlots, cur, sizeof(cur));
    ReadString(kMusicSlots + 0x100, req, sizeof(req));
    const char *now = req[0] ? req : cur;
    int first = -1, at = -1, next = -1;
    for (int i = 0; i < g_mediaCount; ++i) {
        if (_stricmp(g_media[i].kind, "music")) continue;
        if (first < 0) first = i;
        if (at >= 0 && next < 0) next = i;
        if (now[0] && !_stricmp(g_media[i].name, now)) at = i;
    }
    if (first < 0) { Out(o, n, "TruMenu.media.txt has no music rows"); return false; }
    if (next < 0) next = first;
    char line[80];
    Out(line, sizeof(line), "%s 0", g_media[next].name);
    Log(1, "music.next (src=%s): after '%s' -> '%s'", ShotSource("music.next"), now[0] ? now : "-", g_media[next].name);
    return RunMusicPlay(line, o, n);
}
void W6ReadOptions(const char *ini) {
    g_w6WaveLog = OptInt(ini, "Sound", "WaveLog") != 0 ? 1 : 0;
    g_w6WaveMax = OptInt(ini, "Sound", "WaveLogMax");
    if (g_w6WaveMax < 0 || g_w6WaveMax > 100000) g_w6WaveMax = 500;
    char v[96];
    OptString(ini, "Sound", "WaveIds", v, sizeof(v));
    int ids[8];
    const int k = W6ParseIds(v, ids, nullptr, 0);
    if (k > 0) {
        memcpy(g_w6WaveIds, ids, sizeof(ids));
        g_w6WaveN = k;
    } else {                                 // empty / bad: the default 10 (logged by W6Check)
        g_w6WaveIds[0] = 10;
        g_w6WaveN = 1;
    }
}
// load: the byte checks of precheck_02245.txt (after M201Check: needs the voice pool and the FMOD group mute)
void W6Check() {
    DWORD at = 0;
    g_w6Ok = g_snOk && g_smOk && DvChecks(kW6Checks, sizeof(kW6Checks) / sizeof(kW6Checks[0]), &at);
    if (g_w6Ok) Out(g_w6Why, sizeof(g_w6Why), "ok");
    else Out(g_w6Why, sizeof(g_w6Why), !g_snOk || !g_smOk ? "needs the 0.20.1 sound list / group mute checks"
                                                         : "FMOD channel / emitter code differs at 0x%08lx", at);
    char ids[64] = "";
    size_t used = 0;
    for (int i = 0; i < g_w6WaveN; ++i) LabelAdd(ids, sizeof(ids), &used, "%s%d", i ? "," : "", g_w6WaveIds[i]);
    Log(g_w6Ok ? 1 : 0, "0.22.45 W6 sound switches: checks %s (%d rows); [Sound] WaveLog %d, WaveIds %s, WaveLogMax %d; "
        "snd.mute / snd.solo / snd.now / music.stop / music.next", g_w6Why,
        static_cast<int>(sizeof(kW6Checks) / sizeof(kW6Checks[0])), g_w6WaveLog, ids, g_w6WaveMax);
    if (g_w6Ok && g_sndMuteAmb && g_w6RuleN < kW6RuleMax) {   // 0.22.50 C: the kept "Ambient aus" = the ambience rule
        W6Rule r = {};
        r.kind = kW6Amb;
        g_w6Rules[g_w6RuleN++] = r;
        InterlockedExchange(&g_sndMuteAmb, 0);
        Log(1, "0.22.50 Ambient aus: [Media] MuteAmbient=1 -> snd.mute ambience (groups 15 .. 24 + the '_amb_' beds) from "
            "the first game frame");
    }
}
