bool SoReadUnit(DWORD u, SoUnitInfo &i) {
    memset(&i, 0, sizeof(i));
    for (int k = 0; k < 63; ++k) {
        BYTE c = 0;
        if (!ReadByte(u + 2 + static_cast<DWORD>(k), &c)) return false;
        i.name[k] = static_cast<char>(c);
        if (!c) break;
    }
    i.name[63] = 0;
    if (!ReadDword(u + 0x88, &i.handle) || !ReadDword(u + 0x8c, &i.meshes) || !ReadByte(u + 0xb0, &i.mask) ||
        !ReadByte(u + 0xb1, &i.loading) || !ReadByte(u + 0xb3, &i.placed))
        return false;
    bool placeholder = false;
    for (int m = 0; i.meshes && m < 2; ++m) {
        DWORD mesh = 0, f = 0, v = 0;
        if (!ReadDword(i.meshes + 4 * static_cast<DWORD>(m), &mesh) || !mesh) continue;
        if (!ReadDword(mesh + 0x44, &f) || !ReadDword(mesh + 0x48, &v)) return false;
        i.faces += f;
        i.verts += v;
        placeholder = placeholder || (f == 100 && v == 56);
    }
    i.kind = i.meshes ? (placeholder && i.faces == 100 ? 2 : 1) : (!i.loading && !i.handle ? 3 : 0);
    return true;
}
// one line per open (when the view runs, mode 3): floor, radius / view distance, every map unit of the sonar
void SoLogUnits(DWORD list, DWORD count, DWORD anchor) {
    BYTE floor = 0;
    DWORD tuning = 0;
    float radius = 0.0f, view = 0.0f;
    ReadByte(kSoFloor, &floor);
    if (ReadDword(kSoTuning, &tuning) && tuning) {
        ReadFloats(tuning + 0xc, &radius, 1);
        ReadFloats(tuning + 0x10, &view, 1);
    }
    char text[1500] = "";
    size_t used = 0;
    DWORD drawn = 0, faces = 0;
    for (DWORD k = 0; k < count && k < 64; ++k) {
        DWORD u = 0;
        SoUnitInfo i;
        if (!ReadDword(list + 4 * k, &u) || !u || !SoReadUnit(u, i)) continue;
        const bool on = i.meshes && i.placed && ((i.mask & floor) || g_soOnA);
        if (on) { ++drawn; faces += i.faces; }
        const char *st = i.kind == 3 ? "nofile" : !i.meshes ? "loading" : !i.placed ? "unplaced" : on ? "drawn" : "skipped";
        LabelAdd(text, sizeof(text), &used, "%s%s%s m%02x %s %lu", used ? ", " : "", u == anchor ? "*" : "", i.name,
                 i.mask, st, i.faces);
    }
    Log(1, "0.22.49 sonar open: floor [0xedf268] 0x%02x, radius %.0f, view distance %.0f (+4000; tuning [0xee03e0] +0xc / "
        "+0x10), FullMap %d AllFloors %d; %lu map units, %lu drawn with %lu faces (triangle cap %ld) - %s", floor,
        static_cast<double>(radius), static_cast<double>(view), g_soOnC ? 1 : 0, g_soOnA ? 1 : 0, count, drawn, faces,
        g_soOnT ? g_soOnT : kSoCapGame, text);
}
void SoMapTick(DWORD now) {
    DWORD mode = 0;
    if (!ReadDword(kSoMode, &mode) || mode == 0 || mode > 4) { g_soWasOpen = false; return; }
    if (!g_soWasOpen) { g_soWasOpen = true; g_soListLogged = false; g_soMapTick = 0; }
    if (g_soMapTick && now - g_soMapTick < 250) return;
    g_soMapTick = now ? now : 1;
    DWORD anchor = 0, list = 0, count = 0;
    if (!ReadDword(kSoAnchor, &anchor) || !anchor || !ReadDword(kSoUnits, &list) || !list ||
        !ReadDword(kSoUnitCount, &count) || count > 256)
        return;
    bool listed = false;                     // [0xedf254] is not cleared by the close: only a unit of the live list
    for (DWORD k = 0; k < count && !listed; ++k) {
        DWORD u = 0;
        listed = ReadDword(list + 4 * k, &u) && u == anchor;
    }
    SoUnitInfo a;
    if (!listed || !SoReadUnit(anchor, a)) return;
    AcquireSRWLockExclusive(&g_soMapLock);
    const bool changed = strcmp(g_soMap.name, a.name) || g_soMap.kind != a.kind || g_soMap.faces != a.faces;
    g_soMap = a;
    ReleaseSRWLockExclusive(&g_soMapLock);
    if (changed && a.kind != 0)
        Log(1, "0.22.49 sonar: map of %s: %s (faces %lu, vertices %lu, floor mask 0x%02x, load handle %s)", a.name,
            a.kind == 1 ? "real" : a.kind == 2 ? "placeholder only (100 faces / 56 vertices)" : "no file (+0x88 stays 0)",
            a.faces, a.verts, a.mask, a.handle ? "set" : "0");
    if (mode == 3 && !g_soListLogged) {
        g_soListLogged = true;
        SoLogUnits(list, count, anchor);
        S5LogView("open");                   // 0.22.51 (d): centre, axis, the cut plane per unit (section "0.22.51 S5")
    }
}
void S7Tick(DWORD now);                      // 0.22.53 S7 (below): the sonar's extra map loads
void KvTick(DWORD now);                      // 0.22.66 (T2 1): sonar.keepview (section "0.22.66 sonar view kept")
void SoTick() {                              // game thread, every pad poll (cheap: flags, the INI once a second)
    if (!g_soOk) return;
    const DWORD now = GetTickCount();
    if (now - g_soReadTick >= 1000) { g_soReadTick = now; SoReadSwitch(); }
    SoApply("run time");
    if (g_soOnC) SoCapTick(now);
    SoMapTick(now);                          // 0.22.49: two reads while the sonar is closed
    S7Tick(now);                             // 0.22.53 S7
    KvTick(now);                             // 0.22.66 (T2 1): one read while the sonar is closed
}
