    for (int i = 0; i < g_s5NameN && g_s5Area[0]; ++i) listed = listed || !_stricmp(g_s5Names[i], g_s5Area);
    if (!g_s5Area[0]) Out(o, n, de ? "alle (%d)" : "all (%d)", g_s5NameN);
