// [Debug] RoomOnly (owner live 13.11.: "only the current room" for switches / levers / uber labels and key items):
// the room = Lara's stream unit (the data has no finer room); an instance of an unknown unit stays.
// 0.22.42 (W3, live 13.11. 21:15 dlc_caverns: the bridge in front of Lara lost markers): the intro record is not enough -
// an instance of another intro unit stays when its own stream unit +0xe0 is Lara's or when it is within [Debug] RoomNear
// of her (W3RoomDrops; every drop / keep by these rules is logged once per instance and Lara unit)
int g_p5RoomOnly = 0;
bool P5RoomOnlyDrops(DWORD inst) {
    if (!g_p5RoomOnly) return false;
    const char *unit = DvOwnerUnitAny(inst);
    return unit[0] && !DvIsLaraUnit(unit) && W3RoomDrops(inst, unit);
}

// ---- co_ / fx_ filter ----
// 0.22.38 (live 2026-11-13, P5 test in DLC 1: dlc_fx_* / dlc1_fx_* kept their labels - only the name start was tested):
// a "dlc_" / "dlc<digits>_" in front is skipped first, then the 0.22.37 rule. The merged object list (PC 1 .. 821 +
// Xbox TU / DLC 822 .. 1045, work/generic/lists; 1045 distinct names) has 74 dlc_fx_* and 2 dlc1_fx_* (76 names more
// than 0.22.37), no dlc2_fx_* and no dlc*_co_*; co_fx_* stays a co_ object (counts: work/menu38_1311/prefix_names.py)
int P5PrefixKind(const char *low) {          // low = lower-case object name; 1 co_, 2 fx_, 3 neither / an exception
    const char *s = low;
    if (!strncmp(s, "dlc", 3)) {
        const char *p = s + 3;
        while (*p >= '0' && *p <= '9') ++p;
        if (*p == '_') s = p + 1;
    }
    if (!strncmp(s, "co_", 3) && strncmp(s, "co_rock", 7)) return 1;
    if (!strncmp(s, "fx_", 3) && !strstr(s, "_grab_prompt")) return 2;
    return 3;
}
signed char g_p5Prefix[4096];                // per object id: 0 unknown, 1 co_, 2 fx_, 3 neither / an exception
bool P5PrefixHidden(DWORD inst) {
    if (!g_p5HideCo && !g_p5HideFx) return false;
    DWORD object = 0, oid = 0;
    if (!ReadDword(inst + 0x10, &object) || !object || !ReadDword(object + 0x14, &oid)) return false;
    const int id = static_cast<int>(oid & 0xffff);
    int k = id > 0 && id < 4096 ? g_p5Prefix[id] : 0;
    if (!k) {
        char low[64];
        k = 3;
        if (ObjectName(id, low, sizeof(low))) {
            _strlwr_s(low, sizeof(low));
            k = P5PrefixKind(low);           // 0.22.38: dlc_ / dlc1_ / dlc2_ in front skipped first
        }
        if (id > 0 && id < 4096) g_p5Prefix[id] = static_cast<signed char>(k);
    }
    return (k == 1 && g_p5HideCo) || (k == 2 && g_p5HideFx);
}

