P5KeyMark g_kiAt[65];                        // the marks of this frame (for the link lines)
M20Mark g_kiMarks[65];                       // M20Insert keeps at most [Debug] MarkMax (<= 64)
int g_kiN = 0, g_kiLinks = 0;
bool g_kiFresh = false;
