    Log(1, "chapter.unitfresh %d: [Chapter] UnitFresh=%d written - mid-chapter unit rows %s", on ? 1 : 0, on ? 1 : 0,
        on ? "start with new game data (f27) and keep the loaded intro units' played marks at 1 (experimental)"
           : "load with level.keep (state kept)");
