// chapter.intros: the table with every intro's played mark now
void ValUiIntros(char *o, size_t n) {
    if (g_uiN < 0) {
        Out(o, n, "%s", g_uiRtState == 1 ? "no TruMenu.unitintros.txt; the game data read is running"
                                         : "no TruMenu.unitintros.txt and no table from the game data");
        return;
    }
    size_t used = 0;
    o[0] = 0;
    LabelAdd(o, n, &used, "[%s%s] ", g_uiSource, g_uiRtState == 1 ? ", game data read running" : "");   // 0.22.66
    for (int i = 0; i < g_uiN; ++i) {
        LONG v = 0;
        StHit h = {};
        const int r = UiMarkGet(g_ui[i].intro, &v, &h);
        char m[16];
        if (r == 1) Out(m, sizeof(m), "%ld", v);
        else Out(m, sizeof(m), "%s", r ? "?" : "-");
        LabelAdd(o, n, &used, "%s%lu %s mark %s", i ? "; " : "", g_ui[i].intro, g_ui[i].unit, m);
    }
    if (!g_uiN) Out(o, n, "TruMenu.unitintros.txt holds no intro");
}
// ---- S4 cp.reload ----
const ChCheck kCrChecks[] = {
    {0x005dfcad, "f705b8f0e70000100000"},                              // in-game frame: only while the pause bit is clear
    {0x005dfcba, "8b4730 a900000800 7427"},                            // streamFlags (edi = GameTracker) & 0x80000
    {0x005dfcc4, "25fffff7ff 57 894730 e80e48ffff"},                   // bit cleared, 0x5d44e0(GameTracker)
    {0x005dfcda, "e8a1e7ffff eb07 6a06 e878faffff"},                   // in place 0x5de480, else 0x5df760(6)
    {0x005d44e0, "8b442404 53 32db 389869010000 7427 a16492c500 83c010"},   // byte +0x169, the checkpoint's unit name
    {0x006f55a7, "810db8f0e70000000800"},                              // the death state's request (0x6f55a0)
};
int g_crChecked = 0;                         // 0 = not yet, 1 = ok, -1 = failed
bool CrOk() {
    if (!g_crChecked) {
        int bad = 0;
        for (const ChCheck &k : kCrChecks)
            if (!HexBytesAt(k.at, k.hex)) {
                ++bad;
                Log(0, "0.22.58 cp.reload: 0x%08lx does not match - Letzten Checkpoint laden stays off", k.at);
            }
        g_crChecked = bad ? -1 : 1;
        if (!bad) Log(1, "0.22.58 cp.reload: 6 byte checks ok (request bit 0x80000 of [0xe7f0b8], served at 0x5dfcba)");
    }
    return g_crChecked > 0;
}
struct CrState { bool armed, served, saw2; DWORD tick, servedTick, lastTick, gap, player; bool predictInPlace; char cpUnit[64]; };
CrState g_cr = {false, false, false, 0, 0, 0, 0, 0, false, ""};
// what 0x5d44e0 will answer: byte [GameTracker+0x169] and the checkpoint's unit ([[0xc59264]+0x10], empty ->
// [[0xe7ee50]+0x10]+0x20) in the stream unit table (state not 0 / 4, name +0xc - the walk of 0x5c1b90)
bool CrPredict(char *unit, size_t un, BYTE *flag, bool *found) {
    *found = false;
    unit[0] = 0;
    *flag = 0;
    ReadByte(kGameTracker + 0x169, flag);
    const DWORD gd = GameData();
    char name[64] = "";
    if (gd) ReadString(gd + 0x10, name, sizeof(name));
    if (!name[0]) {
        DWORD gi = 0, p = 0;
        if (ReadDword(kGlobalInfo, &gi) && gi && ReadDword(gi + 0x10, &p) && p) ReadString(p + 0x20, name, sizeof(name));
    }
    strncpy_s(unit, un, name, _TRUNCATE);
    for (DWORD e = kStreamUnits; e < kStreamUnitsEnd && name[0]; e += kStreamUnitSize) {
        BYTE st = 0;
        char u[64];
        if (!ReadByte(e + 4, &st) || !st || st == 4 || !ReadString(e + 0xc, u, sizeof(u))) continue;
        if (!_stricmp(u, name)) { *found = true; break; }
    }
    return *flag && *found;
}
void ValCpReload(char *o, size_t n) {
    if (!InLevel()) { Out(o, n, "needs a level"); return; }
    char unit[64];
    BYTE flag = 0;
    bool found = false;
    const bool inPlace = CrPredict(unit, sizeof(unit), &flag, &found);
    Out(o, n, "%s (checkpoint unit %s)", !CrOk() ? "byte checks FAILED" : inPlace ? "in place" : "full reload",
        unit[0] ? unit : "-");
}
bool RunCpReload(const char *, char *o, size_t n) {   // game thread
    if (!CrOk() || !g_experimental) { Out(o, n, "refused: cp.reload byte checks failed / experimental off (TruMenu.log)"); return false; }
    DWORD state = 0, flags = 0;
    if (!g_mainStateOk || !ReadDword(kMainState, &state) || state != 1) {
        Out(o, n, "refused: main state %lu - only in a running level (main state 1)", state);
        return false;
    }
    if (!InLevel()) { Out(o, n, "refused: no player"); return false; }
    if (CinematicNow()) { Out(o, n, "refused: a cutscene plays (cinematic test 0x453f00)"); return false; }
    char why[200];
    if (LevelChangePending(why, sizeof(why))) { Out(o, n, "refused: level change pending (%s)", why); return false; }
    if (!ReadDword(kStreamFlags, &flags)) { Out(o, n, "refused: streamFlags not readable"); return false; }
    if (flags & 0x80000) { Out(o, n, "refused: a restart request is already set ([0xe7f0b8] bit 0x80000)"); return false; }
    if ((flags & 0x1000) && !g_menuPaused && !g_radPaused) {
        Out(o, n, "refused: the world is paused (pause bit 0x1000: the game's pause menu, photo mode, time.pause) - the game "
            "serves the request only while it is clear");
        return false;
    }
    if (g_cr.armed) { Out(o, n, "refused: a cp.reload is still being watched"); return false; }
    if (K1Gate("cp.reload", o, n)) return false;   // 0.22.67 (B1 K1): the reload would birth the checkpoint costume
    BYTE flag = 0;
    bool found = false;
    char unit[64];
    const bool inPlace = CrPredict(unit, sizeof(unit), &flag, &found);
    FlightOffForLoad("cp.reload");           // as every TruMenu load
    ChArm("cp.reload");                      // a full reload passes main state 2: the stale camera hints are cleared
    DWORD player = 0;
    ReadDword(kPlayerPtr, &player);
    bool ok = false;
    __try {
        _InterlockedOr(reinterpret_cast<volatile long *>(kStreamFlags), 0x80000);
        ok = true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        InterlockedIncrement(&g_ownExceptions);
    }
    if (!ok) { Out(o, n, "the write to [0xe7f0b8] FAULTED (caught)"); return false; }
    g_cr.armed = true;
    g_cr.served = g_cr.saw2 = false;
    g_cr.tick = g_cr.lastTick = GetTickCount();
    g_cr.gap = 0;
    g_cr.player = player;
    g_cr.predictInPlace = inPlace;
    strncpy_s(g_cr.cpUnit, sizeof(g_cr.cpUnit), unit, _TRUNCATE);
    Log(1, "0.22.58 cp.reload (src=%s): [0xe7f0b8] |= 0x80000 (the death restart request without the death: no health 0, "
        "no tracker flags); prediction 0x5d44e0: byte [GameTracker+0x169] = %u, checkpoint unit '%s' %s -> %s", ShotSource(
        "cp.reload"), static_cast<unsigned>(flag), unit[0] ? unit : "-", found ? "loaded" : "not loaded",
        inPlace ? "in-place checkpoint restore 0x5de480" : "full reload 0x5df760(6)");
    Out(o, n, "reload last checkpoint requested (%s expected, checkpoint unit %s)", inPlace ? "in-place restore" : "full reload",
        unit[0] ? unit : "-");
    if (g_menuOpen) ToggleMenu("cp.reload");
    return true;
}
void CrTick(DWORD state) {                   // game thread (ChTick)
    if (!g_cr.armed) return;
    const DWORD now = GetTickCount();
    if (now - g_cr.lastTick > g_cr.gap) g_cr.gap = now - g_cr.lastTick;   // a long frame = the in-place wait loop
    g_cr.lastTick = now;
    if (state == 2) g_cr.saw2 = true;
    DWORD flags = 0;
    ReadDword(kStreamFlags, &flags);
    if (!g_cr.served) {
        if (!(flags & 0x80000)) {
            g_cr.served = true;
            g_cr.servedTick = now;
            Log(1, "0.22.58 cp.reload: request served by the game after %.1f s (main state %lu, longest game-thread gap %lu ms)",
                static_cast<double>(now - g_cr.tick) / 1000.0, state, g_cr.gap);
            return;
        }
        if (now - g_cr.tick > 20000) {
            bool taken = false;
            __try {
                _InterlockedAnd(reinterpret_cast<volatile long *>(kStreamFlags), ~0x80000L);
                taken = true;
            } __except (EXCEPTION_EXECUTE_HANDLER) {
                InterlockedIncrement(&g_ownExceptions);
            }
            Log(0, "0.22.58 cp.reload: the game did not serve the request within 20 s (main state %lu, streamFlags 0x%08lx) - "
                "bit %s", state, flags, taken ? "taken back" : "take-back FAULTED");
            g_cr.armed = false;
        }
        return;
    }
    if (!g_cr.saw2 && now - g_cr.servedTick < 5000) return;
    DWORD player = 0;
    ReadDword(kPlayerPtr, &player);
    const bool full = g_cr.saw2;
    Log(1, "0.22.58 cp.reload: result %s (main state 2 %s within 5 s of the serve, longest game-thread gap %lu ms, player "
        "instance 0x%08lx -> 0x%08lx); predicted %s (checkpoint unit '%s')%s", full ? "FULL RELOAD (0x5df760(6))"
        : "IN-PLACE RESTORE (0x5de480)", full ? "seen" : "not seen", g_cr.gap, g_cr.player, player,
        g_cr.predictInPlace ? "in place" : "full reload", g_cr.cpUnit[0] ? g_cr.cpUnit : "-",
        full == !g_cr.predictInPlace ? "" : " - DIFFERS from the prediction");
    g_cr.armed = false;
}
void CcTick(DWORD state);                    // 0.22.69 (B4): chapter.cp watch, checkpoint table, sonar.cplabels (below)
void UiTick(DWORD state) {                   // game thread (ChTick: Render and PadHook)
    ImTick(state);
    WdTick();
    CrTick(state);
    CcTick(state);
}
