    DWORD at = 0;
    g_h2Ok = g_akOk && g_stOk && g_unitOk && DvChecks(kH2Checks, sizeof(kH2Checks) / sizeof(kH2Checks[0]), &at);
    if (g_h2Ok) Out(g_h2Why, sizeof(g_h2Why), "ok");
