// 0.22.33 photo mode (group K, F1 / Q78; workspace docs\Befund-Gruppe-F-1211.md section 3, docs\Befund-Gruppe-K-1211.md):
// the game's own free camera, not one of TruMenu's. FreeCamera = the camera manager's slot of mode 5 ([0xe804f0+0x18] =
// 0xe8e9a0 from the ctor 0x5f3bc2, vtable 0x855e54): activate vf+0x1c 0x5f91b0 takes position / rotation / transform of
// the camera it replaces, pad 0 (+0xf0) and Lara's control off (0x5d5f60); update 0x5f9770 reads the left stick (fly),
// right stick + mouse (look) and actions 19 - 22 (speed / up-down) with the generalbank DTP 16 values (FOV 50, speeds);
// deactivate vf+0x20 0x5f91a0 gives the control back (0x5d5f40). CAMERA_SetMode 0x5f39f0 knows only 6 / 11 / 12
// (camera.mode 5 does nothing), so the switch is the manager's own 0x5edd70(mgr, mode, 0) (thiscall, ret 8: layer +0x4c
// = 0, mode +0x60, slot [mgr+4+mode*4], 0x5e8630 = old vf+0x20(new), [mgr+0x44] = new, new vf+0x1c(old); a set byte
// +0x7c only stores the mode; slot 11 +0x30 is put back to the game camera mgr+0x3370 first).
// photo.on: refused in a cutscene, while loading / a level change waits, in the game's pause, with flight or cine.pause,
// on another camera layer / a held mode / a current camera that is not its mode's slot; else remember mode, control
// byte 0x8ab4e6, pause bit, UI byte -> streamFlags 0xe7f0b8 |= 0x1000 (time.pause: the world stands, the camera update
// 0x5f3df0 at 0x5dff14 still runs - the world block skips from 0x5dfeb2 to 0x5dff0f) -> UI byte 0xcdc9a0 = 1 (ui.hide;
// the game's own screenshot task 0x774aa0 sets the same byte around its frame redraw 0x5da1c0) -> 0x5edd70(mgr, 5, 0)
// and the FreeCamera must be current. photo.off: 0x5edd70(mgr, <remembered mode>, 0) while the FreeCamera is still
// current on layer 0 in mode 5 (the same function back), 0x5edf50 (the game's restore = mode 11) when mode / layer
// changed meanwhile, nothing when the game took the camera itself; control byte as before (0x5d5f60 again if it was 0);
// the pause bit / UI byte only if photo.on set them. Left by itself (Present hook = game thread, PmTick) on a level
// change request, a new player instance / stream unit, main state != 1, a cinematic, the game's pause ([0xe7f0b4] &
// 0x10000000 = pause menu) or a camera the game switched to. TruMenu's own bar / menu leave it on (they are the way to
// photo.shot / photo.off). Plugin unload: only the pause bit / UI byte (no game call from DllMain).
// photo.shot = shot.save clean photo_<n>[_<name>]. No new INI key, 23 byte checks (kPmChecks).
const DWORD kPmFreeCam = 0x00e8e9a0, kPmFreeCamVt = 0x00855e54, kPmSetMode = 0x005edd70, kPmCtlOff = 0x005d5f60;
const DWORD kPmGamePause = 0x00e7f0b4;       // bit 0x10000000: the game's own pause (0x5d4780 / 0x5d4810; frame time 0.5)
const DvCheck kPmChecks[] = {
    {0x005edd70, "56 8bf1 837e4c00 57 8b7c240c 7509 3b7e60 0f8488000000"},      // mode switch: layer +0x4c, mode +0x60
    {0x005edd87, "8d8670330000 85c0 740e 394630 7409 8986800b0000 894630"},    // slot 11 +0x30 = game camera +0x3370
    {0x005edd9f, "807e7c00 7567 807c241000"},                                   // +0x7c held: mode only stored; blend
    {0x005eddb8, "83ff0d c7464c00000000 897e60"},                               // layer 0, mode stored
    {0x005eddfb, "8b54be04 52 8bce e829a8ffff 5f 5e c20800"},                   // slot [mgr+4+mode*4] -> 0x5e8630, ret 8
    {0x005e8630, "53 56 8bd9 8b7344 8b06 8b5020 57 8b7c2410 57 8bce ffd2 897b44 8b07 8b501c 56 8bcf ffd2"},   // switch
    {0x005edf50, "d90530118400 56 8bf1 33c9 d95e78 394e4c"},                   // restore (camera.restore's function)
    {0x005edf7f, "8d510b 7505 395660 7429"},                                    // restore = mode 11
    {0x005f3bc2, "8d86b0e40000 894618"},                                        // ctor: slot 5 [mgr+0x18] = mgr+0xe4b0
    {0x00855e54, "c0365e00 70975f00 30915f00"},                                 // FreeCamera vtable: +4 update 0x5f9770
    {0x00855e70, "b0915f00 a0915f00"},                                          // vf+0x1c activate, vf+0x20 deactivate
    {0x005f91b0, "55 8bec 83e4f0 83ec18 56 8bf1 83bed0000000ff"},               // activate 0x5f91b0
    {0x005f92bc, "c786f000000000000000 e895ccfdff"},                            // pad 0, control off 0x5d5f60
    {0x005f91a0, "e89bcdfdff c20400"},                                          // deactivate: control on 0x5d5f40
    {0x005d5f40, "e85bcaeaff c605e6b48a0001"},                                  // control on: byte 0x8ab4e6 = 1
    {0x005d5f60, "c605e6b48a0000 e834caeaff e92ff80600"},                       // control off: byte 0x8ab4e6 = 0
    {0x005dfeb2, "8535b8f0e700 7555"},                                          // pause bit 0x1000 skips the world ...
    {0x005dff0f, "e83c32fdff e8d73e0100"},                                      // ... not the camera update 0x5f3df0
    {0x005f3e0c, "b9f004e800 e85afeffff 8b0d3405e800"},                         // camera update: manager 0xe804f0
    {0x005da233, "f705b4f0e70000000010"},                                       // game pause bit 0x10000000
    {0x005d47a7, "c60543f1e70006"},                                             // the pause sets game mode 6
    {0x005a434c, "803da0c9cd0000 56 0f85f8040000"},                             // HUD draw reads the UI byte 0xcdc9a0
    {0x00774ac5, "c605a0c9cd0001 e8ef56e6ff"},                                  // the game's screenshot task hides it
};
typedef void(__fastcall *PmSetModeFn)(DWORD mgr, DWORD edx, int mode, int blend);   // thiscall, ret 8
bool g_pmChecked = false, g_pmOk = false;
char g_pmWhy[96] = "not checked";
volatile LONG g_pmActive = 0;
int g_pmMode = 11;                           // camera mode before photo.on
BYTE g_pmCtl = 1;                            // control byte 0x8ab4e6 before photo.on
bool g_pmPauseOurs = false, g_pmUiOurs = false;
DWORD g_pmPlayer = 0, g_pmUnit = 0, g_pmStart = 0;
LONG g_pmShots = 0, g_pmOns = 0;
char g_pmLast[200] = "-";                    // the last leave (or refusal) with its reason
bool PmCheck() {
    if (g_pmChecked) return g_pmOk;
    g_pmChecked = true;
    DWORD at = 0;
    g_pmOk = g_cameraOk && DvChecks(kPmChecks, sizeof(kPmChecks) / sizeof(kPmChecks[0]), &at);
    if (g_pmOk) Out(g_pmWhy, sizeof(g_pmWhy), "ok");
    else if (!g_cameraOk) Out(g_pmWhy, sizeof(g_pmWhy), "camera code (0.1 checks) differs");
    else Out(g_pmWhy, sizeof(g_pmWhy), "free camera code differs at 0x%08lx", at);
    Log(g_pmOk ? 1 : 0, "0.22.33: photo mode %s (%d checks)", g_pmWhy, static_cast<int>(sizeof(kPmChecks) / sizeof(kPmChecks[0])));
    return g_pmOk;
}
// why photo.on may not start now ("" = it may); any thread, read only
void PmRefusal(char *o, size_t n) {
    o[0] = 0;
    DWORD state = 0, v = 0, layer = 0, mode = 0, cur = 0, slot = 0, slot11 = 0, freeCam = 0, vt = 0;
    BYTE hold = 0;
    char why[160];
    if (!PmCheck()) { Out(o, n, "disabled: %s", g_pmWhy); return; }
    if (!g_experimental) { Out(o, n, "experimental actions off ([Cheat] Experimental=0)"); return; }
    if (!InLevel()) { Out(o, n, "needs a level"); return; }
    if (g_mainStateOk && ReadDword(kMainState, &state) && state != 1) { Out(o, n, "main state %lu (needs 1: play game)", state); return; }
    if (LevelChangePending(why, sizeof(why))) { Out(o, n, "%s", why); return; }
    if (CinematicNow()) { Out(o, n, "a cutscene plays"); return; }
    if (g_cnPause) { Out(o, n, "cine.pause holds a cutscene"); return; }
    if (ReadDword(kPmGamePause, &v) && (v & 0x10000000)) { Out(o, n, "the game is paused (pause menu)"); return; }
    if (g_flight) { Out(o, n, "flight is on (cheat.flight 0 first)"); return; }
    if (!ReadDword(kCameraManager + 0x4c, &layer) || !ReadDword(kCameraManager + 0x60, &mode) ||
        !ReadByte(kCameraManager + 0x7c, &hold) || !ReadDword(kCurrentCamera, &cur) ||
        !ReadDword(kCameraManager + 0x30, &slot11) || !ReadDword(kCameraManager + 0x18, &freeCam) ||
        !ReadDword(kPmFreeCam, &vt)) { Out(o, n, "camera manager not readable"); return; }
    if (layer) { Out(o, n, "camera layer %lu (a script / cutscene camera)", layer); return; }
    if (hold) { Out(o, n, "the camera manager holds its mode (+0x7c)"); return; }
    if (mode == 5) { Out(o, n, "the free camera is current already (camera mode 5)"); return; }
    if (mode > 15 || !ReadDword(kCameraManager + 4 + mode * 4, &slot) || cur != slot) {
        Out(o, n, "current camera 0x%08lx is not the slot of mode %lu", cur, mode);
        return;
    }
    if (slot11 != kCameraManager + 0x3370) { Out(o, n, "slot 11 holds another camera (0x%08lx)", slot11); return; }
    if (freeCam != kPmFreeCam || vt != kPmFreeCamVt) {
        Out(o, n, "FreeCamera slot differs ([mgr+0x18] 0x%08lx, vtable 0x%08lx)", freeCam, vt);
        return;
    }
}
const char *PmWhy() {                        // bar grey reason for photo.on (render thread), at most 60 characters
    static char why[160];
    if (g_pmActive) return "";
    PmRefusal(why, sizeof(why));
    if (strlen(why) > 60) why[60] = 0;
    return why;
}
// ---- 0.22.34 photo.pose (group M, F2; docs\Befund-Gruppe-F-1211.md 3.4, docs\Befund-Gruppe-M-1211.md) ----
// Lara's poses screen_capture_01 .. _07 are entries 1604 .. 1598 of her object's anim table (lara DTP 850, sections
// 1551 .. 1545, in lara.drm); no chart slot points to them, so no state of hers plays them. The game's own way to play
// an anim-table entry by index on an instance is the anim request 0x444ba0 (thiscall processor, {u16 mode, u16 anim},
// donor Object; ret 8) in mode 0: 0x444ca7 builds a slot record with one list item = the table index (0x4321d0: speed
// 0x1000 = 1.0, count 1) and starts it with 0x4428a0 - the path of the uber action "play anim" (0x4d86d9) and of the
// script instance helper 0x4abb10 (processor 0 = [[inst+0x280]+0x14]). photo.pose <1..7> runs only in the photo mode
// (the world is paused there: Lara's own process, so her chart, is skipped - 0x5b6e62 - while every processor still gets
// its per-frame 0x443690 - 0x5b704e) and only when the table entry holds the expected section and is resident (slot !=
// -1: a costume object with another table is refused). Before the first pose it notes the processor's +0x44 = the slot
// of the last mode-1 request (0x444c8f; 0x4428a0 sets it to -1 at 0x442d1a); photo.pose off (and photo.off / leaving
// by itself) requests that slot again in mode 1 (the bounded own-object path 0x444c38: slot < u16 [Object+0x38]) - the
// anim Lara had, from its start; no slot noted (-1) = the pose stays until her chart requests the next anim. 13 byte
// checks (kPpChecks), no new INI key.
const DWORD kPpRequest = 0x00444ba0;
const int kPpLastIndex = 1604;               // screen_capture_0n = anim table index 1605 - n (01 = 1604 .. 07 = 1598)
const WORD kPpLastSection = 1551;            // and anim section 1552 - n (01 = 1551 .. 07 = 1545)
const DvCheck kPpChecks[] = {
    {0x00444ba0, "83ec2c a1e8d78b00 33c4 89442428 55 8b6c2438 56 57 8b7c243c 8bf1 0fb70f 33c0 2bc8 0f84df000000 83e901 7440"},
    {0x00444c0d, "53 8bce e8db95ffff 0fb74702 6685c0 8b4e34 8b491c 7c31 85ed 7410"},   // mode 1: [[proc+0x34]+0x1c] = inst
    {0x00444c38, "85c9 7419 8b4910 663b4138 7d10 8b5158 8b0a"},                // own object: slot < u16 [Object+0x38]
    {0x00444c57, "6a01 55 53 8bce e83edcffff 0fb75314"},                       // 0x4428a0, then the entry's speed
    {0x00444c89, "0fb74702 5b 5f 894644"},                                      // processor +0x44 = the mode-1 slot
    {0x00444ca7, "0fb74f02 6a00 6aff 68ff000000 6a00 6a00 6aff 6a01 6a01 6a00 6a00 6a01 6800100000 51 8d4c2444 e8fdd4feff"},
    {0x00444cd3, "8bce e81695ffff 6a01 55 8d542418 52 8bce e8b7dbffff"},       // mode 0: start the built record
    {0x004321d0, "668b442408 8a542410 56 8bf1 8a4c2410 66894614"},             // record: +0x14 speed
    {0x0043222b, "e810271400 668b4c240c 89460c 668908 8b560c b801000000 884202 084620 894610"},   // one item = the index
    {0x00442d1a, "c74644ffffffff"},                                             // 0x4428a0: +0x44 = -1
    {0x004abb32, "8b4f04 8b9180020000 8b4a14 83c404 50 56 e85890f9ff"},        // script helper: processor 0, 0x444ba0
    {0x005b6e5d, "855e1c 750c 851db8f0e700 0f858a010000"},                     // paused: the instance's process skipped
    {0x005b7043, "8b9680020000 8b4a14 03cb e83dc6e8ff"},                       // ... its processors still run 0x443690
};
typedef DWORD(__fastcall *PpRequestFn)(DWORD proc, DWORD edx, const WORD *rec, DWORD donor);   // thiscall, ret 8
bool g_ppChecked = false, g_ppOk = false;
char g_ppWhy[96] = "not checked";
int g_ppPose = 0;                            // 0 = none, 1 .. 7 = screen_capture_0n requested
DWORD g_ppPlayer = 0, g_ppProc = 0, g_ppSlot = 0xffffffff;   // the slot noted before the first pose
char g_ppLast[200] = "-";
bool PpCheck() {
    if (g_ppChecked) return g_ppOk;
    g_ppChecked = true;
    DWORD at = 0;
    g_ppOk = g_playerOk && DvChecks(kPpChecks, sizeof(kPpChecks) / sizeof(kPpChecks[0]), &at);
    if (g_ppOk) Out(g_ppWhy, sizeof(g_ppWhy), "ok");
    else if (!g_playerOk) Out(g_ppWhy, sizeof(g_ppWhy), "player pointer check failed");
    else Out(g_ppWhy, sizeof(g_ppWhy), "anim request code differs at 0x%08lx", at);
    Log(g_ppOk ? 1 : 0, "0.22.34: photo.pose %s (%d checks)", g_ppWhy, static_cast<int>(sizeof(kPpChecks) / sizeof(kPpChecks[0])));
    return g_ppOk;
}
// Lara's instance, processor 0 and object (read only); "" = fine
void PpTarget(DWORD *player, DWORD *proc, DWORD *object, char *why, size_t n) {
    DWORD ctl = 0, procs = 0, owner = 0, inst = 0;
    why[0] = 0;
    *player = *proc = *object = 0;
    if (!ReadDword(kPlayerPtr, player) || !*player) { Out(why, n, "no player instance"); return; }
    if (!ReadDword(*player + 0x280, &ctl) || !ctl || !ReadDword(ctl + 0x14, proc) || !*proc ||
        !ReadDword(ctl + 0x18, &procs) || procs < 1) {
        Out(why, n, "Lara has no anim processor ([inst+0x280] 0x%08lx)", ctl);
        return;
    }
    if (!ReadDword(*proc + 0x34, &owner) || !owner || !ReadDword(owner + 0x1c, &inst) || inst != *player) {
        Out(why, n, "processor 0x%08lx belongs to 0x%08lx, not Lara 0x%08lx", *proc, inst, *player);
        return;
    }
    if (!ReadDword(*player + 0x10, object) || !*object) Out(why, n, "Lara's object not readable");
}
// anim table entry k of an object: section id and run-time slot (0xffff = not resident); false = no such entry
bool PpEntry(DWORD object, int k, WORD *section, WORD *slot) {
    WORD count = 0;
    DWORD table = 0;
    return ReadWord(object + 0x3c, &count) && k >= 0 && k < count && ReadDword(object + 0x44, &table) && table &&
           ReadWord(table + static_cast<DWORD>(k) * 12, section) && ReadWord(table + static_cast<DWORD>(k) * 12 + 2, slot);
}
// game thread: the anim Lara had before the first pose again (photo.pose off, photo.off, leaving by itself)
void PpUndo(const char *reason, char *o, size_t n) {
    if (!g_ppPose) { Out(o, n, "no pose set (last: %s)", g_ppLast); return; }
    DWORD player = 0, proc = 0, object = 0;
    char why[160];
    PpTarget(&player, &proc, &object, why, sizeof(why));
    WORD count = 0;
    const char *what;
    char pending[160];
    if (why[0] || player != g_ppPlayer || proc != g_ppProc) {
        what = "Lara's instance / processor changed - nothing requested";
    } else if (LevelChangePending(pending, sizeof(pending)) || CinematicNow()) {
        what = "a level change / cutscene drives Lara now - nothing requested";
    } else if (g_ppSlot == 0xffffffff || !ReadWord(object + 0x38, &count) || g_ppSlot >= count) {
        what = "no chart slot noted - the pose stays until her chart requests the next anim";
    } else {
        const WORD rec[2] = {1, static_cast<WORD>(g_ppSlot)};
        __try {
            reinterpret_cast<PpRequestFn>(kPpRequest)(proc, 0, rec, 0);
            what = "her slot requested again (0x444ba0 mode 1)";
        } __except (EXCEPTION_EXECUTE_HANDLER) {
            InterlockedIncrement(&g_ownExceptions);
            what = "EXCEPTION in 0x444ba0 mode 1";
        }
    }
    Out(g_ppLast, sizeof(g_ppLast), "pose %d off (%s): %s, slot %ld", g_ppPose, reason, what,
        g_ppSlot == 0xffffffff ? -1L : static_cast<long>(g_ppSlot));
    g_ppPose = 0;
    g_ppSlot = 0xffffffff;
    Log(1, "photo.pose: %s", g_ppLast);
    Out(o, n, "%s", g_ppLast);
}
void PrStart();                                  // 0.22.63 (S3 3a), below
bool RunPhotoPose(const char *arg, char *o, size_t n) {
    char a[16] = "";
    if (arg) strncpy_s(a, sizeof(a), arg, _TRUNCATE);
    // 0.22.68 (B2 6, A4 d P1): "<n> test" = the same request outside the photo mode (no pause) for the [Pose] comparison
    char *tw = strstr(a, " test");
    const bool test = tw != nullptr;
    if (tw) *tw = 0;
    DvTrim(a);
    if (!_stricmp(a, "off") || !strcmp(a, "0")) { PpUndo("photo.pose off", o, n); return true; }
    int pose = 0;
    if (!_stricmp(a, "next") || !a[0]) pose = g_ppPose % 7 + 1;
    else if (a[0] >= '1' && a[0] <= '7' && !a[1]) pose = a[0] - '0';
    if (!pose) { Out(o, n, "usage: photo.pose 1..7|next|off (screen_capture_01 .. _07)"); return false; }
    if (!PpCheck()) { Out(o, n, "disabled: %s", g_ppWhy); return false; }
    if (!g_experimental) { Out(o, n, "experimental actions off ([Cheat] Experimental=0)"); return false; }
    if (!g_pmActive && !test) { Out(o, n, "refused: only in the photo mode (photo.on first; '<n> test' = outside, for a comparison)"); return false; }
    if (test && CinematicNow()) { Out(o, n, "refused: a cutscene runs"); return false; }
    DWORD player = 0, proc = 0, object = 0, before = 0xffffffff;
    char why[160];
    PpTarget(&player, &proc, &object, why, sizeof(why));
    if (why[0]) { Out(o, n, "refused: %s", why); return false; }
    if (g_ppPose && (player != g_ppPlayer || proc != g_ppProc)) {
        g_ppPose = 0;                        // a new instance: the note of the old one is worthless
        g_ppSlot = 0xffffffff;
    }
    const int k = kPpLastIndex + 1 - pose;
    WORD section = 0, slot = 0;
    if (!PpEntry(object, k, &section, &slot)) {
        Out(o, n, "refused: Lara's object 0x%08lx has no anim table entry %d", object, k);
        return false;
    }
    if (section != kPpLastSection + 1 - pose) {
        Out(o, n, "refused: entry %d holds section %u, not %d (screen_capture_0%d) - another costume object?", k, section,
            kPpLastSection + 1 - pose, pose);
        return false;
    }
    if (slot == 0xffff) { Out(o, n, "refused: screen_capture_0%d (entry %d, section %u) is not resident", pose, k, section); return false; }
    if (!g_ppPose) ReadDword(proc + 0x44, &before);
    const WORD rec[2] = {0, static_cast<WORD>(k)};
    __try {
        reinterpret_cast<PpRequestFn>(kPpRequest)(proc, 0, rec, 0);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        InterlockedIncrement(&g_ownExceptions);
        Out(o, n, "EXCEPTION in 0x444ba0 mode 0 (entry %d)", k);
        Log(0, "photo.pose: %s", o);
        return false;
    }
    if (!g_ppPose) {
        g_ppPlayer = player;
        g_ppProc = proc;
        g_ppSlot = before;
    }
    g_ppPose = pose;
    PrStart();                                   // 0.22.63 (S3 3a): Lara's process runs a moment despite the pause
    Out(g_ppLast, sizeof(g_ppLast), "pose %d = screen_capture_0%d (entry %d, section %u, slot %u) on processor 0x%08lx; "
        "back to slot %ld", pose, pose, k, section, slot, proc, g_ppSlot == 0xffffffff ? -1L : static_cast<long>(g_ppSlot));
    Log(1, "photo.pose (src=%s): %s", ShotSource("photo.pose"), g_ppLast);
    Out(o, n, "%s - photo.pose off = back", g_ppLast);
    return true;
}
// ---- end of 0.22.34 photo.pose ----
void ValPhoto(char *o, size_t n) {
    DWORD cam = 0;
    ReadDword(kCurrentCamera, &cam);
    if (g_pmActive)
        Out(o, n, "on %lu s (camera 0x%08lx, mode before %d, control before %u, pause %s, UI %s); %ld shots; pose %d "
            "(last: %s); last: %s", (GetTickCount() - g_pmStart) / 1000, cam, g_pmMode, g_pmCtl,
            g_pmPauseOurs ? "by photo mode" : "was set", g_pmUiOurs ? "hidden by photo mode" : "was hidden", g_pmShots,
            g_ppPose, g_ppLast, g_pmLast);
    else
        Out(o, n, "off (checks %s; %ld times on, %ld shots; camera 0x%08lx); pose: %s; last: %s", g_pmChecked ? g_pmWhy :
            "not run yet", g_pmOns, g_pmShots, cam, g_ppLast, g_pmLast);
}
// game thread: back from the photo mode (reason for the log); 0.22.34: the pose first (photo.pose off), then the
// camera, control, pause bit, UI byte
void PrEnd(const char *why);                     // 0.22.63 (S3 3), below: the pose run bit back
void LhShow(const char *why);                    // 0.22.63 (S3 3), below: Lara shown again
void PmLeave(const char *reason, char *o, size_t n) {
    DWORD cur = 0, layer = 0, mode = 0, flags = 0;
    BYTE ctl = 1;
    PrEnd(reason);                               // 0.22.63 (S3 3): the run bit first, then the pose, Lara shown again
    LhShow(reason);
    if (g_ppPose) {
        char pose[240];
        PpUndo(reason, pose, sizeof(pose));
    }
    ReadDword(kCurrentCamera, &cur);
    ReadDword(kCameraManager + 0x4c, &layer);
    ReadDword(kCameraManager + 0x60, &mode);
    const bool ours = cur == kPmFreeCam;
    const char *cam = "";
    char ctlText[80] = "control as the game set it";
    __try {
        if (ours && !layer && mode == 5) {
            reinterpret_cast<PmSetModeFn>(kPmSetMode)(kCameraManager, 0, g_pmMode, 0);
            cam = "camera mode back (0x5edd70)";
        } else if (ours) {
            reinterpret_cast<CameraRestoreFn>(kCameraRestore)(reinterpret_cast<void *>(kCameraManager), 0);
            cam = "camera restored (0x5edf50: mode / layer had changed)";
        } else {
            cam = "the game had switched the camera itself - left as it is";
        }
        if (ours) {
            ReadByte(kPlayerControl, &ctl);
            if (!g_pmCtl && ctl) {
                reinterpret_cast<VoidFn>(kPmCtlOff)();
                Out(ctlText, sizeof(ctlText), "control off again as before (0x5d5f60)");
            } else {
                Out(ctlText, sizeof(ctlText), "control %u (before %u)", ctl, g_pmCtl);
            }
        }
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        InterlockedIncrement(&g_ownExceptions);
        cam = "EXCEPTION in the camera switch";
    }
    volatile LONG *f = reinterpret_cast<volatile LONG *>(kStreamFlags);
    const bool pauseBack = g_pmPauseOurs && ReadDword(kStreamFlags, &flags) && (flags & 0x1000);
    if (pauseBack) InterlockedAnd(f, ~0x1000L);
    const bool uiBack = g_pmUiOurs && ByteAt(kUiHidden);
    if (uiBack) *reinterpret_cast<volatile BYTE *>(kUiHidden) = 0;
    InterlockedExchange(&g_pmActive, 0);
    DWORD now = 0;
    ReadDword(kCurrentCamera, &now);
    Out(g_pmLast, sizeof(g_pmLast), "off (%s) after %lu s: %s, camera now 0x%08lx, %s, %s, %s", reason,
        (GetTickCount() - g_pmStart) / 1000, cam, now, ctlText, pauseBack ? "world runs again" : "pause bit left",
        uiBack ? "HUD back" : "UI byte left");
    Log(1, "photo: %s", g_pmLast);
    Out(o, n, "photo mode %s", g_pmLast);
}
bool RunPhotoOn(const char *, char *o, size_t n) {
    if (g_pmActive) { Out(o, n, "photo mode is on already (photo.off, photo.shot)"); return true; }
    char why[200];
    PmRefusal(why, sizeof(why));
    if (why[0]) {
        Out(o, n, "refused: %s", why);
        Out(g_pmLast, sizeof(g_pmLast), "refused: %s", why);
        Log(1, "photo.on refused (src=%s): %s", ShotSource("photo.on"), why);
        return false;
    }
    DWORD mode = 11, cur = 0;
    BYTE ctl = 1, ui = 0;
    ReadDword(kCameraManager + 0x60, &mode);
    ReadByte(kPlayerControl, &ctl);
    ReadByte(kUiHidden, &ui);
    ReadDword(kPlayerPtr, &g_pmPlayer);
    ReadDword(kUnitId, &g_pmUnit);
    g_pmMode = static_cast<int>(mode);
    g_pmCtl = ctl;
    volatile LONG *f = reinterpret_cast<volatile LONG *>(kStreamFlags);
    const LONG before = InterlockedOr(f, 0x1000);
    // as time.pause: a pause the open menu / ring set becomes ours (their close would clear it under the free camera)
    const LONG menuHeld = InterlockedExchange(&g_menuPaused, 0), ringHeld = InterlockedExchange(&g_radPaused, 0);
    g_pmPauseOurs = !(before & 0x1000) || menuHeld || ringHeld;
    g_pmUiOurs = !ui;
    if (!ui) *reinterpret_cast<volatile BYTE *>(kUiHidden) = 1;
    bool fault = false;
    __try {
        reinterpret_cast<PmSetModeFn>(kPmSetMode)(kCameraManager, 0, 5, 0);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        InterlockedIncrement(&g_ownExceptions);
        fault = true;
    }
    ReadDword(kCurrentCamera, &cur);
    if (fault || cur != kPmFreeCam) {
        if (g_pmPauseOurs) InterlockedAnd(f, ~0x1000L);
        if (g_pmUiOurs) *reinterpret_cast<volatile BYTE *>(kUiHidden) = 0;
        Out(o, n, "refused: %s (current camera 0x%08lx) - pause bit / UI byte put back", fault ? "exception in 0x5edd70"
            : "the game did not switch to the FreeCamera", cur);
        Out(g_pmLast, sizeof(g_pmLast), "%s", o);
        Log(0, "photo.on: %s", o);
        return false;
    }
    g_pmStart = GetTickCount();
    InterlockedIncrement(&g_pmOns);
    InterlockedExchange(&g_pmActive, 1);
    Out(g_pmLast, sizeof(g_pmLast), "on (mode before %d, control before %u, pause %s, UI %s)", g_pmMode, g_pmCtl,
        g_pmPauseOurs ? "set" : "was set", g_pmUiOurs ? "hidden" : "was hidden");
    Log(1, "photo.on (src=%s): FreeCamera 0x%08lx current, %s; left stick = fly, right stick / mouse = look, the game's "
        "keys of actions 19 - 22 = speed / up-down; photo.shot, photo.off", ShotSource("photo.on"), cur, g_pmLast);
    Out(o, n, "photo mode on: the game's FreeCamera (left stick fly, right stick / mouse look), world paused, HUD hidden "
        "- photo.shot = clean shot, photo.off = back");
    return true;
}
bool RunPhotoOff(const char *, char *o, size_t n) {
    if (!g_pmActive) { Out(o, n, "photo mode is off (last: %s)", g_pmLast); return true; }
    PmLeave("photo.off", o, n);
    return true;
}
bool RunPhotoShot(const char *arg, char *o, size_t n) {
    char name[48] = "";
    if (arg) strncpy_s(name, sizeof(name), arg, _TRUNCATE);
    DvTrim(name);
    char a[96];
    const LONG k = InterlockedIncrement(&g_pmShots);
    Out(a, sizeof(a), "clean photo_%03ld%s%s", k, name[0] ? "_" : "", name);
    const bool ok = RunShotSave(a, o, n);
    if (ok && !g_pmActive) strncat_s(o, n, " (photo mode is off - a clean shot all the same)", _TRUNCATE);
    return ok;
}
// ---- 0.22.63 (package S3 3, ENGINE 5.2 "Instance +0x1c bit 0x1000, +0x14 bit 0x800 (S2)" + 22) photo extras ----
// (a) pose visible: after photo.pose Lara's +0x1c |= 0x1000 (= processed while the world is paused, 0x5b6e5d) for
//     kPrFrames frames, then the bit exactly as before (only if her stamp +0x44 is the same; a line when other bits of
//     the word changed meanwhile). (b) photo.hide / photo.show: +0x14 |= 0x800 (not drawn, 0x5c69f1 / 0x5c6b7f /
//     0x5b9521) on Lara and her children (+0x218 first child, +0x21c sibling, 3 levels, 32 instances), the old bits
//     back on show / photo.off / a level change, only where the stamp is unchanged; no message 7. Also outside the photo
//     mode. (c) photo.shotui: shot.save "ui" (after TruMenu's drawing: lines, labels) once the bar / menu / ring are
//     closed for 2 frames, so the panel itself is not in the picture. Present hook (render thread), every frame.
const DvCheck kPhxChecks[] = {
    {0x005c69f1, "f7461400080000"},              // scene update: +0x14 & 0x800 -> entry skipped (not drawn)
    {0x005c6b7f, "f7461400080000"},
    {0x005b9521, "f7461400080000"},              // bone update
    {0x005dfe29, "e8329bfdff"},                  // bone update outside the pause tests
};
const int kPrFrames = 45, kLhMax = 32;
struct PrRun { DWORD inst, stamp, old; int frames; bool on; };
PrRun g_prRun = {};
struct LhEntry { DWORD inst, stamp, old; };
LhEntry g_lh[kLhMax];
int g_lhN = 0;
volatile LONG g_lhOn = 0;
int g_phxChecked = 0;                            // 0 = not yet, 1 = ok, -1 = failed
volatile LONG g_psuWant = 0;
char g_psuName[48] = "";
int g_psuClosed = 0;
bool PhxOk() {
    if (!g_phxChecked) {
        DWORD at = 0;
        g_phxChecked = DvChecks(kPhxChecks, sizeof(kPhxChecks) / sizeof(kPhxChecks[0]), &at) ? 1 : -1;
        Log(g_phxChecked > 0 ? 1 : 0, "0.22.63 photo extras: %s", g_phxChecked > 0 ? "4 byte checks ok" : "a byte check failed - pose bit / hide off");
    }
    return g_phxChecked > 0;
}
volatile LONG *Word32(DWORD at) { return reinterpret_cast<volatile LONG *>(at); }
void PrEnd(const char *why) {
    PrRun &r = g_prRun;
    if (!r.on) return;
    r.on = false;
    DWORD cur = 0;
    if (tlobj::D(r.inst + 0x44) != r.stamp || !ReadDword(r.inst + 0x1c, &cur)) {
        Log(1, "photo.pose: run bit not put back (%s) - Lara's instance changed", why);
        return;
    }
    if ((cur & ~0x1000UL) != (r.old & ~0x1000UL))
        Log(1, "photo.pose: +0x1c changed meanwhile (before 0x%08lx, now 0x%08lx) - only bit 0x1000 is put back", r.old, cur);
    if (!(r.old & 0x1000)) InterlockedAnd(Word32(r.inst + 0x1c), ~0x1000L);
    Log(1, "photo.pose: run bit 0x1000 back to %d after %d frame(s) (%s)", (r.old & 0x1000) ? 1 : 0, r.frames, why);
}
// called by RunPhotoPose after a request: Lara runs for kPrFrames frames while the world is paused
void PrStart() {
    if (!PhxOk()) return;
    DWORD player = 0, old = 0;
    if (!ReadDword(kPlayerPtr, &player) || !player || !ReadDword(player + 0x1c, &old)) return;
    if (g_prRun.on && g_prRun.inst == player) { g_prRun.frames = 0; return; }   // already running: count again
    PrEnd("next pose");
    g_prRun.inst = player;
    g_prRun.stamp = tlobj::D(player + 0x44);
    g_prRun.old = old;
    g_prRun.frames = 0;
    g_prRun.on = true;
    InterlockedOr(Word32(player + 0x1c), 0x1000L);
    Log(1, "photo.pose: Lara +0x1c 0x%08lx |= 0x1000 for %d frames (processed while paused, S2)", old, kPrFrames);
}
void LhShow(const char *why) {
    if (!g_lhOn) return;
    int back = 0, gone = 0;
    for (int i = 0; i < g_lhN; ++i) {
        const LhEntry &e = g_lh[i];
        if (tlobj::D(e.inst + 0x44) != e.stamp) { ++gone; continue; }
        if (!(e.old & 0x800)) InterlockedAnd(Word32(e.inst + 0x14), ~0x800L);
        ++back;
    }
    Log(1, "photo.show (%s): bit 0x800 of +0x14 back on %d instance(s), %d gone / changed (left alone)", why, back, gone);
    g_lhN = 0;
    InterlockedExchange(&g_lhOn, 0);
}
void LhAdd(DWORD inst, int depth) {
    if (!inst || g_lhN >= kLhMax) return;
    DWORD old = 0;
    if (!ReadDword(inst + 0x14, &old)) return;
    g_lh[g_lhN++] = {inst, tlobj::D(inst + 0x44), old};
    if (depth >= 3) return;
    DWORD child = 0;
    ReadDword(inst + 0x218, &child);
    for (int k = 0; child && k < kLhMax && g_lhN < kLhMax; ++k) {
        LhAdd(child, depth + 1);
        if (!ReadDword(child + 0x21c, &child)) break;
    }
}
void ValPhotoHide(char *o, size_t n) { Out(o, n, "%s (%d instance(s))", g_lhOn ? "hidden" : "shown", g_lhN); }
bool RunPhotoHide(const char *, char *o, size_t n) {
    if (!PhxOk()) { Out(o, n, "disabled: byte checks failed (TruMenu.log)"); return false; }
    if (g_lhOn) { Out(o, n, "Lara is hidden already (photo.show)"); return true; }
    DWORD player = 0;
    if (!ReadDword(kPlayerPtr, &player) || !player) { Out(o, n, "no player"); return false; }
    g_lhN = 0;
    LhAdd(player, 0);
    for (int i = 0; i < g_lhN; ++i) InterlockedOr(Word32(g_lh[i].inst + 0x14), 0x800L);
    InterlockedExchange(&g_lhOn, 1);
    Log(1, "photo.hide (src=%s): +0x14 |= 0x800 on Lara and %d child instance(s) (old words kept; no message 7)",
        ShotSource("photo.hide"), g_lhN - 1);
    Out(o, n, "Lara hidden (%d instance(s)) - photo.show = back", g_lhN);
    return true;
}
bool RunPhotoShow(const char *, char *o, size_t n) {
    if (!g_lhOn) { Out(o, n, "Lara is not hidden by TruMenu"); return true; }
    LhShow("photo.show");
    Out(o, n, "Lara shown again");
    return true;
}
bool RunPhotoShotUi(const char *arg, char *o, size_t n) {
    g_psuName[0] = 0;
    if (arg) strncpy_s(g_psuName, sizeof(g_psuName), arg, _TRUNCATE);
    DvTrim(g_psuName);
    g_psuClosed = 0;
    InterlockedExchange(&g_psuWant, 1);
    Log(1, "photo.shotui (src=%s): shot with TruMenu's lines once the bar / menu / ring are closed", ShotSource("photo.shotui"));
    Out(o, n, "photo.shotui: taken when the bar / menu are closed (with lines and labels)");
    return true;
}
// 0.22.68 (B2 point 6, A4 d, ENGINE 22 "Photo pose still invisible (A4)"): while the run bit holds, one [Pose] line
// per frame (processor 0 +0x44 = the slot of the last mode-1 request, -1 after TruMenu's mode-0 pose, Lara's chart
// record, Lara +0x1c) and, the first frame, the processor's words +0 .. +0x7c; when +0x44 is no longer -1 the chart has
// asked for its own anim (unproven reading) -> the pose is requested again (mode 0) - at most once a frame, never once
// the processor still shows -1 (no request every frame: that restarts the blend). Present = after the game's instance
// loop of the frame (unproven). Each re-request and the end are logged.
int g_ppRe = 0;                              // re-requests in this run
void PpFrameTick() {
    if (!g_prRun.on || !g_ppPose || !g_ppProc) return;
    DWORD slot = 0, t = 0, m = 0, rec = 0, w1c = 0;
    ReadDword(g_ppProc + 0x44, &slot);
    if (ReadDword(0x00fadb58, &t) && t && ReadDword(t + 0xf10, &m) && m) ReadDword(m + 0x510, &rec);
    ReadDword(g_prRun.inst + 0x1c, &w1c);
    if (g_prRun.frames == 0) {               // the processor words once
        char hex[600] = "";
        size_t used = 0;
        for (DWORD k = 0; k < 0x80; k += 4) LabelAdd(hex, sizeof(hex), &used, "%s%08lx", k ? " " : "", tlobj::D(g_ppProc + k));
        Log(1, "[Pose] processor 0x%08lx +0 .. +0x7c: %s", g_ppProc, hex);
        g_ppRe = 0;
    }
    bool again = false;
    if (slot != 0xffffffff && g_ppRe < 30 && !CinematicNow()) {   // the chart took the processor: the pose again
        const int k = kPpLastIndex + 1 - g_ppPose;
        const WORD rq[2] = {0, static_cast<WORD>(k)};
        DWORD player = 0;
        ReadDword(kPlayerPtr, &player);
        if (player == g_ppPlayer) {
            __try {
                reinterpret_cast<PpRequestFn>(kPpRequest)(g_ppProc, 0, rq, 0);
                again = true;
                ++g_ppRe;
            } __except (EXCEPTION_EXECUTE_HANDLER) {
                InterlockedIncrement(&g_ownExceptions);
                Log(0, "[Pose] EXCEPTION in 0x444ba0 mode 0 (re-request) - stopped");
                g_ppRe = 30;
            }
        }
    }
    DWORD after = 0;
    ReadDword(g_ppProc + 0x44, &after);
    Log(1, "[Pose] frame %d: processor +0x44 %ld, record #%d, Lara +0x1c 0x%08lx%s", g_prRun.frames,
        slot == 0xffffffff ? -1L : static_cast<long>(slot), CtRecordIndex(m, rec), w1c,
        again ? " -> the chart's slot: pose requested again" : "");
    if (again) Log(1, "[Pose] re-request %d: +0x44 now %ld", g_ppRe, after == 0xffffffff ? -1L : static_cast<long>(after));
}
// Present hook, every frame (after PmTick)
void PhxTick() {
    PpFrameTick();                               // 0.22.68 (B2 6): the [Pose] lines + re-request
    if (g_prRun.on && ++g_prRun.frames >= kPrFrames) {
        if (g_ppPose) Log(1, "[Pose] end of the run: %d re-request(s) in %d frames", g_ppRe, g_prRun.frames);
        PrEnd("frames done");
    }
    if (g_lhOn) {                                // a level change: the player instance is new - forget, touch nothing
        DWORD player = 0;
        ReadDword(kPlayerPtr, &player);
        if (!g_lhN || player != g_lh[0].inst || tlobj::D(player + 0x44) != g_lh[0].stamp) LhShow("Lara's instance changed");
    }
    if (g_psuWant) {
        const bool closed = !g_qbOpen && !g_menuOpen && !g_radOpen;
        g_psuClosed = closed ? g_psuClosed + 1 : 0;
        if (g_psuClosed >= 2) {
            InterlockedExchange(&g_psuWant, 0);
            char a[96], out[200];
            const LONG k = InterlockedIncrement(&g_pmShots);
            Out(a, sizeof(a), "ui photo_%03ld_ui%s%s", k, g_psuName[0] ? "_" : "", g_psuName);
            RunShotSave(a, out, sizeof(out));
            Log(1, "photo.shotui: %s", out);
        }
    }
}
// Present hook (game thread), every frame: leave by itself when the level / state / camera changes under it
void PmTick() {
    if (!g_pmActive) return;
    DWORD player = 0, unit = 0, state = 1, v = 0, cur = 0;
    char why[160] = "";
    ReadDword(kPlayerPtr, &player);
    ReadDword(kUnitId, &unit);
    ReadDword(kCurrentCamera, &cur);
    if (LevelChangePending(why, sizeof(why))) {
        // why holds the reason
    } else if (!player || player != g_pmPlayer) {
        Out(why, sizeof(why), "player instance 0x%08lx -> 0x%08lx (level change)", g_pmPlayer, player);
    } else if (unit != g_pmUnit) {
        Out(why, sizeof(why), "stream unit %lu -> %lu", g_pmUnit, unit);
    } else if (g_mainStateOk && ReadDword(kMainState, &state) && state != 1) {
        Out(why, sizeof(why), "main state %lu", state);
    } else if (CinematicNow()) {
        Out(why, sizeof(why), "a cutscene started");
    } else if (ReadDword(kPmGamePause, &v) && (v & 0x10000000)) {
        Out(why, sizeof(why), "the game's pause menu opened");
    } else if (cur != kPmFreeCam) {
        Out(why, sizeof(why), "the game switched the camera to 0x%08lx", cur);
    }
    if (!why[0]) return;
    char o[400];
    PmLeave(why, o, sizeof(o));
}
// DllMain detach: only TruMenu's own data writes back (no game call under the loader lock)
void PmShutdown() {
    if (!g_pmActive) return;
    if (g_pmPauseOurs) InterlockedAnd(reinterpret_cast<volatile LONG *>(kStreamFlags), ~0x1000L);
    if (g_pmUiOurs) *reinterpret_cast<volatile BYTE *>(kUiHidden) = 0;
    InterlockedExchange(&g_pmActive, 0);
}
