// ---- 0.17 quick toggles ----
// Schnellschalter (owner wish 2026-11-06, TODO.md "Ideen"; workspace docs\Befund-TruMenu-Schnellschalter-0611.md): a third
// control next to the long menu and the ring, for switching the debug view while playing - a small panel at the LEFT
// screen edge (the legend sits top right), the game keeps running (no freeze, no neutral pad). [Quick] OpenButtons
// (default View + Start = 0x0030) opens / closes it; while it is open D-pad up / down picks a row, left / right switches
// off / on (a value row: one step down / up), LB / RB changes the page. Only those buttons are kept from the game while
// it is open (OnPad -> QbPad: masked in the state the game gets; a button held at the close stays away until released).
// 0.21.3 (Lukas 2026-11-07): X and Y belong to the open bar too (kQbOwn 0xC30F) - Y pins / unpins the selected row as a
// favourite ([Favorites] Ids, as Y in the menu / fav.add), X runs it (section "0.21.3 X / Y" after QbAct).
// The combo itself never reaches the game: a lone combo button is held back for [Quick] ChordMs (the other one may
// follow); released inside that window the game gets it as a 100 ms tap at once, held longer it gets it late (as held).
// Why View + Start: every pad button is bound in the PC input map (generalbank DTP 47, tools/input_map_find.py, logs
// r17_input_map_pc.txt): D-pad = set 0 / 2 / 18, LB / RB = sets 0 / 1 / 2 / 17 / 19 (gameplay), L3 + R3 = TruMenu's
// menu / ring (and a chord of set 0); View (code 0xb: actions 10 / 71 / 89) and Start (0xa: action 9) are menu buttons
// (pause / PDA) - a 250 ms delay on them costs nothing in play, and no binding uses View and Start together.
// Rows: no state of their own - every row runs the existing item through InvokeCore (as the ring: game-thread items are
// queued) and reads its state the ring's way (RadialOn / RadialWhy / ItemValueShort), so menu, ring and bar always agree.
// One "quick: <page> / <row> -> <item> <arg>: <answer>" line per action (the item's own line as well); no per-frame log.
// 0.18 (Lukas live 2026-11-06: "sicher schneller als das Radialmenue" - which menu / ring functions does the bar still
// lack?): 9 pages - Notfall / Cheats, Lara (+ the saved positions), Debug / Darstellung, Leveldaten (start page), Render /
// KI, Zeit / Test, Checkpoints, Saves, Kapitel (debug). Row kinds: bool (left / right = off / on), value (one step),
// action (right = run), info (right = the item's value in the footer), choice (left = next choice, right = run with it).
// kQfConfirm: a second right press on the same row within 3 s runs it (die, unit reload, chapter loads, checkpoint /
// position go with a level load); kQfBackup: save.backup first, then the item as a two-step shortcut (chapters).
// Pages with special rows (positions, checkpoints, saves) are built in the section "0.18 quick-toggle pages" below.
// kQbLabel = a group heading (id "-"), kQbPlanned = a planned function (id "-", greyed, right = what it will do; arg =
// "German text|English text")
enum QbKind { kQbBool = 0, kQbValue, kQbAction, kQbInfo, kQbChoice, kQbLabel, kQbPlanned,
              kQbGroup,                    // 0.21.1: a collapsible group heading (arg = its key in [Quick] Closed)
              // 0.22.28 (Q90 test packages, section "0.22.28 test packages"; only on kQfTp rows so far):
              kQbCheck,                    // a TO TEST check (id "test.mark", arg = the check id): right = OK, left =
                                           // Fehler, X = skip, the same press again = open; created with test.add
              kQbSwitch,                   // a switch of TruMenu.switches.txt (id "sw.set", arg "<Plugin>:<Section>:<Key>"):
                                           // the page Fixes row itself (QbSwView / QbSwAct), no own state
              kQbNote,                     // a hint line (id "-", text = de / en), not selectable, runs nothing
              kQbSndMon };                 // 0.22.47: the sound monitor's live rows in its place (id snd.monitor, arg
                                           // "voices" / "history" / "rules"; section "0.22.47 bar")
enum QbFlag { kQfConfirm = 1, kQfBackup = 2,
              kQfLine = 4,                 // 0.21.11 (page Rettung): right / X puts "<id> <arg> " into the quick command
                                           // line (long menu: the command bar) - for items that need a typed argument
              kQfSub = 8,                  // 0.22.18: a kQbGroup inside the group before it (nesting level 1)
              kQfTp = 16,                  // 0.22.28: test-package content (Q90, docs\Testpakete-1111.md) - after the tests
                                           // each such row becomes a real row of its page or is deleted (owner 2026-11-11)
                                           // 0.22.44 (W2): the Q90 packages are archived (group Archiv / Alt)
              kQfTg = 32,                  // 0.22.44 (W2): content of a test guide package (docs\Testanleitung-1411.md,
                                           // packages A - F; block "TG 1411" of kQbTests) - rows of existing items only
              kQfLv2 = 64, kQfLv3 = 128 }; // 0.22.53 W11: a kQbGroup / kQbLabel at nesting level 2 / 3 (the sound log trees)
enum QbCount { kQcNone = 0, kQcLayer, kQcTriggers, kQcTrgLabels, kQcLaraIn, kQcEncl, kQcLabels, kQcMarkup, kQcFlat, kQcOn,
               kQcCine, kQcAi,            // 0.19 kQcAi: enemies in the ai.dumb scope (last frame)
               kQcPhys };                 // 0.21.1: physics bodies used / capacity
enum QbVal { kQvNone = 0, kQvDepth, kQvAlpha, kQvBright, kQvEncl, kQvSpeed, kQvPass, kQvLang, kQvTime, kQvMark, kQvWeapon,
             kQvAssist, kQvAiMode,       // 0.19 kQvAiMode: ai.mode purge / gate
             kQvSndPos, kQvSndLines, kQvSndSort,     // 0.20.1 sound list: corner, lines, order
             kQvShake, kQvRumble,                    // 0.21 camera shake / rumble 0 / 50 / 100 %
             kQvSpawnKind, kQvSpawnCount, kQvSpawnAt,     // 0.21.1 enemy spawn: kind (choice), count 1 .. 5, place
             kQvSndGroup,                                 // 0.21.8 sound group slider 0 .. 100 % (the row's item)
             kQvSubLang, kQvSubSize, kQvSubAlpha, kQvSubColour, kQvSubPos,   // 0.22.16 settings page: subtitles
             kQvVol, kQvMouse, kQvGfx3,                   // 0.22.16 volume 0 .. 128 / 8, mouse 1 .. 20, gfx 0 .. 2 (item)
             kQvStepRate,                                 // 0.22.18 cine.steprate 5 / 10 / 15
             kQvSubAlignV, kQvSubAlignH, kQvSubMargin,    // 0.22.18 subtitle alignment
             kQvVoiceLang,                                // 0.22.18 voice.lang
             kQvAtStyle,                                  // 0.22.40 menu.attracticon 0 .. 7 (Q126b); 0.22.41 0 .. 16
             kQvSoFade, kQvSoArea,                        // 0.22.51 sonar.fade (8 steps) / sonar.area (alle + the list)
             kQvSoTint,                                   // 0.22.52 sonar.tint aus / ein Farbton / je Bereich
             kQvHear,                                     // 0.22.53 W11 snd.hear <row arg> normal / stumm / solo
             kQvChapKeep };                               // 0.22.56 chapter.keep: the chapter (choice row)
// colour 0 = the layer's; flags = QbFlag
struct QbRow { const char *de, *en, *id, *arg; int kind, layer, count, val; ImU32 colour; int flags; };
// 0.22.18 (owner 2026-11-10, shot pc_leiste_gruppen_164959): the nesting level of a group heading - 0 top, 1 a sub-group
// (kQfSub); its rows are one level deeper. A closed group hides everything up to the next heading of its level or above.
int QbGroupLevel(const QbRow &r) {           // 0.22.53 W11: levels 2 / 3 (kQfLv2 / kQfLv3)
    return (r.flags & kQfLv3) ? 3 : (r.flags & kQfLv2) ? 2 : (r.flags & kQfSub) ? 1 : 0;
}
