int g_chapCpOpen = -1;                       // 0.21.9: the kUnits index whose checkpoints are shown (-1 = none);
                                             // 0.22.37: a kChapOrder row as kChapRowKey + row index (return visits)
char g_chapCpArg[kQbViewMax][72];            // 0.21.9: the cp.jump arguments of this frame's checkpoint rows
const ChapOrder *ChapOrderOf(int unit) {
    if (unit < 0 || unit >= kUnitCount) return nullptr;
    for (const ChapOrder &c : kChapOrder)
        if (!_stricmp(c.unit, kUnits[unit].unit)) return &c;
    return nullptr;
}
// 0.22.37 (P5): a unit row's key - its kChapOrder row (a unit may have two: the return visit) or the kUnits index
const int kChapRowKey = 10000;
const int kChapOrderN = static_cast<int>(sizeof(kChapOrder) / sizeof(kChapOrder[0]));
int ChapRowKey(int unit, const ChapOrder *co) { return co ? kChapRowKey + static_cast<int>(co - kChapOrder) : unit; }
const ChapOrder *ChapRowOfKey(const char *key, int unit) {
    const int k = key && key[0] ? atoi(key) : -1;
    if (k >= kChapRowKey && k - kChapRowKey < kChapOrderN) return &kChapOrder[k - kChapRowKey];
    return ChapOrderOf(unit);
}
int ChapCpCount(const ChapOrder *c) {
    int count = 0;
    for (const char *p = c ? c->cps : ""; *p; ++p)
        if (*p != ' ' && (p == c->cps || p[-1] == ' ')) ++count;
    return count;
}
// the units of group g in page order: kChapOrder first (play order), then the group's other units of kUnits;
// 0.22.37 (P5): rows[] = the kChapOrder row of each entry (a unit with a return visit comes twice, one per row)
int ChapUnits(int g, int *out, int max, const ChapOrder **rows = nullptr) {
    const char *key = kChapGroups[g].key;
    int n = 0;
    for (const ChapOrder &c : kChapOrder) {
        const int i = strcmp(c.group, key) ? -1 : UnitIndexOf(c.unit);
        if (i >= 0 && !strcmp(kUnits[i].group, key) && n < max) {
            if (rows) rows[n] = &c;
            out[n++] = i;
        }
    }
    for (int i = 0; i < kUnitCount && n < max; ++i) {
        if (strcmp(kUnits[i].group, key)) continue;
        bool have = false;
        for (int j = 0; j < n && !have; ++j) have = out[j] == i;
        if (!have) {
            if (rows) rows[n] = ChapOrderOf(i);
            out[n++] = i;
        }
    }
    if (!strcmp(key, kUnitsNoDataGroup))     // 0.21.10: the unused-slot group also lists left / right (they stay in DLC 1)
        for (const char *u : kUnitsNoData) {
            const int i = UnitIndexOf(u);
            bool have = i < 0;
            for (int j = 0; j < n && !have; ++j) have = out[j] == i;
            if (!have && n < max) {
                if (rows) rows[n] = ChapOrderOf(i);
                out[n++] = i;
            }
        }
    return n;
}
// a DLC 2 unit that is not the DLC 2 start: a direct load may skip the doppelganger setup
bool ChapDlc2Note(int unit) {
    return unit >= 0 && unit < kUnitCount && !strcmp(kUnits[unit].group, "DLC 2") && _stricmp(kUnits[unit].unit, kChapDlc2Start);
}
int QbPzRows(QbView *v, QbDyn *d, int max, bool de);   // 0.22.31 (Q106), section "0.22.31 joint puzzles"
// 0.22.31 (Q105): the heading "DE|EN" of a kChapOrder row in one language
void ChapHeadText(const char *head, bool de, char *o, size_t n) {
    const char *bar = head ? strchr(head, '|') : nullptr;
    if (!bar) { Out(o, n, "%s", head ? head : ""); return; }
    if (de) Out(o, n, "%.*s", static_cast<int>(bar - head), head);
    else Out(o, n, "%s", bar + 1);
}
bool ChapBaseGroup(const char *group) { return group && !strncmp(group, "Base game", 9); }   // 0.22.31
// 0.22.58 (S1): a chapter start row - a heading "Kapitel ..." / "Prolog ..." on the first visit (the SetChapterUIData
// callers, Q105), or a DLC start (the DLCs have no sub-chapters: Q1a, the title card ran only in base units)
bool ChapIsStartRow(const ChapOrder *co, const char *unit) {
    const char *dlc = nullptr;
    if (unit && ChapDlcStart(unit, &dlc)) return true;
    return co && co->visit <= 1 && co->head && (!strncmp(co->head, "Kapitel ", 8) || !strncmp(co->head, "Prolog", 6));
}
int QbChapRows(QbView *v, QbDyn *d, int max, bool de) {
    char lara[48];
    PosLaraUnit(lara, sizeof(lara));
    int n = 0, rows = 0;
    n += QbPzRows(v, d, max, de);            // 0.22.31 (Q106): group "Raetsel" (uber objects of the loaded units) first
    for (int g = 0; g < kChapGroupN && n < max; ++g) {
        int order[kUnitCount + 16];          // 0.21.9: play order for DLC 1 / DLC 2 (kChapOrder); 0.22.37: + return visits
        const ChapOrder *orderRow[kUnitCount + 16];
        const int count = ChapUnits(g, order, kUnitCount + 16, orderRow);
        const bool open = g_chapOpen == g;
        QbView &w = v[n];
        QbDyn &q = d[n];
        memset(&w, 0, sizeof(w));
        memset(&q, 0, sizeof(q));
        w.src = -1;
        Out(w.name, sizeof(w.name), "%s %s (%d)", open ? "[-]" : "[+]", de ? kChapGroups[g].de : kChapGroups[g].en, count);
        Out(w.state, sizeof(w.state), "%s", open ? (de ? "links = zu" : "left = close") : (de ? "rechts = auf" : "right = open"));
        if (!strcmp(kChapGroups[g].key, "DLC 2"))
            Out(w.count, sizeof(w.count), "%s", de ? "besser Start + laufen" : "better start + walk");
        else if (!strcmp(kChapGroups[g].key, kUnitsNoDataGroup))   // 0.21.10
            Out(w.count, sizeof(w.count), "%s", de ? "nie gebaute Pl\303\244tze" : "never-built slots");   // 0.22.48
        else if (ChapBaseGroup(kChapGroups[g].key))   // 0.22.31 (Q105)
            Out(w.count, sizeof(w.count), "%s", de ? "Debug, ohne Story" : "debug, no story");   // count[24]
        w.col = kQbChapter;
        w.stateCol = IM_COL32(170, 170, 170, 255);
        q.kind = kQdChapGroup;
        q.intro = g;
        ++n;
        if (!open) continue;
        bool ringShown = false;
        for (int j = 0; j < count && n < max && rows < kQbViewMax; ++j) {
            const int i = order[j];
            const ChapOrder *co = orderRow[j];   // 0.21.9: ring mark, checkpoints (0.22.37: the row, not the unit's first)
            if (co && co->ring && !ringShown) {  // 0.21.9: the loop's units under one heading
                QbDynLabel(&v[n], &d[n], de ? "Rundweg (Richtung nicht in den Daten)" : "Loop (direction not in the data)");
                ringShown = true;
                if (++n >= max) break;
            }
            if (co && co->head) {                // 0.22.31 (Q105): chapter start / loop note before the unit
                char head[160];
                ChapHeadText(co->head, de, head, sizeof(head));
                QbDynLabel(&v[n], &d[n], head);
                if (++n >= max) break;
            }
            QbRow &r = g_chapRow[rows];
            // 0.22.58 (S1): a chapter start row (heading "Kapitel ..." / "Prolog ...", first visit; the DLC starts) = the
            // chapter rows' path (ChapSteps: new game data, the intro); every other unit row = chapter.unit (state kept)
            if (ChapIsStartRow(co, kUnits[i].unit))
                r = {kUnits[i].unit, kUnits[i].unit, "level.load", kUnits[i].unit, kQbAction, -1, kQcNone, 0, kQbChapter,
                     kQfConfirm | kQfBackup};
            else
                r = {kUnits[i].unit, kUnits[i].unit, "chapter.unit", kUnits[i].unit, kQbAction, -1, kQcNone, 0, kQbChapter,
                     kQfConfirm};
            QbView &x = v[n];
            QbDyn &y = d[n];
            memset(&x, 0, sizeof(x));
            memset(&y, 0, sizeof(y));
            x.src = -1;
            char key[160];
            Out(key, sizeof(key), "%d/%s %s", g_qbPage, r.id, r.arg);   // QbActRow's confirmation key
            const bool armed = QbArmed(key), note = ChapDlc2Note(i), here = lara[0] && !_stricmp(lara, kUnits[i].unit);
            const bool noDrm = UnitNoDrm(i);     // 0.21.9: grey, not loadable
            const bool unused = UnitUnused(i);   // 0.21.10: one of the six slots without data (never built)
            const int cpsOwn = ChapCpCount(co);
            const int gcps = CcRowCount(kUnits[i].unit);   // 0.22.69 (B4 1): the unit's checkpoints from the game data
            const int cps = cpsOwn + gcps;
            const int rowKey = ChapRowKey(i, co);   // 0.22.37: one row of a unit with a return visit opens alone
            const bool cpOpen = cps > 0 && g_chapCpOpen == rowKey;
            char more[48] = "";
            if (cps) Out(more, sizeof(more), "  %s %d CP", cpOpen ? "[-]" : "[+]", gcps ? gcps : cpsOwn);
            Out(x.name, sizeof(x.name), "  %s%s%s%s", kUnits[i].unit, co && co->ring ? (de ? " (Rundweg)" : " (loop)") : "",
                co && co->visit > 1 ? (de ? " (R\303\274ckweg)" : " (return)") : "", more);
            Out(x.state, sizeof(x.state), "%s", unused ? (de ? "ungenutzt" : "unused") : noDrm ? (de ? "keine .drm" : "no .drm")
                                                : armed ? (de ? "nochmal rechts!" : "right again!")
                                                : cps ? (de ? "rechts 2x, links: CP" : "right 2x, left: CP") : (de ? "rechts 2x" : "right 2x"));
            Out(x.count, sizeof(x.count), "%s", unused ? (de ? "nie gebaut" : "never built")   // 0.22.48
                                                : here ? (de ? "Lara hier" : "Lara here")
                                                : noDrm && UnitNameNoArchive(kUnits[i].unit) ? (de ? "kein PC-Archiv" : "no PC archive")
                                                : noDrm ? (de ? "nicht ladbar" : "not loadable")
                                                : note ? (de ? "Doppel-Zustand?" : "doppel state?")
                                                : !strcmp(r.id, "chapter.unit") ? (g_chUnitFresh ? (de ? "frisch (Test)" : "fresh (test)")
                                                                                  : (de ? "Stand bleibt" : "state kept"))
                                                : "");   // 0.22.58 (S1): chapter.unit rows
            x.col = noDrm ? IM_COL32(130, 130, 130, 255) : here ? IM_COL32(150, 240, 150, 255) : kQbChapter;
            x.stateCol = noDrm ? IM_COL32(130, 130, 130, 255) : armed ? IM_COL32(255, 110, 90, 255) : note ? IM_COL32(255, 190, 90, 255)
                                                                                                       : IM_COL32(235, 235, 235, 255);
            y.kind = kQdChap;
            y.intro = rows++;
            y.loaded = note;
            strncpy_s(y.unit, sizeof(y.unit), kUnits[i].unit, _TRUNCATE);
            Out(y.arg, sizeof(y.arg), "%d", rowKey);   // 0.22.37: QbChapAct / ChapFootHint find the row again
            ++n;
            if (!cpOpen) continue;
            // 0.21.9: the open unit's checkpoints - cp.jump <unit> <intro> (backup, unit.go, wait.unit, dbg.cpgo), right 2x
            char ids[160];
            strncpy_s(ids, sizeof(ids), co ? co->cps : "", _TRUNCATE);
            char *context = nullptr;
            for (char *id = strtok_s(ids, " ", &context); id && n < max && rows < kQbViewMax; id = strtok_s(nullptr, " ", &context)) {
                Out(g_chapCpArg[rows], sizeof(g_chapCpArg[rows]), "%s %s%s", kUnits[i].unit, id,
                    ChapBaseGroup(kUnits[i].group) ? " force" : "");   // 0.22.31 (Q105): base game = player.goto force
                QbRow &c = g_chapRow[rows];
                c = {kUnits[i].unit, kUnits[i].unit, "cp.jump", g_chapCpArg[rows], kQbAction, -1, kQcNone, 0, kQbChapter,
                     kQfConfirm};
                QbView &cx = v[n];
                QbDyn &cy = d[n];
                memset(&cx, 0, sizeof(cx));
                memset(&cy, 0, sizeof(cy));
                cx.src = -1;
                Out(key, sizeof(key), "%d/%s %s", g_qbPage, c.id, c.arg);
                const bool cpArmed = QbArmed(key);
                const bool ghoul = !_stricmp(kUnits[i].unit, "dlc_yggdrasil_end") && !strcmp(id, "9608");
                Out(cx.name, sizeof(cx.name), "      CP %s", id);
                Out(cx.state, sizeof(cx.state), "%s", cpArmed ? (de ? "nochmal rechts!" : "right again!") : (de ? "rechts 2x" : "right 2x"));
                Out(cx.count, sizeof(cx.count), "%s", ghoul ? (de ? "020_ghoul sofort" : "020_ghoul at once") : "");
                cx.col = kQbChapter;
                cx.stateCol = cpArmed ? IM_COL32(255, 110, 90, 255) : IM_COL32(235, 235, 235, 255);
                cy.kind = kQdChapCp;
                cy.intro = rows++;
                cy.loaded = note;
                strncpy_s(cy.unit, sizeof(cy.unit), kUnits[i].unit, _TRUNCATE);
                strncpy_s(cy.arg, sizeof(cy.arg), id, _TRUNCATE);
                ++n;
            }
            // 0.22.69 (B4 1): the unit's checkpoints from the game data - chapter.cp <unit> <id> (the game's restart, right 2x)
            int gidx[64];
            const int gn = CcRowsOf(i, gidx, 64);
            for (int k = 0; k < gn && n < max && rows < kQbViewMax; ++k) {
                const truintro::CpScanRow &gr = g_ccRows[gidx[k]];
                Out(g_chapCpArg[rows], sizeof(g_chapCpArg[rows]), "%s %lu", kUnits[i].unit, gr.intro);
                QbRow &c = g_chapRow[rows];
                c = {kUnits[i].unit, kUnits[i].unit, "chapter.cp", g_chapCpArg[rows], kQbAction, -1, kQcNone, 0, kQbChapter,
                     kQfConfirm};
                QbView &cx = v[n];
                QbDyn &cy = d[n];
                memset(&cx, 0, sizeof(cx));
                memset(&cy, 0, sizeof(cy));
                cx.src = -1;
                Out(key, sizeof(key), "%d/%s %s", g_qbPage, c.id, c.arg);
                const bool gArmed = QbArmed(key);
                Out(cx.name, sizeof(cx.name), "      %s %lu", de ? "Ab Checkpoint" : "From checkpoint", gr.intro);
                Out(cx.state, sizeof(cx.state), "%s", gArmed ? (de ? "nochmal rechts!" : "right again!") : (de ? "rechts 2x" : "right 2x"));
                Out(cx.count, sizeof(cx.count), "%s", de ? "Spiel-Neustart" : "game restart");
                cx.col = kQbChapter;
                cx.stateCol = gArmed ? IM_COL32(255, 110, 90, 255) : IM_COL32(235, 235, 235, 255);
                cy.kind = kQdChapGcp;
                cy.intro = rows++;
                cy.loaded = false;
                strncpy_s(cy.unit, sizeof(cy.unit), kUnits[i].unit, _TRUNCATE);
                Out(cy.arg, sizeof(cy.arg), "%lu", gr.intro);
                ++n;
            }
        }
    }
    return n;
}
// 0.21.9: the footer's key line on page Kapitel (unit rows with checkpoints, checkpoint rows, units without a DRM)
bool ChapFootHint(const QbDyn &q, bool de, char *o, size_t n) {
    const int u = UnitIndexOf(q.unit);
    const char *t = nullptr;
    if (q.kind == kQdChapCp) t = de ? "rechts 2x: Sicherung, Unit, Checkpoint (ohne Fliegen)"
                                    : "right 2x: backup, unit, checkpoint (no flight)";   // 0.22.55
    else if (q.kind == kQdChapGcp) t = de ? "rechts 2x: Sicherung, Neustart des Spiels am Checkpoint (ohne Intro)"
                                          : "right 2x: backup, the game's restart at the checkpoint (no intro)";   // 0.22.69
    else if (q.kind == kQdPz)                // 0.22.31 (Q106)
        t = q.arg[0] ? (de ? "rechts 2x: Gelenk ins Ziel (Cheat), links: Stopp" : "right 2x: joint into the target (cheat), left: stop")
                     : (de ? "nur Anzeige (Ereignis / anderer Knoten)" : "list only (event / other node)");
    else if (q.kind != kQdChap) return false;
    else if (UnitUnused(u)) t = de ? "ungenutzt - nur in der Unit-Liste, nie gebaut, nicht ladbar"
                                   : "unused - only in the unit list, never built, not loadable";   // 0.22.48
    else if (UnitNoDrm(u)) t = de ? "keine .drm in mods - nicht ladbar" : "no .drm in mods - not loadable";
    else if (ChapCpCount(ChapRowOfKey(q.arg, u)) || CcRowCount(q.unit))   // 0.22.69: + game-data checkpoints
        t = de ? "rechts 2x: Sicherung + laden   links: Checkpoints auf / zu"
                                                 : "right 2x: backup + load   left: checkpoints open / close";
    else return false;
    Out(o, n, "%s", t);
    return true;
}
// page Kapitel: right / left / X (dir kQbXDir) on a group or a unit row
void QbChapAct(const QbDyn &q, int dir) {
    const bool de = g_qbLang == 0;
    if (q.kind == kQdChapGroup) {
        const int g = static_cast<int>(q.intro);
        if (g < 0 || g > kChapGroupN) return;   // 0.22.31: g == kChapGroupN = the Q106 group "Raetsel"
        const char *name = g == kChapGroupN ? (de ? "R\303\244tsel" : "Puzzles") : de ? kChapGroups[g].de : kChapGroups[g].en;
        const bool open = dir == kQbXDir ? g_chapOpen != g : dir > 0;
        if (open == (g_chapOpen == g)) {
            QbResult(false, "%s: %s", name, open ? (de ? "schon auf" : "already open") : (de ? "schon zu" : "already closed"));
            return;
        }
        g_chapOpen = open ? g : -1;          // one group open at a time
        QbResult(false, "%s: %s", name, open ? (de ? "auf" : "open") : (de ? "zu" : "closed"));
        return;
    }
    const int k = static_cast<int>(q.intro);
    if (k < 0 || k >= kQbViewMax) return;
    const QbRow &r = g_chapRow[k];
    if (q.kind == kQdChap) {                 // 0.21.9: units without a DRM; left = the unit's checkpoints
        const int u = UnitIndexOf(q.unit);
        if (UnitUnused(u)) {                 // 0.21.10: the proven result + the engine's reaction (0.22.48: readable)
            QbResult(true, "%s: %s", q.unit, de ? "ungenutzt - nur in den Unit-Listen genannt, nie gebaut (in keinem "
                                                  "Archiv, nicht in mods); Laden = Fehlerfenster \"Can't open file\" + "
                                                  "Spielende - nicht angeboten"
                                                : "unused - only named in the unit lists, never built (in no archive, not "
                                                  "in mods); a load = error box \"Can't open file\" + the game exits - not "
                                                  "offered");
            return;
        }
        if (UnitNoDrm(u)) {
            if (UnitNameNoArchive(q.unit))   // 0.22.31 (Q105)
                QbResult(true, "%s: %s", q.unit, de ? "in keinem PC-Archiv und nicht in mods (Q105) - nicht ladbar"
                                                    : "in no PC archive and not in mods (Q105) - not loadable");
            else
                QbResult(true, "%s: %s", q.unit, de ? "keine .drm in mods - nicht ladbar" : "no .drm in mods - not loadable");
            return;
        }
        if (dir == -1 && (ChapCpCount(ChapRowOfKey(q.arg, u)) || CcRowCount(q.unit))) {   // 0.22.69: + game data
            const int key = q.arg[0] ? atoi(q.arg) : u;   // 0.22.37: the row key (return visits open alone)
            const bool open = g_chapCpOpen != key;
            g_chapCpOpen = open ? key : -1;  // one unit's checkpoints at a time
            QbResult(false, "%s: %s", q.unit, open ? (de ? "Checkpoints auf (rechts 2x = hin)" : "checkpoints open (right 2x = go)")
                                                   : (de ? "Checkpoints zu" : "checkpoints closed"));
            return;
        }
    }
    char key[160];
    Out(key, sizeof(key), "%d/%s %s", g_qbPage, r.id, r.arg);
    const bool first = dir != -1 && !QbArmed(key);
    QbActRow(g_qbPage, r, dir == kQbXDir ? 1 : dir);   // the chapter rows' path: confirm, save.backup, level.load
    if (first && q.loaded)                   // DLC 2 unit: the note with the confirmation
        QbResult(true, "%s: %s", r.arg, de ? "Doppelg\303\244ngerin evtl. nicht aufgesetzt (besser DLC-2-Start + laufen) - "
                                             "rechts / X nochmal = laden" : "doppelganger state may be missing (better the "
                                             "DLC 2 start + walk) - right / X again = load");
}
// the help line of a unit row (0.21.9: also of a checkpoint row)
bool ChapHelp(const QbDyn &q, bool de, char *o, size_t n) {
    if (q.kind == kQdChapGcp) {              // 0.22.69 (B4 1)
        Out(o, n, "%s", de ? "Wie nach dem Tod: Lara am Checkpoint, Intro bleibt gespielt" : "As after a death: Lara at the "
                             "checkpoint, the intro stays played");
        return true;
    }
    if (q.kind == kQdChapCp) {               // 0.21.9
        if (!_stricmp(q.unit, "dlc_yggdrasil_end") && !strcmp(q.arg, "9608"))
            Out(o, n, "%s", de ? "CP 9608 liegt wohl im Trigger 10026: 020_ghoul sofort" : "CP 9608 is likely inside trigger "
                                 "10026: 020_ghoul at once");
        else if (ChapBaseGroup(kUnits[UnitIndexOf(q.unit) < 0 ? 0 : UnitIndexOf(q.unit)].group))   // 0.22.31 (Q105)
            Out(o, n, "%s", de ? "Debug-Laden ohne Story-Stand, dann zum CP (force)" : "Debug load without story state, "
                                 "then to the CP (force)");
        else Out(o, n, "%s", de ? "Sicherung, dann in die Unit und zum Checkpoint (ohne Flug)" : "Backup, then into the "
                                  "unit and to the checkpoint (no flight)");   // 0.22.55
        return true;
    }
    if (UnitNameNoArchive(q.unit)) {         // 0.22.31 (Q105)
        Out(o, n, "%s", de ? "In keinem PC-Archiv (Q105); Laden h\303\244ngt im Ladebild" : "In no PC archive (Q105); a load "
                             "hangs in the loading screen");
        return true;
    }
    if (UnitNameUnused(q.unit))              // 0.21.10: proven result + engine reaction, at most 60 characters each
        Out(o, n, "%s", de ? "Nur in der Unit-Liste, nie gebaut; Laden = Fehler + Ende" : "Only in the unit list, never "
                             "built; a load: error + exit");   // 0.22.48: readable (was the package names)
    else if (UnitNameNoDrm(q.unit))          // 0.21.9
        Out(o, n, "%s", de ? "Keine .drm in mods: nur in unitlist.txt, nicht ladbar" : "No .drm in mods: in unitlist.txt "
                             "only, not loadable");
    else if (q.loaded) Out(o, n, "%s", de ? "Direkt laden setzt die Doppelg\303\244ngerin evtl. nicht auf" : "A direct load may not set "
                                      "up the doppelganger state");
    else if (!ChapIsStartRow(ChapRowOfKey(q.arg, UnitIndexOf(q.unit)), q.unit))   // 0.22.58 (S1)
        Out(o, n, "%s", g_chUnitFresh ? (de ? "Im Level: Sicherung + frischer Start mit Intro-Marken" : "In a level: backup + "
                                             "fresh start with intro marks")
                                      : (de ? "Im Level: Sicherung + laden, Stand bleibt" : "In a level: backup + load, "
                                             "state kept"));
    else Out(o, n, "%s", de ? "Hauptmen\303\274: Missionsstart; im Level: Sicherung + laden"   // 0.22.50 D
                            : "Main menu: mission start; in a level: backup + load");
    return true;
}
// 0.22.55 chapter.reload (package P2a, owner 2026-11-15 "Aktuelles Kapitel neu laden": the start of the current chapter,
// as clean as a mission start; "Unit neu laden" / level.reload only reloads Lara's unit). The chapter = page Kapitel's own
// table kChapOrder: Lara's unit (stream entry of GameTracker+0xc0, else GameTracker+0x38), its first row (a unit with a
// return visit counts as its way in), then back to the nearest row of the same group whose heading is a chapter start
// ("Kapitel ..." / "Prolog ..." - the SetChapterUIData callers, Q105); without one the group's first row (DLC 1 / DLC 2:
// dlc_level1_start / dlc_level2_start). That unit runs through ChapSteps, the one path of the chapter rows: save.backup
// kapitel, then in a level the pause menu's DLC start (level.start dlc1 / dlc2 = RegisterAcceptChanges case 8 with the
// new-game block: the unit's own costume, DLC 2's doppelganger) or level.load for a base-game chapter (debug, no story
// values - the only in-level path verified for those), from the main menu the mission start. Refused without a level.
const ChapOrder *ChapStartOf(const char *lara, const ChapOrder **at) {
    *at = nullptr;
    int k = -1;
    for (int i = 0; i < kChapOrderN && k < 0; ++i)
        if (lara && lara[0] && !_stricmp(kChapOrder[i].unit, lara)) k = i;
    if (k < 0) return nullptr;
    *at = &kChapOrder[k];
    const char *group = kChapOrder[k].group;
    int first = k;
    for (int i = k; i >= 0; --i) {
        if (strcmp(kChapOrder[i].group, group)) continue;
        first = i;
        const char *h = kChapOrder[i].head;
        if (h && (!strncmp(h, "Kapitel ", 8) || !strncmp(h, "Prolog", 6))) return &kChapOrder[i];
    }
    return &kChapOrder[first];
}
// 0.22.58 (S6): Lara's unit for the chapter = her stream unit, unless she is off the map - no stream unit, a unit outside
// the chapter table, in the fall record 1068 (fall watch), or more than 3000 units below the newest safe-ground spot; then
// the newest safe-ground spot's stream unit (SafeSpot.lara) when that one is in the table. Last: GameTracker+0x38.
// from = the unit the answer came from, how = "" or why the safe ground was taken
bool ChapInTable(const char *unit) {
    for (int i = 0; unit && unit[0] && i < kChapOrderN; ++i)
        if (!_stricmp(kChapOrder[i].unit, unit)) return true;
    return false;
}
void ChapLaraUnit(char *lara, size_t ln, char *how, size_t hn) {
    lara[0] = how[0] = 0;
    PosLaraUnit(lara, ln);
    SafeSpot s = {};
    bool have = false;
    EnterCriticalSection(&g_safeLock);
    if (g_safeCount) { s = g_safe[(g_safeNext + kSafeMax - 1) % kSafeMax]; have = true; }
    LeaveCriticalSection(&g_safeLock);
    float p[3] = {0.0f, 0.0f, 0.0f}, r[3];
    DWORD inst = 0;
    const bool pos = ReadLara(p, r, &inst);
    const char *off = !lara[0] ? "no stream unit" : !ChapInTable(lara) ? "unit not in the chapter table"
                    : g_fwIn ? "falling (record 1068)" : have && pos && p[2] < s.p[2] - 3000.0f ? "far below the safe ground"
                    : nullptr;
    if (off && have && ChapInTable(s.lara)) {
        Out(how, hn, "off the map (%s: %s) - safe ground %lu s ago", off, lara[0] ? lara : "-", (GetTickCount() - s.tick) / 1000);
        strncpy_s(lara, ln, s.lara, _TRUNCATE);
        return;
    }
    if (!lara[0]) CurrentUnit(lara, ln);
}
bool ChapReloadPlan(char *unit, size_t un, char *chapter, size_t cn, char *o, size_t on) {
    const bool de = g_qbLang == 0;
    char lara[64] = "", how[160] = "";
    ChapLaraUnit(lara, sizeof(lara), how, sizeof(how));   // 0.22.58 (S6)
    if (!InLevel() || !lara[0]) { Out(o, on, "%s", de ? "braucht ein Level (Laras Unit)" : "needs a level (Lara's unit)"); return false; }
    const ChapOrder *at = nullptr, *start = ChapStartOf(lara, &at);
    if (!start) {
        Out(o, on, de ? "%s steht nicht in der Kapitel-Tabelle (Seite Kapitel)" : "%s is not in the chapter table (page "
            "Kapitel)", lara);
        return false;
    }
    strncpy_s(unit, un, start->unit, _TRUNCATE);
    if (start->head) ChapHeadText(start->head, de, chapter, cn);
    else Out(chapter, cn, "%s", !strcmp(start->group, "DLC 1") ? (de ? "DLC 1 Unter der Asche" : "DLC 1 Beneath the Ashes")
                              : !strcmp(start->group, "DLC 2") ? (de ? "DLC 2 Laras Schatten" : "DLC 2 Lara's Shadow")
                              : start->group);
    char *cut = strchr(chapter, '(');        // "Prolog (Croft Manor brennt; ...)" -> "Prolog"
    if (cut && cut > chapter) { *cut = 0; while (cut > chapter && cut[-1] == ' ') *--cut = 0; }
    return true;
}
// 0.22.58 (S7): true while Lara's chapter is a DLC (DLC 1 / DLC 2 have no sub-chapters: the row reloads the DLC start)
bool ChapInDlc() {
    char lara[64], how[160];
    ChapLaraUnit(lara, sizeof(lara), how, sizeof(how));
    const ChapOrder *at = nullptr, *start = ChapStartOf(lara, &at);
    return start && !strncmp(start->group, "DLC ", 4);
}
// 0.22.58 (S6): "<start unit> (<Lara's unit>)" - the unit the row would load and the one it was chosen from (the bar's
// state column shows ~40 characters); "(sicherer Boden ...)" when Lara is off the map
void ValChapReload(char *o, size_t n) {
    char unit[64] = "", chapter[96] = "", why[160] = "", lara[64], how[160];
    if (!ChapReloadPlan(unit, sizeof(unit), chapter, sizeof(chapter), why, sizeof(why))) { Out(o, n, "%s", why); return; }
    ChapLaraUnit(lara, sizeof(lara), how, sizeof(how));
    const bool de = g_qbLang == 0;
    if (how[0]) Out(o, n, "%s (%s %s)", unit, de ? "sicherer Boden" : "safe ground", lara);
    else if (_stricmp(lara, unit)) Out(o, n, "%s (%s %s)", unit, de ? "von" : "from", lara);
    else Out(o, n, "%s", unit);
}
bool RunChapReload(const char *, char *o, size_t n) {
    char unit[64] = "", chapter[96] = "", steps[200], title[64], why[300];
    if (InLevel() && K1Gate("chapter.reload", o, n)) return false;   // 0.22.67 (B1 K1)
    if (!ChapReloadPlan(unit, sizeof(unit), chapter, sizeof(chapter), o, n)) return false;
    {                                        // 0.22.58 (S6): which unit the chapter came from
        char lara[64], how[160];
        ChapLaraUnit(lara, sizeof(lara), how, sizeof(how));
        Log(1, "chapter.reload: Lara's unit %s%s%s", lara, how[0] ? " - " : " (her stream unit)", how);
    }
    bool menu = false;
    if (!ChapSteps(unit, steps, sizeof(steps), &menu, why, sizeof(why))) {
        Log(1, "chapter.reload: %s -> %s refused: %s", chapter, unit, why);
        Out(o, n, "%s", why);
        return false;
    }
    Out(title, sizeof(title), "chapter %s", unit);
    Log(1, "chapter.reload (src=%s): Lara's chapter '%s' starts in %s -> shortcut '%s'%s", ShotSource("chapter.reload"),
        chapter, unit, steps, menu ? " (the game's mission / DLC start)" : " (level.load, debug)");
    char started[200];
    if (!ShortcutStart(steps, title, started, sizeof(started))) { Out(o, n, "%s", started); return false; }
    const bool de = g_qbLang == 0;
    Out(o, n, "%s: %s %s", chapter, unit, menu ? (de ? "- Sicherung, dann Start wie das Spiel" : "- backup, then the start as "
                                                  "the game") : (de ? "- Sicherung, dann laden (debug)" : "- backup, then "
                                                                 "load (debug)"));
    return true;
}
// ---- end of 0.21.7 chapter units ----

// ---- 0.22.31 page Kapitel group "Raetsel" (Q106; engine part in section "0.22.31 joint puzzles") ----
// Render thread, refreshed at most every 300 ms while the group is open: the uber instances of the loaded units, nearest
// first. Objects whose graph has joint-range transitions (condition 14 / 15, any node) are puzzles (at most 16): one row
// per object (current node, distance) and one row per joint-range transition of its CURRENT node - joint index, kind,
// the live value (the engine's getter, read only), the target range and node. An "enter" row of a hinge / rail joint
// runs joint.set <intro> <index> <middle of the range> (right twice; a cheat), left stops a running drive. Other uber
// instances within [Debug] UberRadius (event / command / time puzzles, gates) follow as a list (at most 8, list only).
// 0.22.56 (package P2b): the joint-range rows are a list only - their "solve" (joint.set to the middle of a range) drove
// the chapel shadow door's rail while both locks were closed (2026-11-15); the new sections above them (section
// "0.22.56 puzzles nearby") run only the game's own paths. arg = "<item> <argument>" of a row that runs something.
struct PzRow { char name[112], state[64], count[24], arg[64]; ImU32 col; bool act; };   // 0.22.59: act = an action row
const int kPzRowMax = 112;
PzRow g_pzRows[kPzRowMax];
int g_pzN = 0, g_pzPuzzles = 0, g_pzOthers = 0;
DWORD g_pzAt = 0;
bool PzHasJoint(DWORD b) {                   // any condition 14 / 15 transition in the graph
    DWORD desc = 0, count = 0, nodes = 0;
    if (!ReadDword(b + 0x78, &desc) || !desc || !ReadDword(desc + 4, &count) || count > 64 || !ReadDword(desc + 8, &nodes) ||
        !nodes)
        return false;
    for (DWORD k = 0; k < count; ++k) {
        DWORD tn = 0, tp = 0;
        if (!ReadDword(nodes + 28 * k + 0xc, &tn) || tn > 64 || !ReadDword(nodes + 28 * k + 0x10, &tp) || !tp) continue;
        for (DWORD j = 0; j < tn; ++j) {
            DWORD t = 0, cond = 0;
            if (ReadDword(tp + 4 * j, &t) && t && ReadDword(t + 0x18, &cond) && (cond == 14 || cond == 15)) return true;
        }
    }
    return false;
}
PzRow *PzAdd(ImU32 col) {
    if (g_pzN >= kPzRowMax) return nullptr;
    PzRow *r = &g_pzRows[g_pzN++];
    memset(r, 0, sizeof(*r));
    r->col = col;
    return r;
}
// ---- 0.22.56 puzzles nearby (package P2b; ENGINE section 9 "Switch -> target, static (P4)", "Target behaviour from
// the graph (P4)", the P5 rows "Chapel plates ...", "Chapel switches and shadow pillars", TruLink 0.5 README) ----
// Built from TruLink 0.5's decoders (TruLinkObj.h, the same byte check rows) and run through TruLink's own action code
// (TruLinkAct.h) - nothing here writes a joint limit, a node or a lock directly. Render thread = game thread; the list
// is refreshed at most every 300 ms while the group is open, within 2 x [Debug] UberRadius of Lara:
//   switches   an instance whose class chain has the switch base (P5 base 3637: member 0 a 'modifiable' at +4, ints at
//              +8 .. +32; +16 off, +20 on, +24 disabled, +32 current): state, "gesperrt: Platte x nicht gedrueckt" when
//              a plate it names is up, "bereits benutzt" when it is on and its target is one-shot; its target and the
//              target's kind from the graph (P4 rules: one-shot / ring n / toggle / repeatable / reversible / auto-reset)
//   plates     name holds "plate": the base's stickybool (P5 +92 = pressed), the rail value, weights and Lara on it
//   targets    multibody anchors and uber objects: kind, node, "braucht Gewicht auf Platte x" from reverse refs
//   figures    a multibody with an object check (condition 9): each checked link's node against the check with the most
//              entries (chapel: all four on position_a), the steps left along its trigger edges, the command that steps
//              it (an entry with one event record to that link) and the switch learned at run time ("Schalter x noch
//              n mal"); the fire state from the plate that names the igniter that names the object (P5: the check acts
//              only while 4818 burns); row "Figuren auf Ziel setzen" = puzzle.figures (those commands, one per idle link)
//   doors      a hinge with its motor on and a velocity != 0: "offen 148 Grad, zu in ~42 s" (angle / motor speed);
//              "Tuer offen halten" = puzzle.hold (TruLinkAct drive, hold-until-off, the saved motor values back at off)
//   weights    a body + class 'portablebase': where it lies; "zu mir" / "zurueck" = puzzle.bring (TruLinkAct placement)
// PzGameTick (game frame): the hold drive, the figures job, the state log (node changes of nearby uber states, every
// 250 ms) and the switch learning (a ring link moved while Lara stood at a switch that names its object).
bool g_tlGrp[tlobj::kGrpCount];
int g_tlGrpRows[tlobj::kGrpCount];
int g_tlBad = -1;
DWORD g_tlFirstBad = 0;
void PzTlCheck() {
    g_tlBad = tlobj::RunChecks(g_tlGrp, &g_tlFirstBad, g_tlGrpRows);
    char groups[256] = "";
    for (int g = 0; g < tlobj::kGrpCount; ++g) {
        char one[40];
        Out(one, sizeof(one), "%s%s %d/%d", g ? ", " : "", tlobj::kGrpNames[g], g_tlGrp[g] ? g_tlGrpRows[g] : 0, g_tlGrpRows[g]);
        strncat_s(groups, sizeof(groups), one, _TRUNCATE);
    }
    Log(g_tlBad ? 0 : 1, "0.22.56 puzzles: TruLink 0.5 byte checks %d of %d rows bad (first 0x%08lx) - %s", g_tlBad,
        tlobj::kTlCheckCount, g_tlFirstBad, groups);
}
bool PzNeed(int a, int b = -1, int c = -1, int d = -1, int e = -1) {
    const int g[5] = {a, b, c, d, e};
    for (int i = 0; i < 5; ++i)
        if (g[i] >= 0 && !g_tlGrp[g[i]]) return false;
    return g_tlBad >= 0;
}
// switch base, plate flag, portable objects, graph behaviour, object checks, ring steps, motor-closed hinges: the pure
// reads in TruPuzzleCore.h (offline: TruLinkObjTest.exe 'puzzle <id>' on a full dump)
using namespace pzcore;
// the plate flag, read at most once per plate and refresh (the sticky store walk)
struct PzFlagMemo { DWORD inst; int flag; bool ok; };
PzFlagMemo g_pzFlagMemo[24];                 // one sticky store walk per plate and refresh (PzCollect clears it)
int g_pzFlagMemoN = 0;
bool PzPlateFlag(DWORD inst, int *flag) {
    for (int i = 0; i < g_pzFlagMemoN; ++i)
        if (g_pzFlagMemo[i].inst == inst) { *flag = g_pzFlagMemo[i].flag; return g_pzFlagMemo[i].ok; }
    int f = 0;
    const bool ok = PzPlateFlagRead(inst, &f);
    if (g_pzFlagMemoN < 24) g_pzFlagMemo[g_pzFlagMemoN++] = {inst, f, ok};
    if (ok) *flag = f;
    return ok;
}
// "offen 148 Grad, zu in ~42 s": the value against the limit the motor drives to, at its speed (PzDoorOf; 0.22.57: rails
// in units, the hinge value taken over the 180 / -180 wrap at the stop)
void PzDoorLine(const PzDoor &d, bool de, char *o, size_t n) {
    const float rest = fabsf(d.v - d.end);
    const char *unit = d.type == 1 ? "\302\260" : (de ? " Einh." : " units");
    if (rest <= (d.type == 1 ? 1.0f : 3.0f)) { Out(o, n, de ? "zu (%.0f%s)" : "closed (%.0f%s)", static_cast<double>(d.v), unit); return; }
    Out(o, n, de ? "offen %.0f%s, zu in ~%.0f s" : "open %.0f%s, closes in ~%.0f s", static_cast<double>(d.v), unit,
        static_cast<double>(rest / fabsf(d.perS)));
}
// the label line of a part (uber labels, key items, names): the motor-closed joint that moves THIS link (joint record
// B, A when B is the world) - 0.22.56 matched either body of the joint, the text could sit on another part (16.11. K3)
bool PzDoorText(DWORD inst, bool de, char *o, size_t n) {
    if (!PzNeed(tlobj::kGrpMulti, tlobj::kGrpJoint)) return false;
    const DWORD x = tlobj::MultiOfAny(inst);
    for (int i = 0; x && i < tlobj::JointCount(x); ++i) {
        PzDoor d;
        if (!PzDoorOf(x, i, &d) || d.part < 0 || tlobj::LinkInst(x, d.part) != inst) continue;
        if (!PzDoorIsOpen(d)) return false;  // 0.22.57: closed (and the locks' motor rails at their end): no line
        char t[64];
        PzDoorLine(d, de, t, sizeof(t));
        Out(o, n, "%s %s", de ? "T\303\274r" : "Door", t);
        return true;
    }
    return false;
}
// ---- runtime tables: learned switch -> ring link, the hold drive, the figures job, placements to undo ----
struct PzLearn { LONG anchor, sw; int link; };
PzLearn g_pzLearn[16];
int g_pzLearnN = 0;
LONG PzLearned(LONG anchor, int link) {
    for (int i = 0; i < g_pzLearnN; ++i)
        if (g_pzLearn[i].anchor == anchor && g_pzLearn[i].link == link) return g_pzLearn[i].sw;
    return 0;
}
// 0.22.59 (R1 point 9b, live 17.11. 23:00 "replaced by a new hold"): up to kPzHoldMax holds at the same time - each motor
// hold its own drive, each timer / counter hold its own keep; a new hold of the same door / gate replaces only that one
const int kPzHoldMax = 4;
tlact::DriveCtl g_pzHolds[kPzHoldMax] = {{{}, 0, "puzzle.hold", nullptr}, {{}, 0, "puzzle.hold", nullptr},
                                         {{}, 0, "puzzle.hold", nullptr}, {{}, 0, "puzzle.hold", nullptr}};
// the motor hold of joint jn of X (nullptr = none)
tlact::DriveCtl *PzMotorHoldOf(DWORD x, int jn) {
    for (tlact::DriveCtl &c : g_pzHolds)
        if (c.on && c.d.x == x && c.d.index == jn) return &c;
    return nullptr;
}
int PzMotorHolds() {
    int k = 0;
    for (const tlact::DriveCtl &c : g_pzHolds) k += c.on ? 1 : 0;
    return k;
}
// 0.22.57: the two other hold kinds (0.22.59: several at a time, one per gate)
//   timer   an auto-reset gate (P4: back on time alone, DLC 1 dlc_caverns_hall 25 s): while the link is in the hold node
//           (the node of the longest time condition on the way back) and no transition runs, its time in node
//           [b+0x88] is set to 0 each game frame - the condition "time >= 25 s" (0x4d3204) never holds; off = the time
//           runs again from 0 (the full time left)
//   counter a reversible gate with "set node" records in its object command table (plate gates: Raise / Lower): when
//           the link reaches a node of the closing side (the target of another set-node record and the nodes behind it
//           on internal edges), the opening record's entry is sent at once through X vf+4 (tlact::CmdExec, the plate's
//           own path) - the "Lower" does not stay; at most every 250 ms, 400 times
enum { kPhNone = 0, kPhTimer, kPhCounter };
struct PzKeep {
    volatile LONG on;
    int kind, link, node, openCmd, sent;
    LONG intro;
    DWORD inst, stamp, x, start, last, resets;
    float secs;
    BYTE closeSide[64];                      // counter: node k is on the closing side
    LONG lastNode;                           // 0.22.59: the check after - node changes of the held link are logged
    int nodeLines;
    bool opened;                             // 0.22.59 (9a): it was closed at the start - the first send opens it
};
PzKeep g_pzKeeps[kPzHoldMax] = {};
PzKeep *PzKeepOf(LONG intro) {
    for (PzKeep &q : g_pzKeeps)
        if (q.on && q.intro == intro) return &q;
    return nullptr;
}
int PzKeepHolds() {
    int k = 0;
    for (const PzKeep &q : g_pzKeeps) k += q.on ? 1 : 0;
    return k;
}
bool PzAnyHold() { return PzMotorHolds() + PzKeepHolds() > 0; }
// 0.22.57: switch -> command entry, read once per switch / target from the loaded scripts (PzSwitchEntry)
struct PzSwCmd { DWORD sw, swStamp, tgt; int entry, calls; };
PzSwCmd g_pzSwCmd[48];
int g_pzSwCmdN = 0;
int PzSwitchCmd(DWORD sw, DWORD tgt, int *calls) {
    const DWORD stamp = tlobj::D(sw + 0x44);
    for (int i = 0; i < g_pzSwCmdN; ++i)
        if (g_pzSwCmd[i].sw == sw && g_pzSwCmd[i].swStamp == stamp && g_pzSwCmd[i].tgt == tgt) {
            if (calls) *calls = g_pzSwCmd[i].calls;
            return g_pzSwCmd[i].entry;
        }
    int c = 0;
    const int e = PzSwitchEntry(sw, tgt, &c);
    static int ring = 0;                     // full: the oldest goes (no re-trace + log line every refresh)
    if (g_pzSwCmdN < 48) g_pzSwCmd[g_pzSwCmdN++] = {sw, stamp, tgt, e, c};
    else g_pzSwCmd[ring++ % 48] = {sw, stamp, tgt, e, c};
    const LONG si = static_cast<LONG>(tlobj::D(sw + 0x58)), ti = static_cast<LONG>(tlobj::D(tgt + 0x58));
    if (e >= 0)
        Log(1, "0.22.57 puzzle: switch %ld sends command entry %d to %ld (%d send(s) in the called function; read from the "
            "loaded scripts as tools/puzzle_switch_scan.py)", si, e, ti, c);
    else
        Log(1, "0.22.57 puzzle: switch %ld -> %ld: no command entry in its script (bind + call + uberobjectcommand not "
            "found)", si, ti);
    if (calls) *calls = c;
    return e;
}
struct PzFigJob {
    volatile LONG on;
    LONG anchor;
    DWORD stamp, start, lastSend;
    int links[16], want[16], cmd[16], sent;
};
PzFigJob g_pzFig = {};
struct PzPlaced { LONG intro; DWORD stamp; float pos[3], rot[3]; };
PzPlaced g_pzPlaced[8];
int g_pzPlacedN = 0;
// ---- the list ----
enum { kPoSwitch = 1, kPoPlate, kPoMulti, kPoUber, kPoWeight, kPoPole };
struct PzObj { DWORD inst; LONG intro; float pos[3], d2; int kind; char name[48]; };
const int kPoMax = 96, kPeMax = 1024;
PzObj g_po[kPoMax];
int g_poN = 0;
struct PzEdge { LONG from, to; };
PzEdge g_pe[kPeMax];
int g_peN = 0;
const PzObj *PzFind(LONG intro) {
    for (int i = 0; i < g_poN; ++i)
        if (g_po[i].intro == intro) return &g_po[i];
    return nullptr;
}
void PzCollect(DWORD player, const float *lara) {
    g_poN = g_peN = 0;
    g_pzFlagMemoN = 0;                       // plate flags are read again in this refresh
    const float rad = 2.0f * g_ubRadius, r2 = rad * rad;
    static DWORD seen[512];
    int nSeen = 0;
    tlobj::ForInstances([&](DWORD inst, int) {
        if (inst == player) return true;
        const DWORD so = tlobj::ScriptObj(inst);   // every instanceref of the loaded scripts (hints, refs)
        bool fresh = so != 0;
        for (int i = 0; fresh && i < nSeen; ++i) fresh = seen[i] != so;
        if (fresh && nSeen < 512) {
            seen[nSeen++] = so;
            const DWORD data = tlobj::D(so + 0xc);
            const LONG owner = static_cast<LONG>(tlobj::D(tlobj::ScriptOwner(inst) + 0x58));
            DWORD roots[16];
            const int depth = tlobj::ClassChain(so, roots, 16);
            for (int d = 0; d < depth; ++d)
                for (int k = 0; k < tlobj::MemberCount(roots[d]) && g_peN < kPeMax; ++k) {
                    tlobj::Member m;
                    if (!tlobj::MemberAt(roots[d], k, &m) || strcmp(m.type, "instanceref")) continue;
                    const LONG to = static_cast<LONG>(tlobj::D(data + m.offset));
                    if (to > 0 && to != owner) g_pe[g_peN++] = {owner, to};
                }
        }
        float p[3];
        if (g_poN >= kPoMax || !TlRead(inst + 0x20, p, 12)) return true;
        const float dx = p[0] - lara[0], dy = p[1] - lara[1], dz = p[2] - lara[2], d2 = dx * dx + dy * dy + dz * dz;
        if (!(d2 <= r2)) return true;
        PzObj o = {};
        o.inst = inst;
        o.intro = static_cast<LONG>(tlobj::D(inst + 0x58));
        o.pos[0] = p[0]; o.pos[1] = p[1]; o.pos[2] = p[2];
        o.d2 = d2;
        tlobj::InstName(inst, o.name, sizeof(o.name));
        PzSw sw;
        const DWORD b = tlobj::Uber(inst);
        if (PzSwitchOf(inst, &sw)) o.kind = kPoSwitch;
        else if (PzNameHas(o.name, "plate") && strncmp(o.name, "fx_", 3)) o.kind = kPoPlate;
        else if (tlobj::Multi(inst)) o.kind = kPoMulti;
        else if (tlobj::BodyOf(inst) && PzIsPortable(inst)) o.kind = PzNameHas(o.name, "pole") ? kPoPole : kPoWeight;
        else if (b && !tlobj::IsMulti(tlobj::D(b + 0x7c))) o.kind = kPoUber;
        if (!o.kind) return true;
        int at = g_poN++;                     // nearest first
        while (at > 0 && g_po[at - 1].d2 > d2) { g_po[at] = g_po[at - 1]; --at; }
        g_po[at] = o;
        return true;
    });
}
const char *PzMetres(float d2, char *o, size_t n) {
    Out(o, n, "%.1fm", static_cast<double>(sqrtf(d2) / kUnitsPerMetre));
    return o;
}
// weights / Lara on a plate (physics positions within 200 units across, 100 below .. 350 above the plate origin)
void PzOnPlate(const PzObj &pl, DWORD player, const float *lara, bool de, char *o, size_t n) {
    o[0] = 0;
    size_t used = 0;
    for (int i = 0; i < g_poN; ++i) {
        const PzObj &w = g_po[i];
        if (w.kind != kPoWeight && w.kind != kPoPole) continue;
        const float dx = w.pos[0] - pl.pos[0], dy = w.pos[1] - pl.pos[1], dz = w.pos[2] - pl.pos[2];
        if (dx * dx + dy * dy > 200.0f * 200.0f || dz < -100.0f || dz > 350.0f) continue;
        LabelAdd(o, n, &used, "%s%s %ld", used ? ", " : "", de ? "Gewicht" : "weight", w.intro);
    }
    (void)player;
    const float dx = lara[0] - pl.pos[0], dy = lara[1] - pl.pos[1], dz = lara[2] - pl.pos[2];
    if (dx * dx + dy * dy <= 200.0f * 200.0f && dz >= -100.0f && dz <= 350.0f) LabelAdd(o, n, &used, "%sLara", used ? ", " : "");
}
// 0.22.57: is weight w on plate pl (the PzOnPlate box: 200 units across, 100 below .. 350 above the plate origin)
bool PzOnThisPlate(const PzObj &w, const PzObj &pl) {
    const float dx = w.pos[0] - pl.pos[0], dy = w.pos[1] - pl.pos[1], dz = w.pos[2] - pl.pos[2];
    return dx * dx + dy * dy <= 200.0f * 200.0f && dz >= -100.0f && dz <= 350.0f;
}
// 0.22.57: up to max free weights for plate pl, nearest to it first (not carried by Lara, not on this plate; weights on
// another plate only after the loose ones); *onNow = weights on pl now
int PzFreeWeights(const PzObj &pl, DWORD player, LONG *ids, int max, int *onNow) {
    struct C { LONG intro; float score; };
    C c[16];
    int cn = 0;
    *onNow = 0;
    for (int i = 0; i < g_poN; ++i) {
        const PzObj &w = g_po[i];
        if (w.kind != kPoWeight) continue;
        if (PzOnThisPlate(w, pl)) { ++*onNow; continue; }
        if (tlobj::HolderOf(w.inst) && tlobj::HolderOf(w.inst) == player) continue;
        bool other = false;
        for (int p = 0; p < g_poN && !other; ++p) other = g_po[p].kind == kPoPlate && g_po[p].inst != pl.inst && PzOnThisPlate(w, g_po[p]);
        const float dx = w.pos[0] - pl.pos[0], dy = w.pos[1] - pl.pos[1], dz = w.pos[2] - pl.pos[2];
        // 0.22.61 (R4): the weights a counter script names (a trigger's instanceref: chapel weight counter) count for
        // the objective - they go first
        bool counted = false;
        for (int e = 0; e < g_peN && !counted; ++e) {
            if (g_pe[e].to != w.intro) continue;
            const DWORD ti = tlobj::InstByIntro(static_cast<DWORD>(g_pe[e].from));
            char tn[48];
            if (!ti) continue;
            tlobj::InstName(ti, tn, sizeof(tn));
            counted = PzNameHas(tn, "trigger");
        }
        const float score = dx * dx + dy * dy + dz * dz + (other ? 1.0e12f : 0.0f) - (counted ? 1.0e11f : 0.0f);
        if (cn < 16) {
            int at = cn++;
            while (at > 0 && c[at - 1].score > score) { c[at] = c[at - 1]; --at; }
            c[at] = {w.intro, score};
        }
    }
    const int n = cn < max ? cn : max;
    for (int i = 0; i < n; ++i) ids[i] = c[i].intro;
    return n;
}
// the fire of a ring object: an igniter ("ignit" in its name) naming it, and the plate naming that igniter (P5)
bool PzFire(LONG anchor, LONG *plate, int *flag) {
    for (int i = 0; i < g_peN; ++i) {
        if (g_pe[i].to != anchor) continue;
        const DWORD ig = tlobj::InstByIntro(static_cast<DWORD>(g_pe[i].from));
        char name[48];
        if (!ig) continue;
        tlobj::InstName(ig, name, sizeof(name));
        if (!PzNameHas(name, "ignit")) continue;
        for (int j = 0; j < g_peN; ++j) {
            if (g_pe[j].to != g_pe[i].from) continue;
            const DWORD pi = tlobj::InstByIntro(static_cast<DWORD>(g_pe[j].from));
            int f = 0;
            if (pi && PzPlateFlag(pi, &f)) { *plate = g_pe[j].from; *flag = f; return true; }
        }
    }
    return false;
}
// 0.22.57 (replaces the 0.22.56 learning as the first source): the switch that steps link `link` of multibody anchor
// `anchor` - a listed switch naming the anchor whose script sends a command entry with one record to that link
// (PzSwitchCmd, read from the loaded scripts; chapel: 4819 -> entry 0 = link 1, 4820 -> 3 = 3, 4821 -> 1 = 0, 4822 ->
// 2 = 2 on dump 26292, as P4's static scan); 0 = none
LONG PzDataSwitch(LONG anchor, DWORD anchorInst, DWORD x, int link) {
    if (!PzNeed(tlobj::kGrpCmd, tlobj::kGrpScript, tlobj::kGrpSuper)) return 0;
    for (int i = 0; i < g_poN; ++i) {
        if (g_po[i].kind != kPoSwitch) continue;
        bool names = false;
        for (int e = 0; e < g_peN && !names; ++e) names = g_pe[e].from == g_po[i].intro && g_pe[e].to == anchor;
        if (names && PzEntryLink(x, PzSwitchCmd(g_po[i].inst, anchorInst, nullptr)) == link) return g_po[i].intro;
    }
    return 0;
}
