// 0.22.57: the counter-command data of link `link` of X: the "set node" entries of the object command table for that
// link (one record each); open = the entry whose node is the link's node now or leads to it on internal edges (round
// gate: Raise -> At_Top on its joint range), closeSide = every other set-node target and what it reaches on internal
// edges (Lower -> AtBottom -> FX_collision). 1 = ok (the link is on the open side now), 0 = a pair exists but the gate
// is not open now, -1 = no pair (no counter hold)
int PzCounterOf(DWORD x, int link, int *openCmd, BYTE *closeSide) {
    const DWORD lb = tlobj::Uber(tlobj::LinkInst(x, link));
    const int nn = lb ? tlobj::NodeCount(lb) : 0;
    if (nn <= 0 || nn > 64) return -1;
    static BYTE reach[64][64];
    memset(reach, 0, sizeof(reach));
    for (int k = 0; k < nn; ++k) {
        const DWORD node = tlobj::NodeAddr(lb, k);
        for (int j = 0; node && j < tlobj::TransCount(node); ++j) {
            const DWORD t = tlobj::TransAt(node, j), to = tlobj::D(t + 4);
            if (t && to < static_cast<DWORD>(nn) && PzInternal(tlobj::D(t + 0x18))) reach[k][to] = 1;
        }
    }
    for (int m = 0; m < nn; ++m)
        for (int i = 0; i < nn; ++i)
            if (reach[i][m])
                for (int j = 0; j < nn; ++j)
                    if (reach[m][j]) reach[i][j] = 1;
    int setv[8], sete[8], sn = 0;
    for (int c = 0; c < tlobj::CmdCount(x) && sn < 8; ++c) {
        DWORD rec = 0;
        int rn = 0;
        if (!tlobj::CmdRecords(x, c, &rec, &rn) || rn != 1 || static_cast<int>(tlobj::D(rec)) != link || tlobj::D(rec + 4) != 1)
            continue;
        const DWORD v = tlobj::D(rec + 8);
        if (v < static_cast<DWORD>(nn)) { setv[sn] = static_cast<int>(v); sete[sn++] = c; }
    }
    if (sn < 2) return -1;
    const LONG cur = static_cast<LONG>(tlobj::D(lb + 0x84));
    const bool idle = cur >= 0 && cur < nn && !tlobj::D(lb + 0x80);
    int open = -1;
    for (int s = 0; s < sn && open < 0 && idle; ++s)
        if (setv[s] == cur || reach[setv[s]][cur]) open = s;
    // 0.22.59 (R1 point 9a, live 17.11. 7a: a closed reward grate got "0 counter commands"): closed = the link sits on the
    // side of another set-node record; the opening record is then the one set-node target the current node is not on
    // (exactly one, else no open-first: 0 with *openCmd = -1)
    bool closed = false;
    if (open < 0) {
        *openCmd = -1;
        if (!idle) return 0;
        int cand = -1, cands = 0;
        for (int s = 0; s < sn; ++s) {
            bool same = false;               // records with the same node count once
            for (int t = 0; t < s && !same; ++t) same = setv[t] == setv[s];
            if (same || setv[s] == cur || reach[setv[s]][cur]) continue;
            cand = s;
            ++cands;
        }
        if (cands != 1) return 0;
        open = cand;
        closed = true;
    }
    memset(closeSide, 0, 64);
    int marked = 0;
    for (int s = 0; s < sn; ++s) {
        if (setv[s] == setv[open]) continue;
        closeSide[setv[s]] = 1;
        ++marked;
        for (int k = 0; k < nn; ++k)
            if (reach[setv[s]][k] && (closed || k != cur) && k != setv[open] && !reach[setv[open]][k]) closeSide[k] = 1;
    }
    if (closed && cur >= 0 && cur < 64) closeSide[cur] = 1;
    *openCmd = marked ? sete[open] : -1;
    return closed ? 0 : marked ? 1 : -1;
}
// 0.22.57: the hold rows of a target (Puzzles nearby): motor-closed joints (open ones; the one held), the timer of an
// auto-reset gate, the counter command of a reversible plate gate; false = row table full
bool PzHoldRows(const PzObj &o, DWORD x, const PzKind &k, LONG story, bool de) {
    const ImU32 kSub = IM_COL32(220, 220, 220, 255), kAct = IM_COL32(255, 170, 80, 255);
    char arg[32];
    if (story) {                              // the game closes it as part of the story: no hold
        PzRow *s = PzAdd(kSub);
        if (!s) return false;
        Out(s->name, sizeof(s->name), "      %s", de ? "Offen halten" : "Hold open");
        Out(s->state, sizeof(s->state), de ? "nein: Story schlie\303\237t (Trigger %ld)" : "no: a story close (trigger %ld)", story);
        return true;
    }
    PzCheck chk = {};                         // 0.22.59: the checked links (locks of the shadow door) stay the game's
    const bool hasChk = x && PzBestCheck(x, &chk);
    for (int jn = 0; x && jn < tlobj::JointCount(x); ++jn) {   // motor-closed doors (hinge / rail)
        PzDoor d;
        if (!PzDoorOf(x, jn, &d)) continue;
        const bool mine = PzMotorHoldOf(x, jn) != nullptr, open = PzDoorIsOpen(d);
        bool lock = false;
        for (int q = 0; hasChk && q < chk.n && !lock; ++q) lock = chk.link[q] == d.part;
        // 0.22.59 (R1 point 9a / 9c, live 17.11.: the shadow door row came only above 5 degrees): a closed door is offered
        // as "open + hold" - not a lock of the object check (those belong to the game, no row as before)
        if (!open && !mine && lock) continue;
        char t[64];
        PzDoorLine(d, de, t, sizeof(t));
        PzRow *dr = PzAdd(kSub);
        if (!dr) return false;
        Out(dr->name, sizeof(dr->name), de ? "      T\303\274r (Gelenk %d, Teil %d)" : "      door (joint %d, part %d)", jn, d.part);
        Out(dr->state, sizeof(dr->state), "%s", t);
        Out(arg, sizeof(arg), mine ? "%ld %d off" : "%ld %d", o.intro, jn);
        PzRow *a = PzLine(kAct, "puzzle.hold", arg);
        if (!a) return false;
        if (open || mine) Out(a->name, sizeof(a->name), "      %s", de ? "T\303\274r offen halten (Motor)" : "Hold door open (motor)");
        else Out(a->name, sizeof(a->name), "      %s", de ? "T\303\274r \303\266ffnen + offen halten (Motor)" : "Open + hold door (motor)");
        Out(a->state, sizeof(a->state), "%s", mine ? (de ? "H\303\204LT - rechts = loslassen" : "HOLDING - right = release")
                                            : (de ? "rechts 2\303\227 (bis aus)" : "right 2x (until off)"));
    }
    const bool keepMine = PzKeepOf(o.intro) != nullptr;
    if (k.kind == kPkAuto && k.holdNode >= 0) {                 // timer
        const DWORD lb = k.link >= 0 && x ? tlobj::Uber(tlobj::LinkInst(x, k.link)) : tlobj::Uber(o.inst);
        if (!lb) return true;
        char hn[48];
        tlobj::NodeName(lb, k.holdNode, hn, sizeof(hn));
        const bool inNode = static_cast<LONG>(tlobj::D(lb + 0x84)) == k.holdNode && !tlobj::D(lb + 0x80);
        Out(arg, sizeof(arg), keepMine ? "%ld off" : "%ld timer", o.intro);
        PzRow *a = PzLine(kAct, "puzzle.hold", arg);
        if (!a) return false;
        if (de) Out(a->name, sizeof(a->name), "      Tor offen halten (Zeit in '%s' anhalten, %.0f s)", hn, static_cast<double>(k.holdSecs));
        else Out(a->name, sizeof(a->name), "      Hold gate open (stop the time in '%s', %.0f s)", hn, static_cast<double>(k.holdSecs));
        Out(a->state, sizeof(a->state), "%s", keepMine ? (de ? "H\303\204LT (Zeit steht) - rechts = aus" : "HOLDING (time stopped) - right = off")
                                            : inNode ? (de ? "rechts 2\303\227 (bis aus)" : "right 2x (until off)")
                                            : (de ? "rechts 2\303\227 (h\303\244lt, sobald offen)" : "right 2x (holds once open)"));
    } else if (k.kind == kPkReverse && x && k.link >= 0) {      // counter command (plate gates)
        int openCmd = -1;
        BYTE side[64];
        const int c = PzCounterOf(x, k.link, &openCmd, side);
        if (c < 0 && !keepMine) return true;
        // 0.22.59 (R1 point 9a): closed with one opening record = "open + hold" (the first send opens it)
        const bool canOpen = c == 0 && openCmd >= 0;
        Out(arg, sizeof(arg), keepMine ? "%ld off" : "%ld counter", o.intro);
        PzRow *a = PzLine(kAct, keepMine || c > 0 || canOpen ? "puzzle.hold" : "", arg);
        if (!a) return false;
        if (canOpen && !keepMine)
            Out(a->name, sizeof(a->name), de ? "      Tor \303\266ffnen + offen halten (Eintrag %d)" : "      Open + hold gate (entry %d)",
                openCmd);
        else Out(a->name, sizeof(a->name), "      %s", de ? "Tor offen halten (Gegenbefehl)" : "Hold gate open (counter command)");
        Out(a->state, sizeof(a->state), "%s", keepMine ? (de ? "H\303\204LT - rechts = aus" : "HOLDING - right = off")
                                            : c > 0 || canOpen ? (de ? "rechts 2\303\227 (bis aus)" : "right 2x (until off)")
                                            : (de ? "erst \303\266ffnen (Platte / Schalter)" : "open it first (plate / switch)"));
    }
    return true;
}
// ---- 0.22.67 (B1 N5) "Tuer herausziehen": a pull-out door (ENGINE 9 "Pull-out door ma_uo_bedroom_door 4526") ----
// A link of X whose CURRENT node has a "joint range left" transition (condition 15, watch on TRANS +0x20 joint / +0x24
// range [lo, hi), the engine's own watcher 0x4937a0) while the joint (hinge / rail) is inside the range: the game moves
// it out with Lara's grapple pull (live 19.11. 21:07:00: hinge 0 of 4526 leaves [-47.41, 31.61) -> 'door_pulled_out').
// puzzle.pullout <anchor> <joint> drives the joint with its own motor (TruLinkAct drive as puzzle.hold, limits kept, no
// node / lock written) 8 deg / 20 units past the nearer range edge that the joint's limits allow; the drive ends on the
// first node change of any link (the game reacts), 10 s, no progress or leaving the limits; every link's node change in
// the 4 s after the start goes into the log by name. Not for a lock of an object check (shadow door 4835).
struct PoCand { int link, joint, type; float lo, hi, v, target; bool ok; char why[48]; };
bool PoFind(DWORD x, PoCand *out, int max, int *count) {
    *count = 0;
    if (!x || !PzNeed(tlobj::kGrpMulti, tlobj::kGrpJoint, tlobj::kGrpUber)) return false;
    PzCheck chk = {};
    const bool hasChk = PzBestCheck(x, &chk);
    for (int i = 0; i < tlobj::Links(x) && *count < max; ++i) {
        const DWORD lb = tlobj::Uber(tlobj::LinkInst(x, i));
        if (!lb || tlobj::D(lb + 0x80)) continue;
        const DWORD node = tlobj::NodeAddr(lb, static_cast<LONG>(tlobj::D(lb + 0x84)));
        for (int j = 0; node && j < tlobj::TransCount(node) && *count < max; ++j) {
            const DWORD tr = tlobj::TransAt(node, j);
            float lo = 0.0f, hi = 0.0f;
            if (!tr || tlobj::D(tr + 0x18) != 15 || !tlobj::RangeOf(tlobj::D(tr + 0x24), &lo, &hi)) continue;
            const int ji = tlobj::JointIndexOf(x, tlobj::D(tr + 0x20));
            DWORD jrec = 0, jt = 0;
            if (ji < 0 || !tlobj::JointAt(x, ji, &jrec, &jt)) continue;
            const int type = tlobj::JointType(jt);
            if (type != 1 && type != 3) continue;
            bool lock = false;
            for (int q = 0; hasChk && q < chk.n && !lock; ++q) lock = chk.link[q] == i;
            PoCand &c = out[(*count)++];
            memset(&c, 0, sizeof(c));
            c.link = i;
            c.joint = ji;
            c.type = type;
            c.lo = lo;
            c.hi = hi;
            float lim[2] = {0.0f, 0.0f};
            DWORD flags = 0;
            const float toUnit = type == 1 ? 57.29577951308232f : 1.0f;
            const bool limits = tlobj::RF(jt + 0xd8, &lim[0]) && tlobj::RF(jt + 0xdc, &lim[1]) && tlobj::R32(jt + 0x174, &flags) &&
                                (flags & 2) && lim[0] < lim[1];
            const float llo = lim[0] * toUnit, lhi = lim[1] * toUnit, past = type == 1 ? 8.0f : 20.0f;
            if (!TlJointValue(jt, type, &c.v)) { Out(c.why, sizeof(c.why), "value unreadable"); continue; }
            if (type == 1 && limits) c.v = tlobj::HingeUnwrap(c.v, llo, lhi);
            if (lock) { Out(c.why, sizeof(c.why), "lock of the object check"); continue; }
            if (!(c.v >= lo && c.v < hi)) { Out(c.why, sizeof(c.why), "already outside the range"); continue; }
            const float up = hi + past, down = lo - past;   // the nearer edge first, the other when the limits forbid it
            const bool upOk = !limits || up <= lhi, downOk = !limits || down >= llo;
            const bool upFirst = hi - c.v <= c.v - lo;
            if (upFirst ? upOk : !downOk && upOk) c.target = up;
            else if (downOk) c.target = down;
            else { Out(c.why, sizeof(c.why), "the joint's limits [%.1f, %.1f] keep it inside", static_cast<double>(llo), static_cast<double>(lhi)); continue; }
            c.ok = true;
        }
    }
    return *count > 0;
}
tlact::DriveCtl g_poDrive = {{}, 0, "puzzle.pullout", nullptr};
struct PoWatch { bool on; LONG intro; DWORD inst, stamp, x, start; int links; DWORD nodes[16]; };
