bool ThIntArg(const char *arg, long lo, long hi, long *v) {
    char *end = nullptr;
    *v = arg ? strtol(arg, &end, 10) : 0;
    return arg && arg[0] && end && !*end && *v >= lo && *v <= hi;
}
