// render thread (debug view)
void ThCircle(ImDrawList *dl, const DvCam &c, const float *p, float r, ImU32 col, float thick) {
    float prev[3] = {p[0] + r, p[1], p[2]};
    for (int k = 1; k <= 40; ++k) {
        const float a = 6.2831853f * static_cast<float>(k) / 40.0f, q[3] = {p[0] + r * cosf(a), p[1] + r * sinf(a), p[2]};
        DvLine(dl, c, prev, q, col, thick);
        memcpy(prev, q, sizeof(q));
    }
}
void ThText(ImDrawList *dl, ImVec2 at, int row, ImU32 col, const char *line) {
    ImFont *font = ImGui::GetFont();
    const float size = ImGui::GetFontSize();
    const ImVec2 sz = font->CalcTextSizeA(size, FLT_MAX, 0.0f, line);
    const ImVec2 o(at.x - sz.x * 0.5f, at.y + static_cast<float>(row) * (sz.y + 2.0f));
    dl->AddRectFilled(ImVec2(o.x - 3, o.y), ImVec2(o.x + sz.x + 3, o.y + sz.y), IM_COL32(0, 0, 0, 165), 3.0f);
    dl->AddText(font, size, o, col, line);
}
void ThDrawView(ImDrawList *dl, const DvCam &c, const ThView &v) {
    const thorcore::Result &R = v.R;
    const bool de = g_qbLang == 0;
    const float z = R.P.floorZ + 6.0f;
    const ThState &s = g_th;
    if (g_thMap)                             // height tiles (only round the pillar)
        for (const ThTile &t : v.tiles) {
            const float dx = t.x + 50.0f - s.pos[0], dy = t.y + 50.0f - s.pos[1];
            if (dx * dx + dy * dy > 3500.0f * 3500.0f) continue;
            const float w[4][3] = {{t.x, t.y, z}, {t.x + 100.0f, t.y, z}, {t.x + 100.0f, t.y + 100.0f, z}, {t.x, t.y + 100.0f, z}};
            ImVec2 sp[4];
            bool ok = true;
            for (int k = 0; k < 4 && ok; ++k) {
                float q[3];
                DvToCam(c, w[k], q);
                ok = DvCamToScreen(c, q, &sp[k]);
            }
            if (ok) dl->AddQuadFilled(sp[0], sp[1], sp[2], sp[3], t.col);
        }
    for (const ThSeg &g : v.segs) {
        ImU32 col = kThGrey;
        float thick = 1.5f;
        bool dash = false;
        if (g.layer < 3) {
            col = kThCol[g.layer];
            const int a = g.layer == thorcore::kArtA ? 0 : g.layer == thorcore::kArtB ? 1 : -1;
            if (a >= 0 && a < v.arts && !v.art[a].born) col = (col & 0x00ffffff) | 0x90000000;   // collected: dimmed
            thick = 3.0f;
        } else if (g.layer < 6) {
            col = kThCol[g.layer - 3];
            thick = 2.0f;
            dash = true;
        } else if (g.layer == 7) {
            if (!g_thLoose) continue;
            col = IM_COL32(255, 255, 255, 150);
            thick = 1.0f;
        } else if (g.layer == 8) {
            col = IM_COL32(200, 200, 200, 230);
            thick = 2.5f;
        }
        const float a[3] = {g.a[0], g.a[1], z + (g.layer < 3 ? 3.0f * static_cast<float>(g.layer) : 0.0f)};
        const float b[3] = {g.b[0], g.b[1], a[2]};
        g_dvDashed = dash;
        DvLine(dl, c, a, b, col, thick);
        g_dvDashed = false;
    }
    for (const thorcore::Ledge &l : v.L) {   // the rings in their target's colour, with a name
        if (!l.closed || !l.target) continue;
        const ImU32 col = l.kind >= 0 ? kThCol[l.kind] : kThGrey;
        for (int i = 0; i < l.n; ++i) DvLine(dl, c, l.pts[i], l.pts[(i + 1) % l.n], col, 2.5f);
        float rc[2];
        ThRingCentre(l, rc);
        const float top[3] = {rc[0], rc[1], l.zmean + 150.0f};
        float q[3];
        ImVec2 at;
        DvToCam(c, top, q);
        if (!DvCamToScreen(c, q, &at)) continue;
        char nm[40], to[96], line[160];
        ThRingName(v, l, de, nm, sizeof(nm));
        ThKindName(v, l.kind, de, to, sizeof(to));
        Out(line, sizeof(line), "%s -> %s", nm, to);
        ThText(dl, at, 0, col, line);
    }
    for (int k = 0; k < thorcore::kKinds; ++k) {   // targets without a reachable area: grey text at their gallery
        if (v.kindReach[k] || !v.kindKnown[k]) continue;
        const float at3[3] = {v.kindAt[k][0], v.kindAt[k][1], v.kindAt[k][2] + 120.0f};
        float q[3];
        ImVec2 at;
        DvToCam(c, at3, q);
        if (!DvCamToScreen(c, q, &at)) continue;
        char to[96], line[200];
        ThKindName(v, k, de, to, sizeof(to));
        Out(line, sizeof(line), de ? "%s: von der S\303\244ule nicht erreichbar" : "%s: not reachable from the pillar", to);
        ThText(dl, at, 0, kThGrey, line);
    }
    for (int q = 0; q < s.obsN; ++q) {       // obstacles: grey crosses of their disc
        const float *o = s.obs[q].pos, e = s.obs[q].ext * 0.7f;
        const float a1[3] = {o[0] - e, o[1] - e, z + 4.0f}, b1[3] = {o[0] + e, o[1] + e, z + 4.0f};
        const float a2[3] = {o[0] - e, o[1] + e, z + 4.0f}, b2[3] = {o[0] + e, o[1] - e, z + 4.0f};
        DvLine(dl, c, a1, b1, IM_COL32(170, 170, 170, 230), 2.0f);
        DvLine(dl, c, a2, b2, IM_COL32(170, 170, 170, 230), 2.0f);
    }
    const LONG tn = s.trackN;                // the pillar's track (dotted)
    for (LONG k = tn > kThTrackMax ? tn - kThTrackMax : 0; k + 1 < tn; k += 2) {
        const float *a = s.track[k % kThTrackMax], *b = s.track[(k + 1) % kThTrackMax];
        const float a3[3] = {a[0], a[1], z + 2.0f}, b3[3] = {(a[0] + b[0]) * 0.5f, (a[1] + b[1]) * 0.5f, z + 2.0f};
        DvLine(dl, c, a3, b3, IM_COL32(255, 255, 255, 200), 2.0f);
    }
    const float p[3] = {s.pos[0], s.pos[1], R.P.floorZ + 8.0f};
    ThCircle(dl, c, p, R.P.foot, IM_COL32(255, 255, 255, 230), 2.0f);
    ThCircle(dl, c, p, R.P.head, IM_COL32(255, 230, 60, 200), 1.5f);
    // the state lines above the pillar
    const int i = R.Index(p[0], p[1]);
    int best = -1;                           // the nearest cell of any area
    float bd = 1e30f;
    for (const int k : v.areaCells) {
        const float dx = R.Cx(k) - p[0], dy = R.Cy(k) - p[1], d = dx * dx + dy * dy;
        if (d < bd) { bd = d; best = k; }
    }
    const float top[3] = {p[0], p[1], R.P.floorZ + 1500.0f};
    float q[3];
    ImVec2 at;
    DvToCam(c, top, q);
    if (!DvCamToScreen(c, q, &at)) return;
    int row = 0;
    char line[220], nm[40], to[96];
    auto areaText = [&](int cell, char *o, size_t n, ImU32 *col) {   // "Ring NO -> Artefakt A (D 2.0 m)" of a cell
        o[0] = 0;
        size_t used = 0;
        *col = kThGrey;
        const float cp[3] = {R.Cx(cell), R.Cy(cell), 0.0f};
        for (size_t r = 0; r < R.rings.size(); ++r) {
            if (!((R.ringMask[static_cast<size_t>(cell)] >> r) & 1)) continue;
            const thorcore::Ledge &l = v.L[static_cast<size_t>(R.rings[r])];
            ThRingName(v, l, de, nm, sizeof(nm));
            ThKindName(v, l.kind, de, to, sizeof(to));
            LabelAdd(o, n, &used, "%s%s -> %s (D %.1f m)", used ? ", " : "", nm, to,
                     static_cast<double>((thorcore::LedgeDist(l, cell == i ? p : cp) - R.P.head) / kUnitsPerMetre));
            if (l.kind >= 0) *col = kThCol[l.kind];
        }
        for (int k = 0; k < thorcore::kKinds; ++k)
            if ((R.galMask[static_cast<size_t>(cell)] >> k) & 1) {
                ThKindName(v, k, de, to, sizeof(to));
                LabelAdd(o, n, &used, "%s%s %s", used ? ", " : "", to, de ? "(direkt, unbelegt)" : "(direct, unproven)");
                if (*col == kThGrey) *col = kThCol[k];
            }
    };
    ImU32 col = kThGrey;
    char area[200];
    if (i >= 0 && (R.ringMask[static_cast<size_t>(i)] || R.galMask[static_cast<size_t>(i)])) {
        areaText(i, area, sizeof(area), &col);
        Out(line, sizeof(line), de ? "S\303\244ule in Fl\303\244che %s" : "pillar in the area %s", area);
        ThText(dl, at, row++, col, line);
    } else if (best >= 0) {
        areaText(best, area, sizeof(area), &col);
        const float dx = R.Cx(best) - p[0], dy = R.Cy(best) - p[1];
        const bool free = i >= 0 && R.reach[static_cast<size_t>(i)];
        Out(line, sizeof(line), de ? "n\303\244chste Fl\303\244che %s: %.1f m nach %s, %s" : "next area %s: %.1f m %s, %s", area,
            static_cast<double>(sqrtf(dx * dx + dy * dy) / kUnitsPerMetre), ThCompass(dx, dy, de, false),
            free ? (de ? "Weg frei" : "way free") : (de ? "S\303\244ule nicht im erreichbaren Bereich" : "pillar not in the reachable part"));
        ThText(dl, at, row++, col, line);
        const float t3[3] = {R.Cx(best), R.Cy(best), p[2]};   // arrow to it
        DvLine(dl, c, p, t3, IM_COL32(255, 255, 255, 255), 2.5f);
        M20Diamond(dl, c, t3, 25.0f, IM_COL32(255, 255, 255, 255), 2.0f);
    } else {
        ThText(dl, at, row++, kThGrey, de ? "keine erreichbare Fl\303\244che" : "no reachable area");
    }
    if (i >= 0 && R.dist[static_cast<size_t>(i)] < R.P.foot + 40.0f) {   // at a limit
        float d = 0.0f;
        const int nb = R.NearestBlocked(p[0], p[1], R.P.foot + 200.0f, &d);
        if (nb >= 0) {
            const float h = R.Rise(nb);
            char hs[40];
            if (h > 1e29f) Out(hs, sizeof(hs), "%s", de ? "Loch" : "hole");
            else Out(hs, sizeof(hs), de ? "H\303\266he %.1f m" : "height %.1f m", static_cast<double>(h / kUnitsPerMetre));
            Out(line, sizeof(line), de ? "S\303\244ule kann hier nicht weiter (Hindernis %.1f m, %s)" : "the pillar cannot go on here "
                "(obstacle %.1f m, %s)", static_cast<double>((d - R.P.foot) / kUnitsPerMetre), hs);
            ThText(dl, at, row++, IM_COL32(255, 200, 120, 255), line);
        }
    }
    if (!v.mesh) ThText(dl, at, row, kThGrey, de ? "(Gel\303\244nde aus Strahlen)" : "(terrain from rays)");
}
void ThDraw(ImDrawList *dl, const DvCam &c) {
    AcquireSRWLockShared(&g_thLock);
    if (g_thView) ThDrawView(dl, c, *g_thView);
    ReleaseSRWLockShared(&g_thLock);
}
// ---- state log + switch learning (every 250 ms in a level) ----
struct PzWatch { DWORD b, stamp; LONG intro, node; DWORD trans; };
PzWatch g_pzWatch[128];
int g_pzWatchN = 0, g_pzLogged = 0;
DWORD g_pzWatchAt = 0;
void PzWatchTick() {
    const DWORD now = GetTickCount();
    if (now - g_pzWatchAt < 250) return;
    g_pzWatchAt = now;
    if (!InLevel() || !PzNeed(tlobj::kGrpList, tlobj::kGrpUber, tlobj::kGrpMulti)) { g_pzWatchN = 0; return; }
    const DWORD player = tlobj::D(tlobj::kPlayer);
    float lara[3];
    if (!player || !TlRead(player + 0x20, lara, 12)) return;
    const float rad = 2.0f * g_ubRadius, r2 = rad * rad;
    static PzWatch next[128];
    int nn = 0;
    struct Moved { DWORD x; int link; };
    Moved moved[16];
    int mn = 0;
    tlobj::ForInstances([&](DWORD inst, int) {
        const DWORD b = tlobj::Uber(inst);
        float p[3];
        if (!b || nn >= 128 || !TlRead(inst + 0x20, p, 12)) return true;
        const float dx = p[0] - lara[0], dy = p[1] - lara[1], dz = p[2] - lara[2];
        if (!(dx * dx + dy * dy + dz * dz <= r2)) return true;
        PzWatch w = {b, tlobj::D(inst + 0x44), static_cast<LONG>(tlobj::D(inst + 0x58)),
                     static_cast<LONG>(tlobj::D(b + 0x84)), tlobj::D(b + 0x80)};
        next[nn++] = w;
        for (int i = 0; i < g_pzWatchN; ++i) {
            const PzWatch &o = g_pzWatch[i];
            if (o.b != b || o.stamp != w.stamp || (o.node == w.node && (o.trans != 0) == (w.trans != 0))) continue;
            char name[48], a[48], z[48];
            tlobj::InstName(inst, name, sizeof(name));
            tlobj::NodeName(b, o.node, a, sizeof(a));
            if (w.trans) {
                tlobj::NodeName(b, static_cast<LONG>(tlobj::D(w.trans + 4)), z, sizeof(z));
                strncat_s(z, sizeof(z), " (transition)", _TRUNCATE);
            } else {
                tlobj::NodeName(b, w.node, z, sizeof(z));
            }
            if (g_pzLogged < 400) Log(1, "puzzle: %s %ld '%s' -> '%s'", name, w.intro, a, z);
            else if (g_pzLogged == 400) Log(1, "puzzle: more state changes in this level not logged (400)");
            ++g_pzLogged;
            const DWORD x = tlobj::D(b + 0x7c);
            if (tlobj::IsMulti(x) && mn < 16) {
                for (int l = 0; l < tlobj::Links(x); ++l)
                    if (tlobj::LinkInst(x, l) == inst) moved[mn++] = {x, l};
            }
        }
        return true;
    });
    // learning: exactly one link of an object moved while Lara stands within 2 m of a switch that names the object
    for (int i = 0; i < mn && !g_pzFig.on; ++i) {
        int same = 0;
        for (int k = 0; k < mn; ++k) same += moved[k].x == moved[i].x ? 1 : 0;
        const DWORD anchor = tlobj::D(moved[i].x + 0x58);
        const LONG ai = anchor ? static_cast<LONG>(tlobj::D(anchor + 0x58)) : 0;
        if (same != 1 || !ai || PzLearned(ai, moved[i].link)) continue;
        LONG best = 0;
        float bd = 600.0f * 600.0f;
        tlobj::ForInstances([&](DWORD inst, int) {
            PzSw sw;
            float p[3];
            if (!TlRead(inst + 0x20, p, 12)) return true;
            const float dx = p[0] - lara[0], dy = p[1] - lara[1], dz = p[2] - lara[2], d2 = dx * dx + dy * dy + dz * dz;
            if (d2 >= bd || !PzSwitchOf(inst, &sw)) return true;
            const DWORD so = tlobj::ScriptObj(inst), data = tlobj::D(so + 0xc);
            DWORD roots[16];
            const int depth = tlobj::ClassChain(so, roots, 16);
            for (int d = 0; d < depth; ++d)
                for (int k = 0; k < tlobj::MemberCount(roots[d]); ++k) {
                    tlobj::Member m;
                    if (tlobj::MemberAt(roots[d], k, &m) && !strcmp(m.type, "instanceref") &&
                        static_cast<LONG>(tlobj::D(data + m.offset)) == ai) {
                        best = static_cast<LONG>(tlobj::D(inst + 0x58));
                        bd = d2;
                    }
                }
            return true;
        });
        if (!best || g_pzLearnN >= 16) continue;
        g_pzLearn[g_pzLearnN++] = {ai, best, moved[i].link};
        Log(1, "puzzle: learned - switch %ld steps link %d of %ld (Lara stood at it when the link moved)", best,
            moved[i].link, ai);
    }
    memcpy(g_pzWatch, next, sizeof(PzWatch) * static_cast<size_t>(nn));
    g_pzWatchN = nn;
}
// a level load (main state 2): runtime ids and instances change - learned switches, watch, jobs, undo places go
void PzLevelLoad() {
    g_pzLearnN = 0;
    g_pzWatchN = 0;
    g_pzLogged = 0;
    g_pzPlacedN = 0;
    g_pzSwCmdN = 0;                          // 0.22.57: switch -> command entries are read again
    PzKeepStop("level load");                // 0.22.57: timer / counter hold
    if (g_pzFig.on) { InterlockedExchange(&g_pzFig.on, 0); Log(1, "puzzle.figures: level load - stopped"); }
    PzMotorStopAll("level load");            // 0.22.59: every motor hold
    PzPullReset();                           // 0.22.59 (9a): a pending / watched switch pull
    if (g_pzTo.on) PzPullToStop("level load - stopped");   // 0.22.62 (S1 g)
    if (g_poDrive.on) tlact::DriveStop(g_poDrive, "level load");   // 0.22.67 (B1 N5)
    g_poW.on = false;
}
void PzGameTick() {
    if (g_tlBad < 0) return;
    for (tlact::DriveCtl &c : g_pzHolds) {   // 0.22.59: every motor hold
        if (!c.on) continue;
        __try {
            tlact::DriveTick(c, *kGameClock);
        } __except (EXCEPTION_EXECUTE_HANDLER) {
            InterlockedExchange(&c.on, 0);
            Log(0, "puzzle.hold: access fault in the drive tick (caught) - stopped without restore");
        }
    }
    __try {
        PzKeepTick();                        // 0.22.57 timer / counter hold
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        for (PzKeep &q : g_pzKeeps) InterlockedExchange(&q.on, 0);
        Log(0, "puzzle.hold: access fault in the timer / counter tick (caught) - stopped");
    }
    __try {
        PzPullTick();                        // 0.22.59 (9a): the switch pull and its check after
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        PzPullReset();
        Log(0, "puzzle.pull: access fault in the pull tick (caught) - stopped");
    }
    __try {                                  // 0.22.67 (B1 N5): puzzle.pullout drive + its node log
        if (g_poDrive.on) tlact::DriveTick(g_poDrive, *kGameClock);
        PoWatchTick();
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        InterlockedExchange(&g_poDrive.on, 0);
        g_poW.on = false;
        Log(0, "puzzle.pullout: access fault in its tick (caught) - stopped without restore");
    }
    __try {
        PzPullToTick();                      // 0.22.62 (S1 g): "Figur aufs Ziel", the next pull when the figure stands
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        InterlockedExchange(&g_pzTo.on, 0);
        Log(0, "puzzle.pullto: access fault in its tick (caught) - stopped");
    }
    __try {
        InsTick();                           // 0.22.61 (R1c 2): puzzle.insert message + check after
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        InterlockedExchange(&g_ins.pending, 0);
        InterlockedExchange(&g_ins.check, 0);
        Log(0, "puzzle.insert: access fault in the tick (caught)");
    }
    __try {
        RbTick();                            // 0.22.68 (B2 5): rune blocks - falls, countdown, hold
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        InterlockedExchange(&g_rb.want, 0);
        g_rb.hold = false;
        Log(0, "puzzle.runehold: access fault in the tick (caught) - stopped");
    }
    __try {
        PiTick();                            // 0.22.59 (4 / 5): states + hints for the world labels / key items
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        g_pzInfoAt = GetTickCount() | 1;
        Log(0, "puzzle info: access fault while building (caught)");
    }
    __try {
        PzFigTick();
        PzWatchTick();
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        InterlockedExchange(&g_pzFig.on, 0);
        Log(0, "puzzle: access fault in the figures / watch tick (caught)");
    }
}
// ---- end of 0.22.56 puzzles nearby ----
void PzRefresh(bool de) {
    g_pzN = g_pzPuzzles = g_pzOthers = 0;
    DWORD player = 0;
    float lara[3];
    if (!g_jtOk || !InLevel() || !ReadDword(kPlayerPtr, &player) || !player || !ReadFloats(player + kInstancePosition, lara, 3))
        return;
    PzNewRows(de, player, lara);             // 0.22.56: switches, plates, targets, figures, doors, weights
    if (!g_pzActions) {                      // 0.22.59 (R1 point 4) / 0.22.62 (S1 b): Aktionen off = no action rows
        int k = 0;
        for (int i = 0; i < g_pzN; ++i)
            if (!g_pzRows[i].act) g_pzRows[k++] = g_pzRows[i];
        g_pzN = k;
    }
    if (g_pzN) {
        PzRow *h = PzAdd(IM_COL32(150, 150, 150, 255));
        if (h) Out(h->name, sizeof(h->name), "  %s", de ? "Gelenk-Bereiche (nur Anzeige)" : "Joint ranges (list only)");
    }
    struct Cand { DWORD inst, b; float d2; bool joint; };
    Cand c[48];
    int cn = 0;
    const float r2 = g_ubRadius * g_ubRadius;
    DWORD inst = 0;
    ReadDword(kFirstInstance, &inst);
    for (int guard = 0; inst && guard < 4096; ++guard) {
        DWORD next = 0;
        float p[3];
        const DWORD b = inst != player ? UberStateOf(inst) : 0;
        if (b && ReadFloats(inst + kInstancePosition, p, 3)) {
            const float dx = p[0] - lara[0], dy = p[1] - lara[1], dz = p[2] - lara[2], d2 = dx * dx + dy * dy + dz * dz;
            const bool joint = PzHasJoint(b);
            if ((joint || d2 <= r2) && cn < 48) c[cn++] = {inst, b, d2, joint};
        }
        if (!ReadDword(inst + 8, &next)) break;
        inst = next;
    }
    for (int i = 1; i < cn; ++i)             // puzzles first, each part nearest first
        for (int k = i; k > 0 && ((c[k].joint && !c[k - 1].joint) || (c[k].joint == c[k - 1].joint && c[k].d2 < c[k - 1].d2)); --k) {
            const Cand t = c[k]; c[k] = c[k - 1]; c[k - 1] = t;
        }
    for (int i = 0; i < cn; ++i) {
        if (c[i].joint ? g_pzPuzzles >= 16 : g_pzOthers >= 8) continue;
        DWORD object = 0, oid = 0, intro = 0, node = 0, trans = 0, desc = 0, count = 0, nodes = 0;
        ReadDword(c[i].inst + 0x10, &object);
        if (object) ReadDword(object + 0x14, &oid);
        ReadDword(c[i].inst + 0x58, &intro);
        ReadDword(c[i].b + 0x84, &node);
        ReadDword(c[i].b + 0x80, &trans);
        char name[64], state[48];
        if (!ObjectName(static_cast<int>(oid & 0xffff), name, sizeof(name))) Out(name, sizeof(name), "obj %lu", oid & 0xffff);
        UberText(c[i].b, false, de, state, sizeof(state));
        int other = 0;                       // joint-range transitions of the other nodes
        if (ReadDword(c[i].b + 0x78, &desc) && desc && ReadDword(desc + 4, &count) && count <= 64 && ReadDword(desc + 8, &nodes))
            for (DWORD k = 0; nodes && k < count; ++k) {
                DWORD tn = 0, tp = 0;
                if (k == node || !ReadDword(nodes + 28 * k + 0xc, &tn) || tn > 64 || !ReadDword(nodes + 28 * k + 0x10, &tp) || !tp)
                    continue;
                for (DWORD j = 0; j < tn; ++j) {
                    DWORD t = 0, cond = 0;
                    if (ReadDword(tp + 4 * j, &t) && t && ReadDword(t + 0x18, &cond) && (cond == 14 || cond == 15)) ++other;
                }
            }
        PzRow *o = PzAdd(c[i].joint ? IM_COL32(255, 210, 90, 255) : IM_COL32(170, 170, 170, 255));
        if (!o) break;
        if (c[i].joint) ++g_pzPuzzles; else ++g_pzOthers;
        MbPart part;                         // 0.22.55: which part of a multibody object (link n, its node)
        char partText[56] = "";
        if (MbPartOf(c[i].inst, &part)) MbPartText(part, de, partText, sizeof(partText));
        Out(o->name, sizeof(o->name), "  %s%s %lu%s", name, partText, intro, c[i].joint ? "" : (de ? " (Ereignis)" : " (event)"));
        Out(o->state, sizeof(o->state), "%s", state);
        Out(o->count, sizeof(o->count), "%.0f%s", sqrtf(c[i].d2), other ? (de ? " +Knoten" : " +nodes") : "");
        if (!c[i].joint || trans || !nodes || node >= count) continue;
        DWORD tn = 0, tp = 0;                // the current node's joint-range transitions
        if (!ReadDword(nodes + 28 * node + 0xc, &tn) || tn > 64 || !ReadDword(nodes + 28 * node + 0x10, &tp) || !tp) continue;
        for (DWORD j = 0; j < tn; ++j) {
            DWORD t = 0, cond = 0, jrec = 0, rrec = 0, to = 0;
            if (!ReadDword(tp + 4 * j, &t) || !t || !ReadDword(t + 0x18, &cond) || (cond != 14 && cond != 15)) continue;
            ReadDword(t + 0x20, &jrec);
            ReadDword(t + 0x24, &rrec);
            ReadDword(t + 4, &to);
            float lo = 0.0f, hi = 0.0f, v = 0.0f;
            int index = -1;
            DWORD joint = 0;
            const bool range = rrec && JtRange(rrec, &lo, &hi), found = jrec && JtFind(c[i].b, jrec, &index, &joint);
            const bool val = found && JtValue(joint, &v);
            const int type = found ? JtType(joint) : -1;
            char dest[32];
            UberNodeName(c[i].b, static_cast<LONG>(to), dest, sizeof(dest));
            PzRow *r = PzAdd(IM_COL32(235, 235, 235, 255));
            if (!r) break;
            if (range)
                Out(r->name, sizeof(r->name), "      G%d %s %s%.1f %s [%.1f, %.1f) -> %s", index, JtTypeName(type, de),
                    val ? "" : "? ", static_cast<double>(v), cond == 14 ? (de ? "rein" : "into") : (de ? "raus" : "out of"),
                    static_cast<double>(lo), static_cast<double>(hi), dest);
            else
                Out(r->name, sizeof(r->name), "      G%d %s -> %s (%s)", index, JtTypeName(type, de), dest,
                    de ? "Bereich nicht lesbar" : "range not readable");
            const bool inside = val && range && lo <= v && v < hi;
            Out(r->count, sizeof(r->count), "%s", inside ? (de ? "drin" : "inside") : "");
            // 0.22.52 (j): the target. Owner live test 22:13 l3_secretchamber: a FREE hinge (limits off, [0, 0]) with the
            // open-ended ranges [1, 10000) / [-10001, -1) (Not_Rotating -> Rotating = a motion detector, not a solving
            // step) got the middle 5000.5 degrees -> the pillar was locked at 87 rad and spun through the geometry.
            // Now: open-ended range on a free hinge = list only; otherwise the range is cut to the joint's own limits
            // (limit on, lo < hi; ma_rb_chapel_gate_round At_Top [774.3, 948.2) vs limits [0, 790.1]: 861 -> 782.2) and
            // an open bound (|x| >= 360 degrees on a hinge) is replaced by the near bound + 2 degrees.
            float lim[2] = {0.0f, 0.0f};
            DWORD jfl = 0;
            const bool limOk = found && ReadFloats(joint + 0xd8, lim, 2) && ReadDword(joint + 0x174, &jfl);
            const bool limOn = limOk && (jfl & 2) != 0;
            const float open = type == 1 ? 360.0f : 1.0e6f;
            const bool loOpen = range && fabsf(lo) >= open, hiOpen = range && fabsf(hi) >= open;
            const bool motion = type == 1 && limOk && !limOn && (loOpen || hiOpen);
            float a = lo, z = hi;
            if (limOn && lim[0] < lim[1]) {
                const float lr0 = type == 1 ? lim[0] * 57.29577951f : lim[0], lr1 = type == 1 ? lim[1] * 57.29577951f : lim[1];
                if (a < lr0) a = lr0;
                if (z > lr1) z = lr1;
            }
            float target = (a + z) * 0.5f;
            if (loOpen && !hiOpen) target = z - (type == 1 ? 2.0f : 5.0f);
            else if (hiOpen && !loOpen) target = a + (type == 1 ? 2.0f : 5.0f);
            // 0.22.56: no "solve" row any more (it drove a rail with closed locks) - the range and its target are shown
            (void)target;
            const bool tried = JtWasTried(static_cast<LONG>(intro), index, static_cast<LONG>(node));
            Out(r->state, sizeof(r->state), "%s", tried ? (de ? "Bereich hier nicht scharf (versucht)"
                                                              : "range not armed here (tried)")
                                                  : motion ? (de ? "Bewegungs-Melder, kein Ziel" : "motion detector, no target")
                                                  : cond == 14 && range && found && !(a < z)
                                                      ? (de ? "Bereich au\303\237erhalb der Grenzen" : "range outside the limits")
                                                      : (de ? "nur Anzeige" : "list only"));
        }
    }
    // 0.22.55: poles without a hole / reference in the loaded data (section "0.22.55 multibody parts + unused poles"),
    // within [Debug] UberRadius of Lara, list only
    PlScan();
    for (int i = 0; i < g_plN; ++i) {
        const PlPole &pl = g_plPoles[i];
        float p[3];
        if (pl.verdict != 1 || !ReadFloats(pl.inst + kInstancePosition, p, 3)) continue;
        const float dx = p[0] - lara[0], dy = p[1] - lara[1], dz = p[2] - lara[2], d2 = dx * dx + dy * dy + dz * dz;
        if (d2 > r2) continue;
        PzRow *o = PzAdd(IM_COL32(170, 170, 170, 255));
        if (!o) break;
        ++g_pzOthers;
        Out(o->name, sizeof(o->name), "  ma_pt_pole_a %ld", pl.intro);
        Out(o->state, sizeof(o->state), "%s", PlUnusedText(de));
        Out(o->count, sizeof(o->count), "%.0f", static_cast<double>(sqrtf(d2)));
    }
}
int QbPzRows(QbView *v, QbDyn *d, int max, bool de) {
    if (max <= 0) return 0;
    const bool open = g_chapOpen == kChapGroupN;
    if (open && (!g_pzAt || GetTickCount() - g_pzAt > 300)) {
        AcquireSRWLockExclusive(&g_pzBuildLock);   // 0.22.59: PiTick (game thread) builds the same object list
        PzRefresh(de);
        ReleaseSRWLockExclusive(&g_pzBuildLock);
        g_pzAt = GetTickCount();
        if (!g_pzAt) g_pzAt = 1;
    }
    int n = 0;
    QbView &w = v[n];
    QbDyn &q = d[n];
    memset(&w, 0, sizeof(w));
    memset(&q, 0, sizeof(q));
    w.src = -1;
    if (open) Out(w.name, sizeof(w.name), "[-] %s (%d)", de ? "R\303\244tsel in der N\303\244he (Q106)" : "Puzzles nearby (Q106)",
                  g_pzPuzzles);
    else Out(w.name, sizeof(w.name), "[+] %s", de ? "R\303\244tsel in der N\303\244he (Q106)" : "Puzzles nearby (Q106)");
    Out(w.state, sizeof(w.state), "%s", open ? (de ? "links = zu" : "left = close") : (de ? "rechts = auf" : "right = open"));
    Out(w.count, sizeof(w.count), "%s", !g_jtOk ? (de ? "aus (Pr\303\274fung)" : "off (check)")
                                        : PzAnyHold() ? (de ? "h\303\244lt offen" : "holding open")   // 0.22.56 / 57 / 59
                                        : g_pzFig.on ? (de ? "Figuren" : "figures")
                                        : g_jtOn ? (de ? "l\303\244uft" : "running") : "");
    w.col = kQbChapter;
    w.stateCol = IM_COL32(170, 170, 170, 255);
    q.kind = kQdChapGroup;
    q.intro = kChapGroupN;
    ++n;
    if (!open) return n;
    // 0.22.59 (R1 point 4) one level row; 0.22.62 (S1 b, live 18.11.: level 1 hid the actions): two switches, right
    // twice = toggle
    for (int s = 0; s < 2 && n < max; ++s) {
        QbView &x = v[n];
        QbDyn &y = d[n];
        memset(&x, 0, sizeof(x));
        memset(&y, 0, sizeof(y));
        x.src = -1;
        const char *item = s == 0 ? "puzzle.hints" : "puzzle.actions";
        const bool on = (s == 0 ? g_pzHints : g_pzActions) != 0;
        char key[40];
        Out(key, sizeof(key), "pz %s", item);
        const bool armed = QbArmed(key);
        Out(x.name, sizeof(x.name), "  %s", s == 0 ? (de ? "Hinweise" : "Hints") : (de ? "Aktionen (Cheats)" : "Actions (cheats)"));
        Out(x.state, sizeof(x.state), "%s", armed ? (de ? "nochmal rechts!" : "right again!")
                                         : on ? (de ? "an (rechts 2\303\227: aus)" : "on (right 2x: off)")
                                         : (de ? "aus (rechts 2\303\227: an)" : "off (right 2x: on)"));
        x.col = IM_COL32(150, 235, 150, 255);
        x.stateCol = armed ? IM_COL32(255, 110, 90, 255) : IM_COL32(255, 190, 90, 255);
        y.kind = kQdPz;
        y.intro = -1;
        strncpy_s(y.arg, sizeof(y.arg), item, _TRUNCATE);
        ++n;
    }
    if (!g_jtOk || !g_pzN) {
        char t[112];
        if (!g_jtOk) Out(t, sizeof(t), "%s %s", de ? "Gelenk-Pr\303\274fung:" : "joint checks:", g_jtWhy);
        else Out(t, sizeof(t), "%s", de ? "keine Uber-Objekte geladen / in der N\303\244he" : "no uber objects loaded / nearby");
        if (n < max) QbDynLabel(&v[n], &d[n], t), ++n;
        return n;
    }
    for (int i = 0; i < g_pzN && n < max; ++i) {
        const PzRow &r = g_pzRows[i];
        QbView &x = v[n];
        QbDyn &y = d[n];
        memset(&x, 0, sizeof(x));
        memset(&y, 0, sizeof(y));
        x.src = -1;
        char key[160];
        Out(key, sizeof(key), "pz %s", r.arg);
        const bool armed = r.arg[0] && QbArmed(key);
        Out(x.name, sizeof(x.name), "%s", r.name);
        Out(x.state, sizeof(x.state), "%s", armed ? (de ? "nochmal rechts!" : "right again!") : r.state);
        Out(x.count, sizeof(x.count), "%s", r.count);
        x.col = r.col;
        x.stateCol = armed ? IM_COL32(255, 110, 90, 255) : r.arg[0] ? IM_COL32(255, 190, 90, 255) : IM_COL32(170, 170, 170, 255);
        y.kind = kQdPz;
        y.intro = i;
        strncpy_s(y.arg, sizeof(y.arg), r.arg, _TRUNCATE);
        ++n;
    }
    return n;
}
// 0.22.56: a row runs "<item> <argument>" from its arg (puzzle.figures / puzzle.hold / puzzle.bring), right twice; left
// ends a running door hold (puzzle.hold off) or a 0.22.31 joint.set drive
void QbPzAct(const QbDyn &q, int dir) {
    const bool de = g_qbLang == 0;
    if (dir == -1) {
        if (PzAnyHold()) QbRun("Kapitel", "Raetsel", de ? "Alle loslassen" : "Release all", "puzzle.hold", "off");
        else if (g_jtOn) QbRun("Kapitel", "Raetsel", de ? "Gelenk stoppen" : "Stop joint", "joint.set", "stop");
        else QbResult(false, "%s", de ? "links: nichts aktiv" : "left: nothing running");
        return;
    }
    if (!q.arg[0]) { QbResult(false, "%s", de ? "nur Anzeige" : "list only"); return; }
    char item[32] = "", arg[64] = "";
    const char *space = strchr(q.arg, ' ');
    const size_t il = space ? static_cast<size_t>(space - q.arg) : strlen(q.arg);
    if (!il || il >= sizeof(item)) return;
    memcpy(item, q.arg, il);
    item[il] = 0;
    if (space) strncpy_s(arg, sizeof(arg), space + 1, _TRUNCATE);
    const char *what = !strcmp(item, "puzzle.figures") ? (de ? "Figuren auf Ziel setzen" : "Set figures to target")
                     : !strcmp(item, "puzzle.hold") ? (de ? "Offen halten" : "Hold open")
                     : !strcmp(item, "puzzle.bring") ? (de ? "Objekt versetzen" : "Move object")
                     : !strcmp(item, "puzzle.weights") ? (de ? "Gewichte auf die Platte" : "Weights onto the plate")
                     : !strcmp(item, "puzzle.insert") ? (de ? "Einstecken" : "Insert")   // 0.22.61
                     : !strcmp(item, "puzzle.pullto") ? (de ? "Figur aufs Ziel" : "Figure to target")   // 0.22.62 (S1 g)
                     : !strcmp(item, "puzzle.hints") ? (de ? "Hinweise an / aus" : "Hints on / off")   // 0.22.62 (S1 b)
                     : !strcmp(item, "puzzle.actions") ? (de ? "Aktionen an / aus" : "Actions on / off") : item;
    char key[160];
    Out(key, sizeof(key), "pz %s", q.arg);
    if (strcmp(arg, "off") && !QbConfirm(key, what, de ? "Cheat: nur Spiel-eigene Wege (Befehle, Motor, Platzierung)"
                                                       : "cheat: the game's own paths only (commands, motor, placement)"))
        return;
    QbRun("Kapitel", "Raetsel", what, item, arg);
}
// 0.22.57 export TruMenuPuzzleList (TruLink 0.5.2 puzzle.list): the rows of "Raetsel in der Naehe" as text, refreshed
// now - one line per row "name<TAB>state<TAB>count<TAB>action" (action = the "<item> <argument>" the row runs, "-" for
// a list-only row); lang 0 German, else English. Game thread only (TruLink runs it as a game-thread job). Returns the
// length, or the size needed when out is too small (then out holds as many whole lines as fit)
int PzListText(char *out, int size, int lang) {
    if (!out || size <= 0) return -1;
    out[0] = 0;
    if (!g_jtOk || !InLevel()) return _snprintf_s(out, static_cast<size_t>(size), _TRUNCATE, "%s",
                                                  !g_jtOk ? "-\tjoint checks failed\t\t-\n" : "-\tno level\t\t-\n");
    __try {
        PzRefresh(lang == 0);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return _snprintf_s(out, static_cast<size_t>(size), _TRUNCATE, "-\taccess fault while reading (caught)\t\t-\n");
    }
    g_pzAt = GetTickCount() | 1;
    int len = 0, need = 0;
    for (int i = 0; i < g_pzN; ++i) {
        const PzRow &r = g_pzRows[i];
        const char *name = r.name;
        while (*name == ' ') ++name;
        char line[400];
        const int w = _snprintf_s(line, sizeof(line), _TRUNCATE, "%s\t%s\t%s\t%s\n", name, r.state, r.count, r.arg[0] ? r.arg : "-");
        if (w < 0) continue;
        need += w;
        if (len + w < size) { memcpy(out + len, line, static_cast<size_t>(w) + 1); len += w; }
    }
    return need < size ? len : need + 1;
}
// ---- end of 0.22.31 page Kapitel group "Raetsel" ----

// ---- 0.22.47 bar: the sound monitor rows (a kQbSndMon row; the core in section "0.22.47 sound monitor") ----
// "voices" = every voice of the last list (playing first, then paused / starting / muted), "history" = the newest starts,
// "rules" = the active snd.mute rules + the sonar switch. A voice / start row: right = snd.mute w<id> 1 (its wave) or
// e<hex> 1 (its emitter when the wave is unknown), left = the same 0, X = toggle; a stream with neither: only its whole
// group (right twice). A rule row: left / right / X = that rule 0. Rows rebuilt every frame from the snapshot.
struct W7Row { int what; int wave, group; DWORD emitter, sid; char label[64]; };   // what 0 voice / start, 1 rule, 2 sonar
const int kW7RowMax = 128;
W7Row g_w7Rows[kW7RowMax];
int g_w7RowN = 0;
SnVoice g_w7QbVoices[kSnMax];                // render thread copy of the snapshot
W7Hist g_w7QbHist[kW7HistCap];
void W7QbReset() { g_w7RowN = 0; }
void W7Target(int wave, DWORD emitter, char *o, size_t n) {
    if (wave >= 0) Out(o, n, "w%d", wave);
    else if (emitter) Out(o, n, "e%lx", emitter);
    else o[0] = 0;
}
// muted by a rule now: the wave, its SoundPlex section, its emitter or the sonar switch (display only, render thread)
bool W7Muted(int wave, DWORD emitter, DWORD sid) {
    if (W7SonarMode() == 1 && W7SonarWave(wave)) return true;
    W6Rule r = {};
    if (wave >= 0) { r.kind = kW6Wave; r.value = static_cast<DWORD>(wave); if (W6Find(r) >= 0) return true; }
    if (sid) { r.kind = kW6Sound; r.value = sid; if (W6Find(r) >= 0) return true; }
    if (emitter) { r.kind = kW6Emitter; r.value = emitter; if (W6Find(r) >= 0) return true; }
    return false;
}
int W7QbRows(QbView *v, int max, const char *what, int depth, bool de) {
    g_w7BarAt = GetTickCount() | 1;          // SnTick keeps the list fresh while these rows are drawn
    int n = 0;
    auto view = [&](const char *name, const char *state, const char *count, ImU32 col, ImU32 stateCol, int square,
                    int slot) {
        if (n >= max) return;
        QbView &w = v[n++];
        memset(&w, 0, sizeof(w));
        strncpy_s(w.name, sizeof(w.name), name, _TRUNCATE);
        strncpy_s(w.state, sizeof(w.state), state, _TRUNCATE);
        strncpy_s(w.count, sizeof(w.count), count, _TRUNCATE);
        w.col = col;
        w.stateCol = stateCol;
        w.square = square;
        w.skip = slot < 0;                   // a label line: up / down pass over it
        w.src = slot >= 0 ? kQbSmSrc - slot : -1;
        w.depth = depth;
    };
    auto slotOf = [&](int kind, int wave, int group, DWORD emitter, DWORD sid, const char *label) {
        if (g_w7RowN >= kW7RowMax) return -1;
        W7Row &r = g_w7Rows[g_w7RowN];
        r.what = kind;
        r.wave = wave;
        r.group = group;
        r.emitter = emitter;
        r.sid = sid;
        strncpy_s(r.label, sizeof(r.label), label ? label : "", _TRUNCATE);
        return g_w7RowN++;
    };
    const ImU32 grey = IM_COL32(170, 170, 170, 255), red = IM_COL32(255, 120, 100, 255);
    char name[112], state[48], count[24];
    if (max <= 0) return 0;
    if (!g_w7Ok) {
        Out(name, sizeof(name), "-- %s %s", de ? "Ton-Monitor aus:" : "sound monitor off:", g_w7Why);
        view(name, "", "", grey, grey, 0, -1);
        return n;
    }
    if (!_stricmp(what, "voices")) {
        int count0 = 0, audible = 0;
        DWORD tick = 0;
        static W8Extra extras[kW8ExtraMax];  // 0.22.50 B: the used FMOD channels outside the pool
        int xn = 0, fmUsed = 0, fmPool = 0, fmExtra = 0;
        char slots[kMusicSlotCount][2][64];  // 0.22.50 B: the srmusic slots (current / requested), read here (memory)
        EnterCriticalSection(&g_snLock);
        count0 = g_snSnapN;
        audible = g_snSnapAudible;
        tick = g_snSnapTick;
        memcpy(g_w7QbVoices, g_snSnap, sizeof(SnVoice) * static_cast<size_t>(count0));
        xn = g_w8XSnapN;
        memcpy(extras, g_w8XSnap, sizeof(W8Extra) * static_cast<size_t>(xn));
        fmUsed = g_w8FmUsed;
        fmPool = g_w8FmPool;
        fmExtra = g_w8FmExtra;
        LeaveCriticalSection(&g_snLock);
        const DWORD age = tick ? (GetTickCount() - tick) / 1000 : 0;
        if (!tick) Out(name, sizeof(name), "-- %s", de ? "Aktive Stimmen: noch keine Liste (Spiel-Thread)"
                                                       : "Active voices: no list yet (game thread)");
        else Out(name, sizeof(name), de ? "-- Aktive Stimmen: %d, %d spielen%s" : "-- Active voices: %d, %d playing%s", count0,
                 audible, age >= 3 ? (de ? " (Stand alt)" : " (list old)") : "");
        view(name, "", "", kQbBlue, grey, 0, -1);
        if (tick && g_w8Ok) {                // 0.22.50 B: FMOD's own count (SystemI +0x150), not only the pool
            Out(name, sizeof(name), de ? "-- FMOD: %d Kan\303\244le belegt (%d Pool, %d fremd)"
                                       : "-- FMOD: %d channels used (%d pool, %d others)", fmUsed, fmPool, fmExtra);
            view(name, "", "", grey, grey, 0, -1);
        }
        if (tick) {                          // 0.22.51 W9: the game's reverb as its own row (output level, the sends now)
            int sends = 0, mutedSends = 0;
            float smax = 0.0f;
            for (int i = 0; i < count0; ++i) {
                const SnVoice &x = g_w7QbVoices[i];
                if (x.send <= 0.0f) continue;
                ++sends;
                if (x.fmMute) ++mutedSends;
                if (x.send > smax) smax = x.send;
            }
            W9RevRow(de, sends, mutedSends, smax, name, sizeof(name), state, sizeof(state));
            view(name, state, "", IM_COL32(150, 200, 255, 255), W9RevOutNow() > 0.0f && sends ? red : grey, 0, -1);
            // 0.22.52 W10: the whole DSP graph (walked from the FMOD target unit) and one row per effect
            static W10Fx fx[kW10FxMax];
            int fxn = 0, units = 0;
            LONG rins = -1;
            EnterCriticalSection(&g_snLock);
            fxn = g_w10FxN;
            memcpy(fx, g_w10Fx, sizeof(W10Fx) * static_cast<size_t>(fxn));
            units = g_w10Units;
            rins = g_w10RevIns;
            LeaveCriticalSection(&g_snLock);
            if (units) {
                Out(name, sizeof(name), de ? "-- DSP-Graph: %d Einheiten, %d Effekte; Hall-Eing\303\244nge %ld; Updates %ld/s "
                                             "(%ld Sends), sofort auf 0: %ld"
                                           : "-- DSP graph: %d units, %d effects; reverb inputs %ld; updates %ld/s (%ld "
                                             "sends), zeroed at once: %ld",
                    units, fxn, rins, g_w10Rate, g_w10RateVoices, g_w10Swept);
                view(name, "", "", grey, grey, 0, -1);
                for (int i = 0; i < fxn; ++i) {
                    const W10Fx &f = fx[i];
                    int voices = 0;
                    for (int k = 0; k < count0; ++k) voices += f.group >= 0 && g_w7QbVoices[k].group == f.group ? 1 : 0;
                    char into[24];
                    if (f.group >= 0) Out(into, sizeof(into), "g%d", f.group);
                    else Out(into, sizeof(into), "0x%08lx", f.into);
                    const bool isRev = !strcmp(f.name, "SFX Reverb");
                    Out(name, sizeof(name), de ? "-- DSP %s (%s): -> %s %.2f, %d Eing\303\244nge%s"
                                               : "-- DSP %s (%s): -> %s %.2f, %d inputs%s",
                        f.name, W10TypeName(f.type), into, static_cast<double>(f.mix), f.ins,
                        isRev ? (de ? " (Sends, umgeht Stumm)" : " (sends, bypasses mute)")
                              : (de ? " (Einschub hinter dem Stumm)" : " (insert behind the mute)"));
                    Out(state, sizeof(state), "%s", f.active ? (de ? "aktiv" : "active") : (de ? "inaktiv" : "inactive"));
                    Out(count, sizeof(count), de ? "%d Stimmen" : "%d voices", isRev ? sends : voices);
                    view(name, state, count, IM_COL32(150, 200, 255, 255), grey, 0, -1);
                }
            }
        }
        int shown = 0;
        // 0.22.53 W11: the same structure as the sound log trees - a heading per kind (kW8CatOrder), one per sub-group
        // (kW8Sub) inside it, then its voices (playing first); kinds / sub-groups without a voice are left out
        for (int ko = 0; ko < kW8Cats && shown < 24; ++ko) {
          const int kc = kW8CatOrder[ko];
          int inKind = 0, playKind = 0;
          for (int i = 0; i < count0; ++i)
              if (g_w7QbVoices[i].lcat == kc) { ++inKind; playKind += SnState(g_w7QbVoices[i]) == kSnStPlaying ? 1 : 0; }
          if (!inKind) continue;
          Out(name, sizeof(name), de ? "-- %s: %d, %d spielen" : "-- %s: %d, %d playing", de ? kW8CatDe[kc] : kW8CatEn[kc],
              inKind, playKind);
          view(name, "", "", kQbSound, grey, 0, -1);
          for (int sg = 0; sg < kW8Subs && shown < 24; ++sg) {
            if (kW8Sub[sg].cat != kc) continue;
            int inSub = 0;
            for (int i = 0; i < count0; ++i) inSub += g_w7QbVoices[i].lsub == sg ? 1 : 0;
            if (!inSub) continue;
            Out(name, sizeof(name), "--    %s (%s): %d", de ? kW8Sub[sg].de : kW8Sub[sg].en, kW8Sub[sg].groups, inSub);
            view(name, "", "", grey, grey, 0, -1);
            for (int pass = 0; pass < 2; ++pass)
            for (int i = 0; i < count0 && shown < 24; ++i) {
                const SnVoice &x = g_w7QbVoices[i];
                const int st = SnState(x);
                if (x.lsub != sg) continue;
                if ((pass == 0) != (st == kSnStPlaying)) continue;
                char nm[48];
                W7VoiceName(x.wave, x.cat, de, nm, sizeof(nm));
                char ids[32] = "";
                size_t used = 0;
                if (x.wave >= 0) LabelAdd(ids, sizeof(ids), &used, " w%d", x.wave);
                if (x.sid) LabelAdd(ids, sizeof(ids), &used, " s%lu", x.sid);
                Out(name, sizeof(name), "%s%s%s  <- %s", nm, ids, x.loop ? (de ? " (Schleife)" : " (loop)") : "", x.src);
                // 0.22.50 B: FMOD's own bits (ChannelI +0x74 bit 3 / real +0x68 0x20), not TruMenu's rule; the square as
                // every bool row of the bar: filled = audible, an outline = muted
                // 0.22.51 W9: audible incl. the game's reverb send (a muted voice whose send still reaches the reverb
                // shows "stumm, Hall 0.34" with a filled square)
                const bool muted = x.fmOk ? !x.aud : x.ours || W7Muted(x.wave, x.emitter, x.sid);
                const bool paused = x.fmOk && x.fmPause;
                char rev[48] = "";
                W9SendText(x.fmMute, x.send, de, rev, sizeof(rev));
                Out(state, sizeof(state), "%s g%d %s%s", x.fmMute && rev[0] ? rev + 2 : muted ? (de ? "stumm" : "muted")
                    : paused ? (de ? "pausiert" : "paused") : (de ? kSnStateDe : kSnStateEn)[st], x.group,
                    W7GroupName(x.group, de), !x.fmMute && rev[0] ? rev : "");
                if (x.dist >= 0.0f) Out(count, sizeof(count), "%.2f %.0fm", static_cast<double>(x.vol),
                                        static_cast<double>(x.dist / kW7UnitsPerMetre));
                else Out(count, sizeof(count), "%.2f %s", static_cast<double>(x.vol), x.dist < -1.5f ? "3D" : "2D");
                ImU32 c = kW7KindColour[x.kind];
                if (st != kSnStPlaying) c = (c & 0x00ffffff) | 0x90000000;
                const int at = n;
                view(name, state, count, c, muted ? red : grey, muted ? 2 : 1,
                     slotOf(0, x.wave, x.group, x.emitter, x.sid, nm));
                if (n > at) v[at].rev = 1 + x.rev;   // 0.22.52 W10: the reverb mark in front of the state
                ++shown;
            }
          }
        }
        if (count0 > shown) {
            Out(name, sizeof(name), de ? "-- ... %d weitere (snd.monitor = alle ins Log)" : "-- ... %d more (snd.monitor = all "
                "to the log)", count0 - shown);
            view(name, "", "", grey, grey, 0, -1);
        }
        // 0.22.50 B: the channels the pool never sees (oscillator / DSP) - right twice = their whole group (as a stream)
        for (int i = 0; i < xn && i < 8; ++i) {
            const W8Extra &x = extras[i];
            Out(name, sizeof(name), "%s%s", de ? "Fremdkanal (DSP)" : "foreign channel (DSP)",
                x.loop ? (de ? " (Schleife)" : " (loop)") : "");
            Out(state, sizeof(state), "%s g%d %s", x.mute ? (de ? "stumm" : "muted") : x.pause ? (de ? "pausiert" : "paused")
                : (de ? "spielt" : "playing"), x.group, W7GroupName(x.group, de));
            Out(count, sizeof(count), "%.2f", static_cast<double>(x.vol));
            view(name, state, count, IM_COL32(255, 170, 90, 255), x.mute ? red : grey, x.mute ? 2 : 1,
                 slotOf(0, -1, x.group, 0, 0, de ? "Fremdkanal (DSP)" : "foreign channel (DSP)"));
        }
        // 0.22.50 B: the music slots as rows of their own (name + state; srmusic slots +0 / +0x100 as SnMusicNames)
        for (int s = 0; g_musicOk && s < kMusicSlotCount; ++s) {
            const DWORD base = kMusicSlots + static_cast<DWORD>(s) * kMusicSlotSize;
            if (!ReadString(base, slots[s][0], sizeof(slots[s][0]))) slots[s][0][0] = 0;
            if (!ReadString(base + 0x100, slots[s][1], sizeof(slots[s][1]))) slots[s][1][0] = 0;
            if (!slots[s][0][0] && !slots[s][1][0] && !g_w6Stopped[s][0]) continue;
            const bool stopped = g_w6Stopped[s][0] != 0;
            Out(name, sizeof(name), "%s %d: %s", de ? "Musik-Slot" : "music slot", s,
                slots[s][0][0] ? slots[s][0] : slots[s][1][0] ? slots[s][1] : g_w6Stopped[s]);
            Out(state, sizeof(state), "%s", stopped ? (de ? "von TruMenu gestoppt" : "stopped by TruMenu")
                : g_sndMuteMusic ? (de ? "Musik aus (stumm)" : "music off (muted)")
                : slots[s][1][0] && _stricmp(slots[s][0], slots[s][1]) ? (de ? "startet" : "starting")
                : (de ? "l\303\244uft" : "playing"));
            view(name, state, "", kW7KindColour[kW7Music], stopped || g_sndMuteMusic ? red : grey, 0, -1);
        }
        return n;
    }
    if (!_stricmp(what, "history")) {
        int k = 0;
        EnterCriticalSection(&g_snLock);
        const int keep = g_w7HistN < g_w7HistMax ? g_w7HistN : g_w7HistMax;
        for (int i = 0; i < keep; ++i) g_w7QbHist[k++] = g_w7Hist[(g_w7HistHead - 1 - i + kW7HistCap) % kW7HistCap];
        LeaveCriticalSection(&g_snLock);
        Out(name, sizeof(name), de ? "-- Zuletzt gestartet (neueste oben): %d von %ld" : "-- Last started (newest on top): %d "
            "of %ld", k, g_w7HistTotal);
        if (!g_w7History) Out(name, sizeof(name), "-- %s", de ? "Verlauf aus ([Sound] History=0)" : "history off ([Sound] "
                                                                                                  "History=0)");
        view(name, "", "", kQbBlue, grey, 0, -1);
        for (int i = 0; i < k && i < 30; ++i) {
            const W7Hist &e = g_w7QbHist[i];
            char ids[32] = "";
            size_t used = 0;
            if (e.wave >= 0) LabelAdd(ids, sizeof(ids), &used, " w%d", e.wave);
            if (e.sid) LabelAdd(ids, sizeof(ids), &used, " s%lu", e.sid);
            Out(name, sizeof(name), "%s %s%s  <- %s", e.time, e.name, ids, e.src);
            const bool muted = e.fmMute || W7Muted(e.wave, e.emitter, e.sid);   // 0.22.50: FMOD's bit at the start too
            const int es = e.sub >= 0 && e.sub < kW8Subs ? e.sub : kW8sWoDefault;   // 0.22.53 W11: kind / sub-group
            Out(state, sizeof(state), "%s %s / %s g%d", muted ? (de ? "stumm," : "muted,") : "",
                de ? kW8CatDe[kW8Sub[es].cat] : kW8CatEn[kW8Sub[es].cat], de ? kW8Sub[es].de : kW8Sub[es].en, e.group);
            Out(count, sizeof(count), "%s", e.is3d ? "3D" : "2D");
            view(name, state, count, kW7KindColour[e.kind], muted ? red : grey, muted ? 2 : 1,   // 0.22.50: filled = audible
                 slotOf(0, e.wave, e.group, e.emitter, e.sid, e.name));
        }
        return n;
    }
    // "rules": the snd.mute rules (display: a benign read of the game thread's table) + the sonar switch
    const int sm = W7SonarMode();
    Out(name, sizeof(name), de ? "-- Aktive Ton-Regeln: %d%s" : "-- Active sound rules: %d%s", g_w6RuleN + (sm ? 1 : 0),
        g_w6SoloOn ? " + solo" : "");
    view(name, "", "", kQbBlue, grey, 0, -1);
    if (sm) {
        char ids[64] = "";
        size_t used = 0;
        for (int i = 0; sm == 1 && i < g_w7SonarN; ++i) LabelAdd(ids, sizeof(ids), &used, " w%d", g_w7SonarWaves[i]);
        Out(name, sizeof(name), "%s%s", sm == 1 ? (de ? "Sonar-Ton aus:" : "sonar sound off:") :
                                                  (de ? "Sonar: ganze Gruppe 57 aus" : "sonar: whole group 57 off"), ids);
        view(name, de ? "links = an" : "left = on", "SonarMute", kQbSound, red, 2,   // 0.22.50: an outline = muted
             slotOf(2, -1, sm == 1 ? 0 : kW7SonarGroup, 0, 0, sm == 1 ? "snd.sonar" : "snd.sonar57"));
    }
    for (int i = 0; i < g_w6RuleN && i < kW6RuleMax; ++i) {
        char t[72];
        W6RuleText(g_w6Rules[i], t, sizeof(t));
        Out(name, sizeof(name), "%s %s", de ? "Regel" : "rule", t);
        if (g_w6Rules[i].kind == kW6Wave && W7WaveName(static_cast<int>(g_w6Rules[i].value)))
            Out(name, sizeof(name), "%s %s (%s)", de ? "Regel" : "rule", t, W7WaveName(static_cast<int>(g_w6Rules[i].value)));
        view(name, de ? "links = an" : "left = on", "", kQbSound, red, 2, slotOf(1, -1, 0, 0, 0, t));
    }
    if (!g_w6RuleN && !sm) view(de ? "-- keine" : "-- none", "", "", grey, grey, 0, -1);
    return n;
}
void W7QbAct(int slot, int dir) {
    const bool de = g_qbLang == 0;
    if (slot < 0 || slot >= g_w7RowN) return;
    const W7Row r = g_w7Rows[slot];
    char arg[96], t[32];
    if (r.what == 1) {                       // a rule row: off
        Out(arg, sizeof(arg), "%s 0", r.label);
        QbRun("Ton", "Regel", r.label, "snd.mute", arg);
        return;
    }
    if (r.what == 2) {                       // the sonar switch row: off
        QbRun("Ton", "Sonar", r.label, r.label, "0");
        return;
    }
    W7Target(r.wave, r.emitter, t, sizeof(t));
    if (!t[0]) {                             // a stream without wave / emitter: only its whole group, right twice
        if (r.group <= 0 || dir < 0) {
            QbResult(false, de ? "Strom ohne Welle / Emitter - nur ganze Gruppe g%d (rechts 2x)"
                               : "stream without wave / emitter - only its whole group g%d (right twice)", r.group);
            return;
        }
        char key[48], what[96];
        Out(key, sizeof(key), "snd.mute g%d", r.group);
        Out(what, sizeof(what), de ? "ganze Gruppe g%d %s stumm" : "whole group g%d %s muted", r.group,
            W7GroupName(r.group, de));
        if (!QbConfirm(key, r.label, what)) return;
        Out(arg, sizeof(arg), "g%d 1", r.group);
        QbRun("Ton", "Monitor", r.label, "snd.mute", arg);
        return;
    }
    const bool on = dir == kQbXDir ? !W7Muted(r.wave, r.emitter, r.sid) : dir > 0;
    if (!on && W7SonarMode() == 1 && W7SonarWave(r.wave)) {
        QbResult(false, "%s", de ? "von 'Sonar-Ton aus' stumm - dort ausschalten" : "muted by 'sonar sound off' - switch it "
                                                                                    "off there");
        return;
    }
    Out(arg, sizeof(arg), "%s %d", t, on ? 1 : 0);
    QbRun("Ton", "Monitor", r.label, "snd.mute", arg);
}
// the long menu (big window): the same rows as text with a button each (mouse: one click = mute / on)
void W7MenuRows(const char *what, int page, int index) {
    static QbView rows[64];
    const bool de = g_qbLang == 0;
    W7QbReset();
    const int k = W7QbRows(rows, 64, what, 0, de);
    for (int i = 0; i < k; ++i) {
        const QbView &w = rows[i];
        if (w.src > kQbSmSrc) { ImGui::TextDisabled("   %s", w.name); continue; }
        const int slot = kQbSmSrc - w.src;
        char label[64];
        const bool muted = w.square == 2;     // 0.22.50: filled = audible, an outline = muted (as every bool row)
        Out(label, sizeof(label), "%s###w7m%d_%d_%d", muted ? (de ? "an" : "on") : (de ? "stumm" : "mute"), page, index, i);
        if (TmButton(label)) W7QbAct(slot, muted ? -1 : 1);
        ImGui::SameLine();
        ImGui::TextColored(ImGui::ColorConvertU32ToFloat4(w.col), "%s   %s   %s", w.name, w.state, w.count);
    }
}
// ---- end of 0.22.47 bar ----

// 0.21.8 favourites with an argument: the item + argument a special row stands for (page Fixes switch = sw.set <switch>,
// costume list row = costume.set <object id>, chapter unit = level.load <unit>); false = not pinnable (groups, choosers,
// positions / checkpoints / saves rows)
bool QbDynFav(int k, char *id, size_t idN, char *arg, size_t argN) {
    if (k < 0 || k >= g_qbDynN) return false;
    const QbDyn &q = g_qbDyn[k];
    if (q.kind == kQdSw) {
        bool ok = false;
        EnterCriticalSection(&g_swLock);
        const int i = static_cast<int>(q.intro);
        if (i >= 0 && i < g_swN) { Out(id, idN, "sw.set"); Out(arg, argN, "%s", g_sw[i].target + 4); ok = true; }
        LeaveCriticalSection(&g_swLock);
        return ok && FavArgOk(arg);
    }
    if (q.kind == kQdCos) {
        Out(id, idN, "costume.set");
        Out(arg, argN, "%ld", q.intro);
        return true;
    }
    if (q.kind == kQdChap && q.intro >= 0 && q.intro < kQbViewMax && !UnitNameNoDrm(q.unit)) {   // 0.21.9: not without a DRM
        Out(id, idN, "level.load");
        Out(arg, argN, "%s", g_chapRow[q.intro].arg);
        return FavArgOk(arg);
    }
    return false;
}
bool QbDynIsSw(int k) { return k >= 0 && k < g_qbDynN && g_qbDyn[k].kind == kQdSw; }

// ---- 0.21.7 help line / Y hint (TODO "kurze Hilfe-Zeile zum gewaehlten Punkt", "Y: -" on rows that refuse Y) ----
// the bar row behind the selected view: a static row, a favourite / recent row of page 0, "Naechstes Kostuem"; nullptr
// for every other special row (positions, checkpoints, saves, Tests, Fixes, costumes)
const QbRow *QbSelRow(int page, int sel) {
    if (page < 0 || page >= kQbPageN || sel < 0 || sel >= g_qbViewN) return nullptr;
    const QbPage &p = kQbPages[page];
    const int src = g_qbView[sel].src;
    if (src >= 0) return src < p.n ? &p.rows[src] : nullptr;
    return p.special ? QbSpecialRow(sel - g_qbStaticN) : nullptr;
}
// 0.22.51 (e): the selected row is a value row (X = its default): kQbValue, or an int / choice switch (a kQbSwitch row,
// a page Fixes row, a pinned switch on page 0)
bool QbSelIsValue(int page, int sel) {
    if (page < 0 || page >= kQbPageN || sel < 0 || sel >= g_qbViewN || g_qbView[sel].src <= kQbSmSrc) return false;
    const QbRow *r = QbSelRow(page, sel);
    int i = -1;
    bool value = false;
    EnterCriticalSection(&g_swLock);
    if (r) {
        if (r->kind == kQbValue) value = true;
        else if (r->kind == kQbSwitch) i = SwFindLocked(r->arg);
    } else if (QbDynIsSw(sel - g_qbStaticN)) {
        i = static_cast<int>(g_qbDyn[sel - g_qbStaticN].intro);
    }
    if (i >= 0 && i < g_swN) value = g_sw[i].type != kSwBool;
    LeaveCriticalSection(&g_swLock);
    return value;
}
// the selected row's help line (one language, kQbHelpMax characters): kQbHelp for item rows, the hint column of
// TruMenu.switches.txt on page Fixes, the costume rows' own lines (a refused entry says why); false = no help
bool QbHelpLine(int page, int sel, bool de, char *o, size_t n) {
    o[0] = 0;
    if (page < 0 || page >= kQbPageN || sel < 0 || sel >= g_qbViewN) return false;
    const QbRow *r = QbSelRow(page, sel);
    if (r) {
        if (r->kind == kQbCheck) {           // 0.22.28 (TP)
            Out(o, n, "%s", de ? "rechts OK, links Fehler, X \303\274bersprungen, nochmal = offen"
                               : "right ok, left fail, X skipped, again = open");
            return true;
        }
        if (r->kind == kQbSwitch) {          // 0.22.28 (TP): the hint column of TruMenu.switches.txt, as page Fixes
            EnterCriticalSection(&g_swLock);
            const int i = SwFindLocked(r->arg);
            if (i >= 0) Out(o, n, "%s", de ? g_sw[i].hint : g_sw[i].hintEn);
            LeaveCriticalSection(&g_swLock);
            return o[0] != 0;
        }
        if (r->kind == kQbNote) return false;
        if (!_stricmp(r->id, "power.infinite")) {   // 0.22.19: a greyed row says why (plugin / version / INI missing)
            const char *why = PiWhy();
            if (why[0]) { Out(o, n, "%s", why); return true; }
        }
        const char *t = QbHelpText(r->id, r->arg);
        if (!t) return false;
        QbHelpPart(t, de, o, n);
        return o[0] != 0;
    }
    const int k = sel - g_qbStaticN;
    if (k < 0 || k >= g_qbDynN) return false;
    const QbDyn &q = g_qbDyn[k];
    if (q.kind == kQdSw) {                   // page Fixes: "<DE> // <EN>" of the file
        EnterCriticalSection(&g_swLock);
        const int i = static_cast<int>(q.intro);
        if (i >= 0 && i < g_swN) Out(o, n, "%s", de ? g_sw[i].hint : g_sw[i].hintEn);
        LeaveCriticalSection(&g_swLock);
        return o[0] != 0;
    }
    if (q.kind == kQdChap || q.kind == kQdChapCp || q.kind == kQdChapGcp)   // 0.21.7 page Kapitel (0.21.9 / 0.22.69: + CP)
        return ChapHelp(q, de, o, n);
    if (q.kind == kQdPz) {                   // 0.22.31 (Q106)
        Out(o, n, "%s", q.arg[0] ? (de ? "Cheat: Gelenk ins Ziel, das Spiel l\303\266st selbst aus" : "Cheat: joint into the "
                                         "target, the game itself fires")
                                 : (de ? "Uber-Objekt in der N\303\244he: Zustand, nur Anzeige" : "Uber object nearby: state, "
                                         "list only"));
        return true;
    }
    const char *t = nullptr;
    switch (q.kind) {
    case kQdCosPick: t = de ? "Kost\303\274m live wechseln, ohne die Unit neu zu laden" : "Switch the costume live, no unit reload";
        break;
    case kQdCosRec: t = de ? "Kost\303\274m f\303\274rs n\303\244chste Laden w\303\244hlen; l\303\244dt die Unit neu"
                           : "Choose the costume for the next load; reloads the unit"; break;
    case kQdCos: {
        char block[120];                     // 0.22.55
        if (CosBlocked(static_cast<int>(q.intro), de, block, sizeof(block))) { Out(o, n, "%s", block); return true; }
    }
        t = CosOffered(static_cast<WORD>(q.intro)) == 0
                ? (de ? "Vom Spiel abgelehnt (Pr\303\274fung 0x5c54e0, keine .drm?)" : "Refused by the game's check (no .drm?)")
                : (de ? "Dieses Kost\303\274m jetzt anziehen (live)" : "Wear this costume now (live)");
        break;
    default: return false;
    }
    Out(o, n, "%s", t);
    return true;
}
// ---- end of 0.21.7 help line ----
int QbSpecialBuild(int special, int base, bool de) {
    const int max = kQbViewMax - base;
    g_qbDynN = 0;
    if (max <= 0) return 0;
    int n = 0;
    if (special == kQsFav) n = QbFavRows(g_qbView + base, g_qbDyn, max, de);           // 0.21.1
    else if (special == kQsTests) n = QbTestsRows(g_qbView + base, g_qbDyn, max, de);
    else if (special == kQsSwitches) n = QbSwRows(g_qbView + base, g_qbDyn, max, de);   // 0.21.5
    else if (special == kQsCostume) n = QbCosRows(g_qbView + base, g_qbDyn, max, de);   // 0.21.6
    else if (special == kQsChapters) n = QbChapRows(g_qbView + base, g_qbDyn, max, de);   // 0.21.7
    if (special == kQsLara) n = QbFigRows(g_qbView + base, g_qbDyn, max, de);   // 0.22.16: positions + switch groups
    else if (special == kQsCheckpoints) n = QbCpPageRows(g_qbView + base, g_qbDyn, max, de);
    else if (special == kQsSaves) n = QbSavesRows(g_qbView + base, g_qbDyn, max, de);
    g_qbDynN = n;
    return n;
}
const QbRow *QbSpecialRow(int row) {         // 0.21.3: X / Y on page 0 act on the favourite / recent row itself
    if (row >= 0 && row < g_qbDynN && g_qbDyn[row].kind == kQdCosNext) return &kQbCosNext;   // 0.21.6
    if (row < 0 || row >= g_qbDynN || g_qbDyn[row].kind != kQdItem) return nullptr;
    const int k = static_cast<int>(g_qbDyn[row].intro);
    return k >= 0 && k < kQbViewMax ? &g_qbFavRow[k] : nullptr;
}
void QbSpecialAct(int special, int row, int dir) {
    (void)special;
    const bool de = g_qbLang == 0;
    if (row < 0 || row >= g_qbDynN) return;
    const QbDyn &q = g_qbDyn[row];
    char arg[96], key[160];
    switch (q.kind) {
    case kQdItem:                            // 0.21.1 page 0: the favourite / recent row as its bar row
        if (q.intro >= 0 && q.intro < kQbViewMax) QbActRow(0, g_qbFavRow[q.intro], dir);
        return;
    case kQdPrepare: {                       // 0.21.1 page Tests: the regression shortcut, right twice
        if (dir < 0) { QbResult(false, "%s", de ? "rechts 2x = vorbereiten" : "right 2x = prepare"); return; }
        Out(key, sizeof(key), "prepare %s", q.arg);
        if (!QbConfirm(key, q.arg, de ? "l\303\244dt / teleportiert (Story-Werte?)" : "loads / teleports (story values?)")) return;
        char o[300];
        const bool ok = RunRegressPrepare(q.arg, o, sizeof(o));
        SetLastAction("regress.prepare", ok, o);
        ++g_qbRuns;
        Log(1, "quick: Tests / Prepare %s: %s%s", q.arg, ok ? "" : "err ", o);
        QbResult(!ok, "Prepare %s: %s", q.arg, o);
        return;
    }
    case kQdStop: {
        char o[200];
        const bool ok = RunRegressPrepare("stop", o, sizeof(o));
        SetLastAction("regress.prepare", ok, o);
        QbResult(!ok, "%s", o);
        return;
    }
    case kQdTodo: {                          // 0.21.1 page Tests: TO TEST state as the ring's OK / Fail / Done / toggle
        const bool toggle = !strcmp(q.unit, "toggle"), step = !strcmp(q.unit, "step");
        const char *state = toggle ? (dir > 0 ? "on" : "off") : step ? (dir > 0 ? "done" : "open") : (dir > 0 ? "ok" : "fail");
        TestMarkFromMenu(q.arg, state);
        Log(1, "quick: Tests / TO TEST %s -> %s", q.arg, state);
        QbResult(false, "%s", g_lastAction);
        return;
    }
    case kQdSwGroup:                         // 0.21.5 page Fixes
    case kQdSw:
        QbSwAct(q, dir);
        return;
    case kQdFigGroup:                        // 0.22.16 page Figur (0.22.18: the planned row is a real switch now)
        QbFigAct(q, dir);
        return;
    case kQdCosPick:                         // 0.21.6 page Kostueme
    case kQdCosNext:
    case kQdCosRec:
    case kQdCosGroup:
    case kQdCos:
        QbCosAct(q, dir);
        return;
    case kQdChapGroup:                       // 0.21.7 page Kapitel (X = kQbXDir: a group toggles, a unit = right)
    case kQdChap:
    case kQdChapCp:                          // 0.21.9: a checkpoint of the open unit (cp.jump)
    case kQdChapGcp:                         // 0.22.69 (B4 1): chapter.cp of the open unit
        QbChapAct(q, dir);
        return;
    case kQdPz:                              // 0.22.31 (Q106): a puzzle row of the group Raetsel
        QbPzAct(q, dir);
        return;
    case kQdPos:
        if (dir < 0) { QbResult(false, "%s", de ? "rechts = hin" : "right = go"); return; }
        if (q.loaded) { QbRun("Lara", "position", q.arg, "pos.go", q.arg); return; }
        Out(key, sizeof(key), "pos.goload %s", q.arg);
        {
            char lara[48], what[160];
            PosLaraUnit(lara, sizeof(lara));
            Out(what, sizeof(what), de ? "Unit %s nicht geladen (Lara in %s) - l\303\244dt sie (Story-Werte?)"
                                       : "unit %s not loaded (Lara in %s) - loads it (story values?)", q.unit, lara[0] ? lara : "-");
            if (!QbConfirm(key, q.arg, what)) return;
        }
        QbRun("Lara", "position", q.arg, "pos.goload", q.arg);
        return;
    case kQdCpActive:
        if (dir < 0) { QbResult(false, "%s", de ? "rechts 2x = hin" : "right 2x = go"); return; }
        if (!QbConfirm("dbg.cpgo active", de ? "Aktiver Checkpoint" : "Active checkpoint", nullptr)) return;
        QbRun("Checkpoints", "active", de ? "Aktiver Checkpoint" : "Active checkpoint", "dbg.cpgo", "active");
        return;
    case kQdCpAll:
        QbRun("Checkpoints", "all", de ? "Alle Marker" : "All markers", "dbg.cpall", dir > 0 ? "1" : "0");
        return;
    case kQdCp:
        Out(arg, sizeof(arg), "%ld", q.intro);
        if (dir < 0) {                       // left = marker on <-> off
            Out(arg, sizeof(arg), "%ld %d", q.intro, q.loaded ? 0 : 1);
            QbRun("Checkpoints", "marker", "CP", "dbg.cp", arg);
            return;
        }
        Out(key, sizeof(key), "dbg.cpgo %ld", q.intro);
        if (!QbConfirm(key, "CP", de ? "Fliegen an + hin" : "flight on + go")) return;
        QbRun("Checkpoints", "go", "CP", "dbg.cpgo", arg);
        return;
    case kQdBackupNow:
        if (dir < 0) return;
        QbRun("Saves", "backup", de ? "Sichern" : "Backup", "save.backup", "");
        return;
    case kQdRescan:
        if (dir < 0) return;
        SaveScan(true);
        QbResult(false, "%s", de ? "Liste neu gelesen" : "list re-read");
        return;
    case kQdSave:
        if (dir < 0) { QbResult(false, "%s", de ? "rechts 2x (10 s) = laden" : "right 2x (10 s) = load"); return; }
        QbRun("Saves", "load", q.arg, "save.load", q.arg);
        return;
    case kQdBackup:
        if (dir < 0) { QbResult(false, "%s", de ? "rechts 2x (10 s) = zur\303\274ckspielen" : "right 2x (10 s) = restore"); return; }
        QbRun("Saves", "restore", q.arg, "save.restore", q.arg);
        return;
    default:
        return;
    }
}

// menu (Debug view page, render thread): the checkpoint list and the positions
void PageCpPos() {
    char o[400];
    if (ImGui::TreeNodeEx("Checkpoints (0.17) / Checkpoint-Liste###cplist", ImGuiTreeNodeFlags_DefaultOpen)) {
        if (!g_dvCpOk) ImGui::TextWrapped("checkpoints off: %s", g_dvCpWhy);
        int total = 0;
        g_cpRowN = CpCollect(g_cpRows, kCpMax, true, &total);
        bool layer = g_dvOn[kDvCheckpoints] != 0;
        if (TmCheckbox("layer / Ebene  [dbg.checkpoints]###cplayer", &layer)) DvSet(kDvCheckpoints, layer, "menu", o, sizeof(o));
        ImGui::SameLine();
        if (TmButton("all on / alle an  [dbg.cpall 1]###cpallon")) RunDvCpAll("1", o, sizeof(o));
        ImGui::SameLine();
        if (TmButton("all off / alle aus  [dbg.cpall 0]###cpalloff")) RunDvCpAll("0", o, sizeof(o));
        ImGui::Text("%d checkpoint(s) in the loaded units, nearest first; %d hidden", total, CpHiddenCount());
        for (int i = 0; i < g_cpRowN; ++i) {
            const CpRow &r = g_cpRows[i];
            char text[128], id[48], arg[32];
            CpRowText(r, false, text, sizeof(text));
            bool show = !r.hidden;
            Out(id, sizeof(id), "%s###cpr%ld", text, r.intro);
            if (TmCheckbox(id, &show)) { Out(arg, sizeof(arg), "%ld %d", r.intro, show ? 1 : 0); RunDvCp(arg, o, sizeof(o)); }
            ImGui::SameLine();
            Out(id, sizeof(id), "go to / hin###cpg%ld", r.intro);
            if (TmButton(id)) { Out(arg, sizeof(arg), "%ld", r.intro); RunDvCpGo(arg, o, sizeof(o)); }
        }
        ImGui::TreePop();
    }
    if (ImGui::TreeNodeEx("Positions (0.17) / Positionen###poslist", ImGuiTreeNodeFlags_DefaultOpen)) {
        if (!g_posOk) ImGui::TextWrapped("positions off: %s", g_posWhy);
        static char name[40] = "";
        ImGui::InputText("name###posname", name, sizeof(name));
        ImGui::SameLine();
        if (TmButton("save here / hier merken  [pos.save]###possave")) RunPosSave(name, o, sizeof(o));
        static PosRow rows[kPosMax];
        static DWORD loaded = 0;
        static int count = 0;
        if (GetTickCount() - loaded > 1000) { count = PosLoad(rows, kPosMax); loaded = GetTickCount(); }   // the file, 1 / s
        float shift[3], origin[3];
        for (int i = count - 1; i >= 0; --i) {   // newest first
            const PosRow &r = rows[i];
            bool loadedUnit = PosUnitFrame(r.unit, shift, origin);
            char id[96];
            if (loadedUnit) {
                Out(id, sizeof(id), "go / hin###posg%d", i);
                if (TmButton(id)) InvokeCore("pos.go", r.name, false);
            } else {                             // 0.18: load the unit first (level.load), then flight + pos.go
                Out(id, sizeof(id), "load + go / laden + hin###posgl%d", i);
                if (TmButton(id)) InvokeCore("pos.goload", r.name, false);
            }
            ImGui::SameLine();
            ImGui::TextColored(loadedUnit ? ImVec4(0.6f, 1.0f, 0.6f, 1.0f) : ImVec4(0.7f, 0.7f, 0.7f, 1.0f), "%s  [%s%s]  %.0f %.0f "
                               "%.0f  %s", r.name, r.unit, loadedUnit ? "" : ", not loaded", r.p[0], r.p[1], r.p[2], r.saved);
        }
        ImGui::TreePop();
    }
}
void PosCheck() {
    DWORD at = 0;
    static char why[96];
    g_posOk = g_unitOk && g_playerOk && DvChecks(kPosChecks, sizeof(kPosChecks) / sizeof(kPosChecks[0]), &at);
    if (!g_unitOk) Out(why, sizeof(why), "stream unit table check (0.2) failed");
    else if (!g_playerOk) Out(why, sizeof(why), "player pointer check failed");
    else Out(why, sizeof(why), "unit frame code differs at 0x%08lx", at);
    g_posWhy = g_posOk ? "ok" : why;
    char path[MAX_PATH];
    PosPath(path, sizeof(path));
    Log(g_posOk ? 1 : 0, "0.17 checkpoint list: %d marker(s) hidden ([Debug] CheckpointHide); positions: %s, file %s",
        CpHiddenCount(), g_posWhy, path);
}

// dbg.depthdump (0.17, depth section above: DpDumpCall / DpTick)
void ValDpDump(char *o, size_t n) {
    if (g_dpDumpFrame >= 0) Out(o, n, "pending: frame %ld", static_cast<LONG>(g_dpDumpFrame));
    else Out(o, n, "idle (last dump: %d scene call(s))", g_dpDumpCount);
}
bool RunDpDump(const char *, char *o, size_t n) {
    if (!DvGate("dbg.depthdump", o, n)) return false;
    if (!g_dpMode) { Out(o, n, "switch dbg.depth on / dim first - the PCScene::Draw hook runs only then"); return false; }
    if (!DvAnyOn()) { Out(o, n, "switch a debug view layer on first - the PCScene::Draw hook runs only then"); return false; }
    if (g_dpDumpFrame >= 0) { Out(o, n, "a dump is pending (frame %ld)", static_cast<LONG>(g_dpDumpFrame)); return false; }
    g_dpDumpCount = 0;
    InterlockedExchange(&g_dpDumpFrame, g_dpFrame + 1);
    Log(1, "dbg.depthdump: frame %ld requested (DepthCall %d, src=%s)", static_cast<LONG>(g_dpDumpFrame), g_dpCall,
        ShotSource("dbg.depthdump"));
    Out(o, n, "dump of frame %ld requested - TruMenu.log '0.17 depthdump' lines", static_cast<LONG>(g_dpDumpFrame));
    return true;
}

// load (Start, after the 0.10.2 cinematic check): the byte checks of precheck_017.txt and the row table against kItems
void QuickCheck() {
    DWORD camAt = 0, cineAt = 0;
    g_ocCamOk = g_camLogOk && DvChecks(kOcCamChecks, sizeof(kOcCamChecks) / sizeof(kOcCamChecks[0]), &camAt);
    g_ocCineOk = g_cineOk && DvChecks(kOcCineChecks, sizeof(kOcCineChecks) / sizeof(kOcCineChecks[0]), &cineAt);
    char camText[64], cineText[64];
    if (g_ocCamOk) Out(camText, sizeof(camText), "ok");
    else if (!g_camLogOk) Out(camText, sizeof(camText), "failed (0.8 camera log check)");
    else Out(camText, sizeof(camText), "failed at 0x%08lx", camAt);
    if (g_ocCineOk) Out(cineText, sizeof(cineText), "ok");
    else if (!g_cineOk) Out(cineText, sizeof(cineText), "failed (0.10.2 check)");
    else Out(cineText, sizeof(cineText), "failed at 0x%08lx", cineAt);
    int rows = 0, unknown = 0;
    int planned = 0;
    for (const QbPage &p : kQbPages)
        for (int i = 0; i < p.n; ++i) {
            if (p.rows[i].kind == kQbLabel || p.rows[i].kind == kQbPlanned || p.rows[i].kind == kQbNote ||
                p.rows[i].kind == kQbGroup) {   // 0.18: no item (0.22.18: group headings too - were 29 "unknown";
                                                // 0.22.28: the TP hint lines)
                planned += p.rows[i].kind == kQbPlanned ? 1 : 0;
                continue;
            }
            ++rows;
            if (!FindItem(p.rows[i].id)) {
                ++unknown;
                Log(0, "0.17 quick toggles: row '%s' names the unknown item %s", p.rows[i].de, p.rows[i].id);
            }
        }
    char combo[48];
    QbComboText(g_qbButtons, combo, sizeof(combo));
    Log(g_ocCamOk && g_ocCineOk && !unknown ? 1 : 0, "0.17 quick toggles: [Quick] Enabled %d, OpenButtons 0x%04x (%s), "
        "ChordMs %d, ShowClosed %d, Language %s, Top %d%%, Scale %.2f; %d pages (0.18), %d item rows + %d planned, %d "
        "unknown item(s); cutscene shots: camera checks %s, cinematic test %s, [Shot] OnCine %ld (up to %d pairs per "
        "segment: %d every %d ms, then every %d ms; signal %s; segments %d)", g_qbEnabled, g_qbButtons, combo, g_qbChordMs,
        g_qbShowClosed, g_qbLang ? "en" : "de", g_qbTop, g_qbScale, kQbPageN, rows, planned, unknown, camText, cineText,
        static_cast<LONG>(g_ocOn), g_ocPairs, g_ocFastPairs, g_ocIntervalMs, g_ocSlowMs, OcSignalName(g_ocSignal),
        g_ocSegments);
}

